def match_finding_to_catalog(vuln_type, evidence=""):
    """Match a scanner finding to a catalog entry by keywords.
    Returns the catalog entry dict or None if no match.
    """
    if not vuln_type:
        return None
    vuln_lower = vuln_type.lower()
    evidence_lower = (evidence or "").lower()
    text = vuln_lower + " " + evidence_lower
    best_match = None
    best_score = 0
    for entry in VULN_CATALOG:
        score = 0
        for kw in entry.get("keywords", []):
            kw_lower = kw.lower()
            if kw_lower in text:
                score += len(kw_lower)  # longer keywords score higher
        if score > best_score:
            best_score = score
            best_match = entry
    return best_match if best_score > 0 else None



