def get_user_extra_sources():
    """Load user-added sources from env vars."""
    http_extra = []
    socks4_extra = []
    socks5_extra = []
    
    # Method 1: Single file with all sources
    sources_file = os.environ.get("BUGBOUNTY_PROXY_SOURCES_FILE")
    if sources_file and os.path.exists(sources_file):
        try:
            with open(sources_file, encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    # Try to detect protocol from URL
                    lower = line.lower()
                    if "socks4" in lower:
                        socks4_extra.append(("user-src", line))
                    elif "socks5" in lower:
                        socks5_extra.append(("user-src", line))
                    else:
                        http_extra.append(("user-src", line))
        except OSError as e:
            try:
                print(f"{C.YELLOW}[!] cannot read sources file: {e}{C.RESET}")
            except Exception:
                print(f"[!] cannot read sources file: {e}")
    
    # Method 2: Comma-separated env vars
    http_env = os.environ.get("BUGBOUNTY_EXTRA_HTTP_SOURCES", "")
    if http_env:
        for url in http_env.split(","):
            url = url.strip()
            if url:
                http_extra.append(("user-http", url))
    
    socks4_env = os.environ.get("BUGBOUNTY_EXTRA_SOCKS4_SOURCES", "")
    if socks4_env:
        for url in socks4_env.split(","):
            url = url.strip()
            if url:
                socks4_extra.append(("user-socks4", url))
    
    socks5_env = os.environ.get("BUGBOUNTY_EXTRA_SOCKS5_SOURCES", "")
    if socks5_env:
        for url in socks5_env.split(","):
            url = url.strip()
            if url:
                socks5_extra.append(("user-socks5", url))
    
    return http_extra, socks4_extra, socks5_extra



