    def nmap_smb_scan(self):
        """Nmap SMB enumeration."""
        nmap = self._paths.get("nmap")
        if not nmap:
            return {"error": "nmap not installed"}
        cmd = [
            nmap, "-p", "445", "--script",
            "smb-enum-shares,smb-enum-users,smb-enum-groups,smb-enum-domains,"
            "smb-os-discovery,smb-vuln*,smb2-security-mode,smb2-capabilities,"
            "smb-mbenum,smb-protocols,smb2-enum-sessions",
            "--script-args", "unsafe=1,smbdomain=WORKGROUP",
            "-Pn", "-T4", self.host,
        ]
        r = self._run(cmd, timeout=900)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Highlight null sessions / anonymous access
        if "READ" in out and "WRITE" in out:
            self._write_result("SMB Anonymous Read+Write Access",
                               "Anonymous SMB shares with READ+WRITE found!",
                               "CRITICAL")
        elif "READ" in out:
            self._write_result("SMB Anonymous Read Access",
                               "Anonymous SMB share read access.", "HIGH")
        # Known SMB vulns
        for vuln in ("ms17-010", "ms08-067", "cve-2017-7494",
                     "cve-2020-0796", "ms06-040"):
            if vuln in out.lower():
                self._write_result(f"SMB Vulnerability: {vuln}",
                                   "SMB is vulnerable to " + vuln, "CRITICAL")
        self._write_result("Nmap SMB Scan", out, "HIGH")
        return r

    def nmap_ssl_scan(self):
        """Nmap SSL/TLS audit scripts."""
        nmap = self._paths.get("nmap")
        if not nmap:
            return {"error": "nmap not installed"}
        cmd = [
            nmap, "-p", "443", "--script",
            "ssl-enum-ciphers,ssl-cert,ssl-known-key,ssl-poodle,"
            "ssl-drown,ssl-ccs-injection,ssl-heartbleed,sslv2,sslv2-drown,"
            "ssl-cert-integrity,ssl-cert-subject",
            "-Pn", "-T4", self.host,
        ]
        r = self._run(cmd, timeout=900)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Heartbleed
        if "heartbleed" in out.lower():
            self._write_result("OpenSSL Heartbleed (CVE-2014-0160)",
                               out, "CRITICAL")
        # POODLE
        if "poodle" in out.lower() and "vulnerable" in out.lower():
            self._write_result("SSL POODLE Vulnerability", out, "HIGH")
        # DROWN
