            "--enumerate", "vt",   # Vulnerable themes
            "--plugins-detection", "aggressive",
            "--themes-detection", "aggressive",
            "--passwords", "/usr/share/wordlists/rockyou.txt",
            "--usernames", "admin",
            "--password-attack", "xmlrpc",
