        out = r.get("stdout", "") + r.get("stderr", "")
        if os.path.exists(out_file):
            try:
                import json
                with open(out_file) as f:
                    j = json.load(f)
                # Highlight findings
                for finding in (j.get("version", {}).get("interesting_findings", []) or []):
                    self._write_result("WPScan — Interesting Finding",
                                       json.dumps(finding), "HIGH")
                for plug, data in (j.get("plugins", {}) or {}).items():
                    vulns = data.get("vulnerabilities", []) or []
                    if vulns:
                        for v in vulns:
                            self._write_result(
                                f"WPScan — Vulnerable Plugin: {plug}",
                                json.dumps(v), "CRITICAL")
            except Exception:
                pass
        self._write_result("WPScan Full", out, "HIGH")
