    # ════════════════════════════════════════════════════════════════
    # 7. SMBCLIENT — SMB enumeration (null session, shares)
    # ════════════════════════════════════════════════════════════════

    def smb_null_session(self):
        """Try anonymous/null session to SMB."""
        smb = self._paths.get("smbclient")
        if not smb:
            return {"error": "smbclient not installed"}
        # Try null session
        cmd = [smb, "-L", f"//{self.host}/", "-N", "-c", "allinfo"]
        r = self._run(cmd, timeout=120)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Disk" in out or "share" in out.lower():
            self._write_result("SMB Null Session — Shares Listed",
                               out, "CRITICAL")
        # Try guest
        cmd = [smb, f"//{self.host}/IPC$", "-U", "guest%", "-N", "-c",
               "allinfo"]
        r = self._run(cmd, timeout=60)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "NT_STATUS" not in out or "SUCCESS" in out.upper():
            self._write_result("SMB Guest Login",
                               "Guest login successful!", "HIGH")
        return r

    def smb_version_scan(self):
        """SMB version scan with msfconsole or nmap."""
        nmap = self._paths.get("nmap")
        if nmap:
            cmd = [nmap, "-p", "445", "--script", "smb-os-discovery",
                   "-Pn", self.host]
            r = self._run(cmd, timeout=120)
            out = r.get("stdout", "") + r.get("stderr", "")
            self._write_result("SMB OS Discovery", out, "MEDIUM")
            return r
        return {"error": "nmap not installed"}

