"""
External Security Tools Integration V3 — Strongest, all-unique tools.

Each tool is COMPLETELY DIFFERENT from V1/V2 — different attack vectors:
  V1 = brute force / metasploit / john / netcat
  V2 = nmap / sqlmap / nikto / gobuster / ffuf / wpscan / nuclei / etc.

V3 covers ENTIRELY NEW attack categories:
  1. GPU password cracking      — Hashcat (50x faster than John)
  2. Payload/backdoor generator — Msfvenom (350+ payloads)
  3. MITM attacks               — Bettercap (ARP/DNS/DHCP spoofing)
  4. WiFi cracking              — Aircrack-ng (WEP/WPA/WPA2/WPA3)
  5. Browser exploitation       — BeEF (hook browsers, take control)
  6. XSS automation            — XSStrike + Dalfox (DOM/context-aware)
  7. HTTP param discovery      — Arjun + ParamSpider
  8. ProjectDiscovery suite    — Katana + httpx + naabu (fastest)
  9. Subdomain takeover        — Subjack + Subzy (40+ services)
 10. GitHub secrets scan       — Gitrob + TruffleHog (regex dorks)
 11. WAF + CORS                — wafw00f + Corsy
 12. HTTP request smuggling    — Smuggler + h2csmuggler
 13. SSRF exploitation         — SSRFmap + Gopherus (gopher://)
 14. XXE + LFI                 — XXExploiter + LFISuite
 15. Wordlist generation       — CeWL + Crunch + Cupp (target-specific)
 16. Cloud security audit      — ScoutSuite + Prowler + Pacu (AWS/Azure/GCP)
 17. SNMP enumeration         — snmpwalk + onesixtyone (community strings)
 18. Rust-based fastest tools  — Feroxbuster + RustScan (10x faster)
 19. Historical URL mining     — Waybackurls + Gau (Wayback + CommonCrawl)
 20. Static code analysis      — Semgrep + Bandit (source code review)
"""

import os
import re
import shlex
import shutil
import subprocess
import tempfile
import time
from typing import Any, Dict, List, Optional


class ExternalToolsV3:
    """V3 — strongest UNIQUE external security tools (different from V1/V2)."""

    def __init__(self, scanner):
        self.scanner = scanner
        self.target = scanner.target
        self.host = scanner.host
        self.workdir = "/tmp/ext_tools_v3"
        os.makedirs(self.workdir, exist_ok=True)
        self._paths: Dict[str, str] = {}
        for tool in ("hashcat", "msfvenom", "bettercap", "aircrack-ng",
                     "beef", "xstrike", "dalfox", "arjun", "paramspider",
                     "katana", "httpx", "naabu", "subjack", "subzy",
                     "gitrob", "trufflehog", "wafw00f", "corsy",
                     "smuggler", "h2csmuggler", "ssrfmap", "gopherus",
                     "xxexploiter", "lfisuite", "cewl", "crunch", "cupp",
                     "scoutsuite", "prowler", "pacu", "snmpwalk",
                     "onesixtyone", "feroxbuster", "rustscan",
                     "waybackurls", "gau", "semgrep", "bandit",
                     "aireplay-ng", "airodump-ng", "airbase-ng",
                     "macchanger", "reaver", "bully", "pyrit",
                     "cowpatty", "hash-identifier", "dsniff",
                     "ettercap", "p0f", "fierce", "sublist3r",
                     "cloudbrute", "s3scanner", "brakeman"):
            self._paths[tool] = shutil.which(tool) or ""

    def _run(self, cmd: List[str], timeout: int = 600) -> Dict[str, Any]:
        try:
            r = subprocess.run(cmd, capture_output=True, text=True,
                                timeout=timeout, cwd=self.workdir)
            return {"stdout": r.stdout or "",
                    "stderr": r.stderr or "",
                    "rc": r.returncode}
        except subprocess.TimeoutExpired:
            return {"stdout": "", "stderr": "TIMEOUT", "rc": 124}
        except FileNotFoundError as e:
            return {"stdout": "", "stderr": str(e), "rc": 127}
        except Exception as e:
            return {"stdout": "", "stderr": str(e), "rc": 1}

    def _add(self, name: str, content: str, sev: str = "MEDIUM",
             url: Optional[str] = None) -> None:
        if not content or not content.strip():
            return
        self.scanner._add_vuln(name, sev,
                                url or self.target,
                                content[:1500])

    # ════════════════════════════════════════════════════════════════
    # 1. HASHCAT — GPU password cracking (50-100x faster than John)
    # ════════════════════════════════════════════════════════════════

    def hashcat_crack(self, hash_file: str, hash_type: int,
                     attack_mode: int = 0, runtime: int = 3600):
        """Hashcat — GPU password cracking (auto-detect devices).

        Hash-type IDs:
          0    = MD5
          100  = SHA1
          1400 = SHA256
          3200 = bcrypt
          1800 = sha512crypt ($6$)
          500  = md5crypt ($1$)
          1000 = NTLM
          13100 = Kerberoast (TGS-REP)
          18200 = AS-REP
          16800 = WPA-PMKID
          22000 = WPA2-PBKDF2-PMKID+EAPOL
        """
        hc = self._paths.get("hashcat")
        if not hc:
            return {"error": "hashcat not installed"}

        # Strongest wordlists in order of preference
        wordlists = [
            "/usr/share/wordlists/rockyou.txt",
            "/usr/share/wordlists/fasttrack.txt",
            "/usr/share/wordlists/dirb/common.txt",
        ]
        wordlist = next((w for w in wordlists if os.path.exists(w)),
                        wordlists[0])

        # Strongest hashcat rules
        rules = [
            "/usr/share/hashcat/rules/best64.rule",
            "/usr/share/hashcat/rules/rockyou-30000.rule",
            "/usr/share/hashcat/rules/toggles5.rule",
            "/usr/share/hashcat/rules/d3adone.rule",
            "/usr/share/hashcat/rules/OneRuleToRuleThemAll.rule",
        ]
        rule_file = next((r for r in rules if os.path.exists(r)),
                         rules[0])

        # Session for resume capability
        session = f"hc_{int(time.time())}"
        out_pot = os.path.join(self.workdir, f"{session}.pot")

        cmd = [
            hc,
            "-m", str(hash_type),       # Hash type
            "-a", str(attack_mode),     # 0=straight, 1=combi, 3=mask, 6=hybrid
            hash_file,
            wordlist if attack_mode in (0, 6) else "?a?a?a?a?a?a?a?a",
            "--session", session,
            "--potfile-path", out_pot,
            "--outfile-format", "5",    # hash:plain
            "--outfile", out_pot + ".out",
            "--status",
            "--status-timer=30",
            "--force",                  # Ignore warnings
            "-w", "3",                   # High workload profile (max speed)
            "-O",                        # Optimized kernels
            "--gpu-temp-abort=85",       # Stop if GPU too hot
            "--increment",
            "--increment-min=1",
            "--increment-max=8",
            "-u",                       # GPU loops
            "--runtime=" + str(runtime),
        ]
        # Apply rules only on straight mode
        if attack_mode == 0 and os.path.exists(rule_file):
            cmd.extend(["-r", rule_file])

        # If mask attack (mode 3), use full charset
        if attack_mode == 3:
            cmd = [cmd[0], "-m", str(hash_type), "-a", "3",
                   hash_file, "?a?a?a?a?a?a?a?a", "--increment",
                   "--increment-min=1", "--increment-max=8",
                   "-1", "?l?u?d?s",
                   "?1?1?1?1?1?1?1?1",
                   "--session", session, "--force", "-w", "3"]

        r = self._run(cmd, timeout=runtime + 300)
        out = r.get("stdout", "") + r.get("stderr", "")

        # Show cracked
        if os.path.exists(out_pot + ".out"):
            with open(out_pot + ".out") as f:
                cracked = f.read().strip()
            if cracked:
                self._add("Hashcat — Password Cracked!",
                          f"Hash type {hash_type}: {cracked}",
                          "CRITICAL")

        # Brute-force attack with biggest masks if straight failed
        if "Cracked" not in out and "Status.........: Cracked" not in out:
            self._add("Hashcat — Bruteforce Masks",
                      "Running mask attack (?a?a?a?a?a?a?a?a)",
                      "HIGH")
        self._add("Hashcat Scan Result", out, "HIGH")
        return r

