    # 9. Subdomain takeover — Subjack + Subzy (40+ services)
    # ════════════════════════════════════════════════════════════════

    def subjack_takeover_scan(self, subs_file: Optional[str] = None):
        """Subjack — subdomain takeover scanner."""
        sj = self._paths.get("subjack")
        if not sj:
            return {"error": "subjack not installed"}
        if not subs_file:
            subs_file = os.path.join(self.workdir, "subs.txt")
            # Try to use subfinder results
            subfinder_out = os.path.join("/tmp/ext_tools_v2",
                                          "subfinder.txt")
            if os.path.exists(subfinder_out):
                shutil.copy(subfinder_out, subs_file)
            else:
                # Generate fallback
                with open(subs_file, "w") as f:
                    for sub in ("www", "mail", "admin", "test", "dev",
                                "staging", "api", "stage", "uat",
                                "demo", "beta", "alpha"):
                        f.write(f"{sub}.{self.host}\n")
        cmd = [sj, "-d", self.host,
               "-a",
               "-w", subs_file,
               "-t", "100",
               "-timeout", "10",
               "-o", os.path.join(self.workdir, "subjack.txt"),
               "-c", "/usr/share/subjack/fingerprints.json",
               "-ssl",
               "-v"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Vulnerable" in out or "vulnerable" in out:
            self._add("Subjack — Subdomain Takeover!",
                      out, "CRITICAL")
        self._add("Subjack Takeover Scan", out, "HIGH")
        return r

    def subzy_takeover_scan(self, subs_file: Optional[str] = None):
        """Subzy — alternative subdomain takeover."""
        sz = self._paths.get("subzy")
        if not sz:
            return {"error": "subzy not installed"}
        if not subs_file:
            subs_file = os.path.join(self.workdir, "subs.txt")
        cmd = [sz, "run", "--targets", subs_file,
               "--timeout", "10",
               "--concurrency", "100",
               "--hide_fails",
               "--https"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "VULNERABLE" in out:
            self._add("Subzy — Subdomain Takeover!",
                      out, "CRITICAL")
        self._add("Subzy Takeover Scan", out, "HIGH")
        return r

    # ════════════════════════════════════════════════════════════════
    # 10. GitHub secrets scan — Gitrob + TruffleHog
    # ════════════════════════════════════════════════════════════════

    def gitrob_scan(self, org: Optional[str] = None):
        """Gitrob — scan GitHub orgs for secrets."""
        gr = self._paths.get("gitrob")
        if not gr:
            return {"error": "gitrob not installed"}
        org_name = org or self.host.split(".")[0]
        out_dir = os.path.join(self.workdir, "gitrob")
        os.makedirs(out_dir, exist_ok=True)
        cmd = [gr, "-github-users", org_name,
               "-gitlab-token", "",
               "-threads", "20",
               "-save", out_dir,
               "-commit-depth", "100",
               "-insecure",
               "-verbose"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        self._add("Gitrob GitHub Secrets Scan", out, "HIGH")
        return r

    def trufflehog_scan(self, repo_url: Optional[str] = None):
        """TruffleHog — search git history for secrets."""
        th = self._paths.get("trufflehog")
        if not th:
            return {"error": "trufflehog not installed"}
        target_repo = repo_url or f"https://github.com/{self.host.split('.')[0]}"
        cmd = [th, "git", "file:///" + target_repo,
               "--results", "verified",
               "--json",
               "--regex",
               "--concurrency", "20",
               "--max-depth", "1000000"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Found secret" in out or "Verified" in out:
            self._add("TruffleHog — Secrets Found!", out, "CRITICAL")
        self._add("TruffleHog Secrets Scan", out, "HIGH")
        return r

