    # ════════════════════════════════════════════════════════════════
    # 15. Wordlist generators — CeWL + Crunch + Cupp
    # ════════════════════════════════════════════════════════════════

    def cewl_generate(self, depth: int = 3):
        """CeWL — generate custom wordlist by scraping target."""
        cw = self._paths.get("cewl")
        if not cw:
            return {"error": "cewl not installed"}
        out_file = os.path.join(self.workdir, "cewl.txt")
        cmd = [cw, self.target,
               "-d", str(depth),
               "-m", "4",
               "-w", out_file,
               "-e",
               "-a",
               "--meta",
               "--lowercase",
               "--with-numbers",
               "-u",
               "Mozilla/5.0 (X11; Linux x86_64)",
               "-v"]
        r = self._run(cmd, timeout=600)
        if os.path.exists(out_file):
            sz = os.path.getsize(out_file)
            self._add("CeWL — Custom Wordlist Generated",
                      f"Size: {sz}B\nFile: {out_file}",
                      "MEDIUM")
        return r

    def crunch_generate(self, min_len: int = 4, max_len: int = 8,
                        pattern: Optional[str] = None):
        """Crunch — generate wordlist by pattern."""
        cr = self._paths.get("crunch")
        if not cr:
            return {"error": "crunch not installed"}
        out_file = os.path.join(self.workdir, "crunch.txt")
        # Charset: lower+upper+digits+symbols
        charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+"
        cmd = [cr, str(min_len), str(max_len), charset,
               "-o", out_file,
               "-c", "10000",  # Lines per file
               "-f", "/usr/share/crunch/charset.lst", "all",
               "-t", pattern or "@@@@",    # @ = lowercase
               "-z", "gzip"]
        r = self._run(cmd, timeout=600)
        if os.path.exists(out_file):
            sz = os.path.getsize(out_file)
            self._add("Crunch — Pattern Wordlist Generated",
                      f"Pattern: {pattern or 'all'}\nSize: {sz}B",
                      "MEDIUM")
        return r

    def cupp_generate(self, info: Dict[str, str]):
        """Cupp — generate user-specific wordlist from personal info."""
        cp = self._paths.get("cupp")
        if not cp:
            return {"error": "cupp not installed"}
        # Common personal info questions
        out_file = os.path.join(self.workdir, "cupp.txt")
        cmd = [cp, "-i",
               "-name", info.get("name", ""),
               "-surname", info.get("surname", ""),
               "-aka", info.get("aka", ""),
               "-birth_date", info.get("birth_date", ""),
               "-birth_year", info.get("birth_year", ""),
               "-birth_city", info.get("birth_city", ""),
               "-pet", info.get("pet", ""),
               "-partner", info.get("partner", ""),
               "-partner_date", info.get("partner_date", ""),
               "-partner_year", info.get("partner_year", ""),
               "-partner_city", info.get("partner_city", ""),
               "-kid1", info.get("kid1", ""),
               "-kid1_date", info.get("kid1_date", ""),
               "-kid1_year", info.get("kid1_year", ""),
               "-kid1_city", info.get("kid1_city", ""),
               "-word", info.get("word", ""),
               "-email", info.get("email", ""),
               "-o", out_file]
        r = self._run(cmd, timeout=300)
        if os.path.exists(out_file):
            sz = os.path.getsize(out_file)
            self._add("Cupp — Personalized Wordlist Generated",
                      f"Size: {sz}B", "MEDIUM")
        return r

    # ════════════════════════════════════════════════════════════════
    # 16. Cloud security audit — ScoutSuite + Prowler + Pacu
    # ════════════════════════════════════════════════════════════════

    def scoutsuite_aws_audit(self):
        """ScoutSuite — multi-cloud security audit (AWS)."""
        ss = self._paths.get("scoutsuite")
        if not ss:
            return {"error": "scoutsuite not installed"}
        out_dir = os.path.join(self.workdir, "scoutsuite")
        cmd = [ss, "aws",
               "--profile", "default",
               "--report-dir", out_dir,
               "--update",
               "--services", "all",
               "--regions", "all",
               "--thread-requests", "100",
               "--max-threads", "100",
               "--no-browser"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        if os.path.exists(out_dir):
            for root, dirs, files in os.walk(out_dir):
                for f in files:
                    if f.endswith(".json"):
                        with open(os.path.join(root, f)) as fp:
                            content = fp.read()
                        if "level" in content and "danger" in content:
                            self._add("ScoutSuite — AWS Finding",
                                      content[:1500], "HIGH")
        return r

    def prowler_aws_audit(self):
        """Prowler — AWS CIS benchmark audit (200+ checks)."""
        pr = self._paths.get("prowler")
        if not pr:
            return {"error": "prowler not installed"}
        out_file = os.path.join(self.workdir, "prowler.txt")
        cmd = [pr, "-M", "json", "-o", out_file,
               "-A", "all",      # All AWS accounts
               "-R", "all",      # All regions
               "-c", "all",       # All checks
               "-V",              # Verbose
               "-B",              # Banner
               "-M", "json,csv,html"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Parse results
        if os.path.exists(out_file):
            with open(out_file) as f:
                content = f.read()
            # Find critical findings
            for line in content.split("\n"):
                if "Critical" in line or "[FAIL]" in line:
                    self._add("Prowler — AWS Finding",
                              line, "HIGH")
        self._add("Prowler AWS Audit", out, "HIGH")
