    def snmpwalk_full(self, community: str = "public"):
        """snmpwalk — full SNMP enumeration."""
        sw = self._paths.get("snmpwalk")
        if not sw:
            return {"error": "snmpwalk not installed"}
        cmd = [sw, "-v", "2c", "-c", community, self.host]
        r = self._run(cmd, timeout=600)
        out = r.get("stdout", "") + r.get("stderr", "")
        self._add("snmpwalk — SNMP Enumeration", out, "HIGH")
        # Check for sensitive info
        for kw in ("iso.3.6.1.2.1.1.1", "system description",
                   "user", "password", "ftp"):
            if kw.lower() in out.lower():
                self._add("snmpwalk — Sensitive Info Found",
                          out, "CRITICAL")
                break
        return r

    def onesixtyone_brute(self):
        """onesixtyone — brute SNMP community strings."""
        osx = self._paths.get("onesixtyone")
        if not osx:
            return {"error": "onesixtyone not installed"}
        wordlist = "/usr/share/wordlists/metasploit/snmp_community.txt"
        if not os.path.exists(wordlist):
            wordlist = "/usr/share/seclists/Misc/wordlist-common-snmp.txt"
        cmd = [osx, "-c", wordlist, "-d", "1", "-w", "100", self.host]
        r = self._run(cmd, timeout=600)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Guess" in out or "found" in out.lower():
            self._add("onesixtyone — Community String Found",
                      out, "HIGH")
        return r

