    # 18. Rust-based fastest tools — Feroxbuster + RustScan
    # ════════════════════════════════════════════════════════════════

    def feroxbuster_scan(self):
        """Feroxbuster — Rust-based recursive dir brute (10x faster)."""
        fb = self._paths.get("feroxbuster")
        if not fb:
            return {"error": "feroxbuster not installed"}
        wordlist = "/usr/share/seclists/Discovery/Web-Content/raft-large-words.txt"
        if not os.path.exists(wordlist):
            wordlist = "/usr/share/wordlists/dirb/big.txt"
        cmd = [fb, "-u", self.target,
               "-w", wordlist,
               "-t", "200",                       # 200 threads
               "-d", "5",                          # depth 5
               "-k",                               # skip TLS verify
               "-q",
               "-A", "Mozilla/5.0",
               "-H", "X-Forwarded-For: 127.0.0.1",
               "-H", "X-Original-URL: /",
               "-S", "0",
               "--extract-links",
               "--filter-status", "404",
               "--dont-scan", "https://.*\\.png",
               "--parallel", "10",
               "-r",
               "-e", "php,asp,aspx,jsp,html,txt,bak,old,orig"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "200" in out or "301" in out or "302" in out:
            self._add("Feroxbuster — Paths Found", out, "HIGH")
        self._add("Feroxbuster Dir Scan", out, "MEDIUM")
        return r

    def rustscan_fast_port_scan(self, ports: str = "1-65535"):
        """RustScan — fast port scanner (10x faster than nmap)."""
        rs = self._paths.get("rustscan")
        if not rs:
            return {"error": "rustscan not installed"}
        cmd = [rs, "-a", self.host,
               "-p", ports,
               "-t", "2000",
               "--tries", "3",
               "--ulimit", "100000",
               "-b", "5000",                       # batch size
               "-g", "5000",                       # grepable
               "--no-banner",
               "--accessible",
               "--no-interactive",
               "-d",                                # debug
               "--scripts", "default,vuln,brute",
               "-n", "nolimits",
               "-c", "32"]                          # 32 concurrency
        r = self._run(cmd, timeout=1200)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Open" in out:
            self._add("RustScan — Open Ports", out, "HIGH")
        self._add("RustScan Fast Port Scan", out, "MEDIUM")
        return r

