    # 19. Historical URL mining — Waybackurls + Gau
    # ════════════════════════════════════════════════════════════════

    def waybackurls_scan(self):
        """Waybackurls — fetch URLs from Wayback Machine."""
        wb = self._paths.get("waybackurls")
        if not wb:
            return {"error": "waybackurls not installed"}
        out_file = os.path.join(self.workdir, "waybackurls.txt")
        # Run + capture
        try:
            with open(out_file, "w") as f:
                proc = subprocess.Popen(
                    [wb, self.host],
                    stdout=f, stderr=subprocess.PIPE)
                proc.wait(timeout=600)
        except subprocess.TimeoutExpired:
            proc.terminate()
        if os.path.exists(out_file):
            with open(out_file) as f:
                urls = [l.strip() for l in f if l.strip()]
            if urls:
                self._add("Waybackurls — Historical URLs",
                          f"{len(urls)} URLs found\n" +
                          "\n".join(urls[:50]), "MEDIUM")
        return {"success": True}

    def gau_scan(self):
        """Gau — Get All URLs from Wayback/CommonCrawl/Alienvault."""
        gau = self._paths.get("gau")
        if not gau:
            return {"error": "gau not installed"}
        out_file = os.path.join(self.workdir, "gau.txt")
        cmd = [gau, "--threads", "20",
               "--subs",
               "--providers", "wayback,commoncrawl,alienvault,otx,urlscan",
               "--retries", "5",
               "--timeout", "30s",
               self.host]
        try:
            with open(out_file, "w") as f:
                proc = subprocess.Popen(
                    cmd, stdout=f, stderr=subprocess.PIPE)
                proc.wait(timeout=600)
        except subprocess.TimeoutExpired:
            proc.terminate()
        if os.path.exists(out_file):
            with open(out_file) as f:
                urls = [l.strip() for l in f if l.strip()]
            if urls:
                self._add("Gau — All URLs Found",
                          f"{len(urls)} URLs found\n" +
                          "\n".join(urls[:50]), "MEDIUM")
        return {"success": True}

