    def linpeas_run(self):
        """LinPEAS — strongest Linux privilege escalation."""
        # Try local linpeas
        lp = self._paths.get("linpeas") or "/opt/linpeas/linpeas.sh"
        if not os.path.exists(lp):
            return {"error": "linpeas not installed"}
        cmd = [lp,
               "-a",                          # All checks
               "-s",                          # Superfast
               "-n",                          # No colors
               "-w",                          # Wait
               "-o", os.path.join(self.workdir, "linpeas.txt"),
               "-p", "10",
               "-q",
               "-N",
               "-d", "/",                      # Search /
               "-t", "/,/etc,/var,/opt,/tmp,/home",  # Search paths
               "-c", "10"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Highlight findings
        for kw in ("SUID", "CVE-", "password", "credential",
                   "private key", "token", "PRIVESC"):
            if kw.lower() in out.lower():
                self._add(f"LinPEAS — {kw} Finding!",
                          out, "HIGH")
                break
        self._add("LinPEAS — Linux Privesc Audit", out, "HIGH")
        return r

