    def mobsf_scan_apk(self, apk_path: str):
        """MobSF — strongest mobile app security scanner."""
        ms = self._paths.get("mobsf")
        if not ms:
            return {"error": "mobsf not installed"}
        # Start MobSF server
        try:
            srv_proc = subprocess.Popen(
                [ms, "run", "--host=0.0.0.0", "--port=8000"],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            time.sleep(10)  # wait for startup
        except Exception as e:
            return {"error": str(e)}
        # Upload APK via API
        import requests
        try:
            with open(apk_path, 'rb') as f:
                r = requests.post(
                    'http://localhost:8000/api/v1/upload',
                    files={'file': ('app.apk', f)},
                    headers={'Authorization': 'Token ' +
                             os.environ.get('MOBSF_API_KEY', 'test')},
                    timeout=300)
            res = r.json()
            scan_hash = res.get('hash')
            # Static analysis
            r2 = requests.post(
                'http://localhost:8000/api/v1/static_analyzer',
                data={'hash': scan_hash, 'scan_type': 'android'},
                headers={'Authorization': 'Token ' +
                         os.environ.get('MOBSF_API_KEY', 'test')},
                timeout=1800)
            report = r2.json()
            # Findings
            for finding_type in ('permissions', 'malware_analysis',
                                'code_analysis', 'manifest_analysis',
                                'binary_analysis', 'file_analysis',
                                'niap_analysis', 'trackers_analysis',
                                'secrets'):
                if finding_type in report:
                    self._add(f"MobSF — {finding_type}",
                              str(report[finding_type])[:1500],
                              "HIGH")
            # JSON report
            r3 = requests.post(
                'http://localhost:8000/api/v1/report_json',
                data={'hash': scan_hash},
                headers={'Authorization': 'Token ' +
                         os.environ.get('MOBSF_API_KEY', 'test')},
                timeout=60)
            with open(os.path.join(self.workdir,
                                    "mobsf_report.json"), 'wb') as f:
                f.write(r3.content)
            self._add("MobSF — APK Scan Complete",
                      f"Scanned: {apk_path}\n"
                      f"Scan hash: {scan_hash}",
                      "HIGH")
            return {"success": True, "scan_hash": scan_hash}
        except Exception as e:
            return {"error": str(e)}

