    # ════════════════════════════════════════════════════════════════
    # 15. FIRMWARE ANALYSIS — binwalk
    # ════════════════════════════════════════════════════════════════

    def binwalk_full_extract(self, firmware_path: str):
        """Binwalk — strongest firmware analysis."""
        bw = self._paths.get("binwalk")
        if not bw:
            return {"error": "binwalk not installed"}
        out_dir = os.path.join(self.workdir, "firmware_extract")
        os.makedirs(out_dir, exist_ok=True)
        cmd = [bw, "--verbose",
               "--signature",
               "--casting",
               "--entropy",
               "--strings",
               "--carve",
               "--directory", out_dir,
               "--rm",
               "--matryoshka",          # Recursive extraction
               "--depth", "10",
               firmware_path]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Look for sensitive files
        sensitive = ["passwd", "shadow", "config", "key", "cert",
                     "credentials", "shadow", "wifi", "telnet"]
        for root, dirs, files in os.walk(out_dir):
            for f in files:
                for kw in sensitive:
                    if kw in f.lower():
                        fp = os.path.join(root, f)
                        try:
                            sz = os.path.getsize(fp)
                            self._add(f"Binwalk — {kw.title()} File Found",
                                      f"File: {f}\nSize: {sz}B",
                                      "HIGH")
                        except Exception:
                            pass
        self._add("Binwalk — Firmware Extracted", out, "MEDIUM")
        return r

