    def slither_solidity_scan(self, contract_path: str):
        """Slither — Solidity static analyzer (50+ detectors)."""
        sl = self._paths.get("slither")
        if not sl:
            return {"error": "slither not installed"}
        cmd = [sl, contract_path,
               "--detect", "all",
               "--exclude-optimization",
               "--exclude-informational",
               "--triage-mode",
               "--filter-paths", ".*tests.*",
               "--legacy-ast",
               "--exclude-low",
               "--exclude-medium",
               "--exclude-informational",
               "--human-readable",
               "--json", os.path.join(self.workdir, "slither.json"),
               "--print", "human-summary",
               "--print", "contract-summary",
               "--print", "dataflow",
               "--print", "call-graph",
               "--print", "inheritance",
               "--print", "vars-and-auth",
               "--print", "variable-order",
               "--print", "function-summary",
               "--solc-args", "--optimize --via-ir --bin",
               "--solc-disable-warnings"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Parse findings
        if os.path.exists(os.path.join(self.workdir, "slither.json")):
            import json
            with open(os.path.join(self.workdir, "slither.json")) as f:
                j = json.load(f)
            for detector in j.get("results", {}).get("detectors", []):
                sev = detector.get("impact", "LOW").upper()
                self._add(f"Slither — {detector.get('check', 'unknown')}",
                          json.dumps(detector), sev)
        self._add("Slither Solidity SAST", out, "HIGH")
        return r

    def mythril_symbolic_execution(self, contract_path: str):
        """Mythril — symbolic execution + SMT solver."""
        my = self._paths.get("mythril")
        if not my:
            return {"error": "mythril not installed"}
        cmd = [my, "analyze",
               contract_path,
               "--solv", "0.8.0",
               "--execution-timeout", "1200",
               "--max-depth", "100",
               "--solver-timeout", "60",
               "--transaction-count", "5",
               "--create-timeout", "600",
               "--inf-loop-timeout", "120",
               "--callstack-limit", "10",
               "--module", "all",
               "--strategy", "dfs",
               "--states-query-timeout", "60",
               "--sparse-pruning",
               "--num-solving-batches", "5",
               "--solver", "z3",
               "--solc-args", "--optimize",
               "--bytecode",
               "--address", "0x" + "0"*40,
               "--rpc", "https://mainnet.infura.io/v3/KEY",
               "--inf-rpc-retries", "5",
               "--no-onchain-storage-access",
               "--custom-modules-directory", "/opt/mythril/modules"]
        r = self._run(cmd, timeout=3600)
        out = r.get("stdout", "") + r.get("stderr", "")
        if "Vulnerability" in out or "Issue" in out:
            self._add("Mythril — Solidity Vulnerability Found!",
                      out, "CRITICAL")
        self._add("Mythril Symbolic Execution", out, "HIGH")
        return r

