    def s3scanner_full(self, target_company: Optional[str] = None):
        """S3Scanner — strongest AWS S3 bucket scanner."""
        s3 = self._paths.get("s3scanner")
        if not s3:
            return {"error": "s3scanner not installed"}
        company = target_company or self.host.split(".")[0]
        # Generate wordlist of possible bucket names
        wordlist = os.path.join(self.workdir, "buckets.txt")
        with open(wordlist, "w") as f:
            for prefix in (company, company + "-backup",
                           company + "-dev", company + "-test",
                           company + "-staging", company + "-prod",
                           company + "-internal", company + "-private",
                           company + "-public", company + "-logs",
                           company + "-data", company + "-assets",
                           company + "-media", company + "-files",
                           company + "-docs", company + "-images",
                           company + "-videos", company + "-audio",
                           company + "-config", company + "-secrets",
                           company + "-keys", company + "-terraform",
                           company + "-cloudtrail", company + "-s3",
                           company + "-elastic", company + "-rds",
                           company + "-lambda", company + "-ec2"):
                f.write(prefix + "\n")
        cmd = [s3, "scan", "--buckets-file", wordlist,
               "--provider", "aws,gcp,azure,digitalocean,linode,wasabi,backblaze,oracle,minio",
               "--out-file", os.path.join(self.workdir, "s3results.txt"),
               "--workers", "100",
               "--force"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        if os.path.exists(os.path.join(self.workdir, "s3results.txt")):
            with open(os.path.join(self.workdir, "s3results.txt")) as f:
                results = f.read()
            # Find exposed buckets
            for line in results.split("\n"):
                if "exists" in line.lower() or "open" in line.lower():
                    self._add("S3Scanner — Exposed Bucket Found!",
                              line, "CRITICAL")
        self._add("S3Scanner — Cloud Bucket Scan", out, "HIGH")
        return r

