    def kerbrute_user_enum(self, users_file: str = "/usr/share/wordlists/metasploit/unix_users.txt"):
        """Kerbrute — enumerate valid usernames via Kerberos."""
        kb = self._paths.get("kerbrute")
        if not kb:
            return {"error": "kerbrute not installed"}
        cmd = [kb, "userenum",
               "--dc", self.host,
               "--domain", "DOMAIN",
               users_file,
               "--threads", "100",
               "--ignore-status",
               "--no-preauth",
               "--downgrade",
               "--verbose"]
        r = self._run(cmd, timeout=1800)
        out = r.get("stdout", "") + r.get("stderr", "")
        # Find valid users
        valid_users = re.findall(r"\[\+\] VALID USERNAME.*?user:\s*(\w+)",
                                  out)
        if valid_users:
            self._add("Kerbrute — Valid Users Found!",
                      f"Found {len(valid_users)} valid users\n" +
                      "\n".join(valid_users[:20]), "HIGH")
        self._add("Kerbrute User Enumeration", out, "HIGH")
        return r

