# ─── Lazy imports ─────────────────────────────────────────────────────
def _lazy_import(module_name, attr=None):
    try:
        mod = __import__(module_name, fromlist=[attr] if attr else [])
        return getattr(mod, attr) if attr else mod
    except (ImportError, AttributeError):
        return None


