# ════════════════════════════════════════════════════════════════════
# Bypass Headers (X-Forwarded-For + variants)
# ════════════════════════════════════════════════════════════════════

def _random_ip(internal: bool = False) -> str:
    """Generate random IP address (external or internal)."""
    if internal:
        # Internal IPs often bypass auth
        choice = random.choice(["10", "172", "192", "127", "0"])
        if choice == "10":
            return f"10.{random.randint(0,255)}.{random.randint(0,255)}.{random.randint(0,255)}"
        elif choice == "172":
            return f"172.16.{random.randint(0,255)}.{random.randint(0,255)}"
        elif choice == "192":
            return f"192.168.{random.randint(0,255)}.{random.randint(0,255)}"
        elif choice == "127":
            return f"127.0.0.{random.randint(1,255)}"
        else:
            return f"0.0.0.0"
    # External IPs - look like real client traffic
    return f"{random.randint(1,255)}.{random.randint(0,255)}.{random.randint(0,255)}.{random.randint(0,255)}"


def _random_ipv6() -> str:
    """Generate random IPv6 address (many sites don't rate limit IPv6)."""
    parts = []
    for _ in range(8):
        parts.append(f"{random.randint(0, 0xffff):x}")
    return ":".join(parts)


