    def _add_vuln(self, vuln_type, severity, url, evidence, **extra):
        # ─── SEVERITY FILTER — only CRITICAL and HIGH ──────────
        if severity not in ("CRITICAL", "HIGH"):
            return  # Skip MEDIUM, LOW, INFO
        
        # ─── FALSE POSITIVE FILTER #1: "check string found" ────
        ev_str = str(evidence)
        if "check string found" in ev_str:
            return  # Skip — false positive
        
        # ─── FALSE POSITIVE FILTER #2: base64 image data ────
        if "AAAANSUhEUg" in ev_str:
            return  # Skip — base64 PNG, not a real secret
        
        # ─── FALSE POSITIVE FILTER #3: SPA shell ────────────
        # SPA shell detection: if evidence mentions size and it's close to baseline
        spa_fp = ['Endpoint accessible', 'Path: /', 'endpoint accessible', 
                  'size=', 'Debug Endpoint', 'Consul', 'Eureka', 'Nacos',
                  'Marathon', 'RabbitMQ', 'Zipkin', 'Consul KV', 'Consul Health']
        if any(p in ev_str for p in spa_fp):
            # Check if this is just a SPA shell (same HTML for all paths)
            import re as _re
            size_match = _re.search(r'size=(\d+)b?', ev_str)
            if size_match:
                resp_size = int(size_match.group(1))
                baseline = getattr(self, '_spa_baseline_size', 0)
                if baseline > 0 and abs(resp_size - baseline) < 5000:
                    return  # Skip — SPA shell (size matches baseline)
            # Also skip generic endpoint messages without real evidence
            if not any(k in ev_str.lower() for k in ['sql', 'error', 'root:', 'uid=', 'alert', 'ami-', 'redis', 'password', 'secret', 'key=', 'ListBucket', 'CNAME']):
                return  # Skip — SPA shell false positive
        
        # ─── FALSE POSITIVE FILTER: OAuth test payloads ──────
        if 'evil.com' in ev_str.lower() or 'evil.attacker' in ev_str.lower():
            return  # Skip — test payload, not real bypass

        # ─── FALSE POSITIVE FILTER #4: /proc/ and /actuator/ ──
        url_str = str(url)
        if '/proc/' in url_str and 'root:' not in ev_str:
            return
        if '/actuator/' in url_str and 'env' not in ev_str.lower():
            return
        if '/admin' in url_str and 'admin' not in ev_str.lower() and 'CNAME' not in ev_str:
            return
        
        # ─── AUTO-EXPLOITATION (READ-ONLY, no data deletion) ────
        exploit_result = None
        if hasattr(self, '_deep_exploit'):
            exploit_result = self._deep_exploit(vuln_type, severity, url, evidence)
        if not exploit_result and hasattr(self, '_auto_exploit'):
            exploit_result = self._auto_exploit(vuln_type, severity, url, evidence)
        if exploit_result:
            extra["exploit_verified"] = True
            extra["exploit_details"] = exploit_result
        
        # ─── DEDUPLICATION ────────────────────────────────────
        with self.lock:
            for existing in self.results.get("vulnerabilities", []):
                if existing.get("type") == vuln_type and existing.get("url") == url:
                    return  # Skip — duplicate
        entry = {
            "type": vuln_type,
            "severity": severity,
            "url": url,
            "evidence": evidence,
            "description": self._vuln_description(vuln_type, severity),
            "risk": self._vuln_risk(vuln_type, severity),
            "remediation": self._remediation_for(vuln_type),
            "category": self._vuln_category(vuln_type),
            "discovered_at": time.strftime("%H:%M:%S"),
        }
        entry.update(extra)
        with self.lock:
            self.results["vulnerabilities"].append(entry)
        self._print(f"[{severity}]", f"{vuln_type}: {url}", severity)

    def _load_state(self):
        try:
            st = os.stat(self.state_path)
            if st.st_mode & 0o077:
                self._print("[!]", f"state file {self.state_path} has unsafe permissions, skipping load", "HIGH")
                return
            if os.geteuid() != st.st_uid and st.st_uid != 0:
                self._print("[!]", f"state file {self.state_path} not owned by current user, skipping load", "HIGH")
                return
            with open(self.state_path, "rb") as f:
                state = pickle.load(f)
            if isinstance(state, dict):
                self.already_done = state.get("already_done", set())
                self.crawled_links = state.get("crawled_links", set())
                self.params_seen = state.get("params_seen", set())
                loaded_results = state.get("results", {})
                if isinstance(loaded_results, dict):
                    for k, v in loaded_results.items():
                        if k in self.results:
                            self.results[k] = v
        except FileNotFoundError:
            pass
        except Exception:
            pass

    def _save_state(self):
        try:
            state = {
                "already_done": self.already_done,
                "crawled_links": self.crawled_links,
                "params_seen": self.params_seen,
                "results": self.results,
            }
            with open(self.state_path, "wb") as f:
                pickle.dump(state, f)
            # Restrict permissions to owner-only (BUG-205 hardening)
            try:
                os.chmod(self.state_path, 0o600)
            except OSError:
                pass
        except Exception:
            pass


