    def test_sqli_boolean_based(self):
        """Boolean-based blind SQLi — compare TRUE vs FALSE payloads."""
        if not self.deep: return
        self._print("[*]", "SQLi boolean-based...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:15]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                # TRUE vs FALSE
                true_url = self._inject(url, p, "1 AND 1=1")
                false_url = self._inject(url, p, "1 AND 1=2")
                true_r = self._get(true_url)
                false_r = self._get(false_url)
                if not true_r or not false_r: continue
                t_len = len(true_r.text or "")
                f_len = len(false_r.text or "")
                base_r = self._get(self._inject(url, p, "1"))
                b_len = len(base_r.text or "") if base_r else 0
                # If TRUE matches baseline but FALSE differs → likely blind SQLi
                if abs(t_len - b_len) < 50 and abs(f_len - b_len) > 500 and f_len < b_len:
                    self._add_vuln("SQLi (boolean-based blind)", "HIGH",
                                    true_url, f"{p}=1 AND 1=1 vs 1 AND 1=2 differ",
                                    param=p, evidence="true_response != false_response")

