        for ep in endpoints:
            url = urljoin(self.target, ep)
            data = {"coupon": "TEST", "code": "TEST"}
            threads = []
            results = [None] * 10
            def send(i, results):
                results[i] = self._post(url, data=data)
            for i in range(10):
                t = threading.Thread(target=send, args=(i, results))
                threads.append(t)
            for t in threads: t.start()
            for t in threads: t.join()
            success = sum(1 for r in results if r and r.status_code == 200)
            if success > 1:
                self._add_vuln("Race condition (coupon apply)", "HIGH",
                                url, f"{success}/10 simultaneous coupon applies",
                                endpoint=ep, success_count=success)

