    def test_ssrf_aws_imdsv2_token(self):
        """Wave 11 #113 — AWS IMDSv2 token fetch attempt."""
        if not self.deep: return
        self._print("[*]", "Wave 11: AWS IMDSv2 token...", "INFO")
        try:
            # IMDSv2 requires a token from PUT request
            r = requests.put("http://169.254.169.254/latest/api/token",
                              headers={"X-aws-ec2-metadata-token-ttl-seconds": "21600"},
                              timeout=3, verify=False)
            if r and r.status_code == 200:
                token = r.text
                # Now use token
                r2 = requests.get("http://169.254.169.254/latest/meta-data/instance-id",
                                  headers={"X-aws-ec2-metadata-token": token},
                                  timeout=3, verify=False)
                if r2 and r2.status_code == 200:
                    self._add_vuln("AWS IMDSv2 Metadata Accessible",
                                    "CRITICAL", self.target,
                                    f"Instance ID: {r2.text[:60]}",
                                    endpoint="/")
        except Exception:
            pass

