    def test_aws_s3_buckets_deep(self):
        """Wave 12 #145 — AWS S3 bucket enumeration (deep)."""
        if not self.deep: return
        self._print("[*]", "Wave 12: AWS S3 deep...", "INFO")
        try:
            host = urlparse(self.target).hostname
            base = host.split(".")[0]
            # Try common bucket names
            for prefix in [host, base, host.replace(".", "-"),
                            base + "-backup", base + "-media",
                            base + "-static", base + "-assets",
                            base + "-prod", base + "-dev"]:
                # Regional URL
                urls = [f"https://{prefix}.s3.amazonaws.com",
                        f"https://{prefix}.s3.us-east-1.amazonaws.com",
                        f"https://{prefix}.s3.eu-west-1.amazonaws.com"]
                for u in urls:
                    r = self._get(u)
                    if r and r.status_code == 200:
                        if "<ListBucketResult" in (r.text or ""):
                            self._add_vuln(f"AWS S3 Bucket Open: {prefix}",
                                            "CRITICAL", u,
                                            f"Bucket listing: {prefix}",
                                            endpoint=u)
                            break
        except Exception:
            pass

