    def test_cdn_origin_ip_leak(self):
        """Wave 12 #179 — CDN origin IP leak via multiple sources."""
        if not self.deep: return
        self._print("[*]", "Wave 12: CDN origin IP leak...", "INFO")
        try:
            # Try to find origin IP via DNS history
            host = urlparse(self.target).hostname
            # Check SPF / TXT records for IP hints
            import dns.resolver
            try:
                answers = dns.resolver.resolve(host, "TXT")
                for a in answers:
                    txt = str(a)
                    if "ip4:" in txt.lower():
                        # Extract IP
                        import re
                        ips = re.findall(r"ip4:([0-9.]+)", txt)
                        for ip in ips:
                            self._add_vuln(f"CDN Origin IP Hint in SPF: {ip}",
                                            "HIGH", self.target,
                                            f"SPF: {txt[:80]}",
                                            endpoint="/")
            except Exception:
                pass
        except Exception:
            pass

