    def test_pqc_hybrid_tls_abuse(self):
        """Wave 12 #208 — PQC/Hybrid TLS detection."""
        if not self.deep: return
        self._print("[*]", "Wave 12: PQC Hybrid TLS...", "INFO")
        try:
            import ssl
            host = urlparse(self.target).hostname
            # Check if server supports hybrid (Kyber + ECDHE)
            ctx = ssl._create_unverified_context()
            ctx.set_ciphers("ALL")
            try:
                with socket.create_connection((host, 443), timeout=5) as sock:
                    with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                        # No direct PQC detection in stdlib
                        version = ssock.version()
                        if version and "1.3" in version:
                            pass  # Good
                        elif version and "1.0" in version:
                            self._add_vuln("TLS 1.0 Still Supported (PQC Not Available)",
                                            "HIGH", self.target,
                                            f"TLS version: {version}",
                                            endpoint="/")
            except Exception:
                pass
        except Exception:
            pass

