    def test_redis_abuse_v2(self):
        """Wave 13 #38 — Redis deeper config exposure."""
        if not self.deep: return
        self._print("[*]", "Wave 13: Redis v2...", "INFO")
        try:
            import socket
            for port in [6379, 6380, 6378]:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(3)
                    host = urlparse(self.target).hostname
                    res = s.connect_ex((host, port))
                    if res == 0:
                        s.send(b"*1\r\n$8\r\nCONFIG\r\n$3\r\nGET\r\n$1\r\n*\r\n")
                        data = s.recv(8192)
                        if data and b"maxmemory" in data.lower():
                            self._add_vuln(f"Redis CONFIG GET Accessible (port {port})",
                                            "CRITICAL", self.target,
                                            "Redis config exposed",
                                            endpoint=f":{port}")
        except Exception:
            pass

