    def test_zookeeper_abuse_v2(self):
        """Wave 13 #99 — Zookeeper deeper abuse."""
        if not self.deep: return
        self._print("[*]", "Wave 13: Zookeeper v2...", "INFO")
        try:
            import socket
            for port in [2181, 2182, 9583]:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(3)
                    host = urlparse(self.target).hostname
                    res = s.connect_ex((host, port))
                    if res == 0:
                        # Try ruok command
                        s.send(b"ruok")
                        data = s.recv(1024)
                        if data and b"imok" in data:
                            self._add_vuln(f"Zookeeper ruok Accessible (port {port})",
                                            "HIGH", self.target,
                                            "Zookeeper unauthenticated",
                                            endpoint=f":{port}")
        except Exception:
            pass

