    def test_cve_2024_6387_openssh_regreSSHion(self):
        """Wave 14 #152 — CVE-2024-6387 OpenSSH regreSSHion RCE."""
        if not self.deep: return
        self._print("[*]", "Wave 14: CVE-2024-6387...", "INFO")
        try:
            import socket
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(5)
                host = urlparse(self.target).hostname
                res = s.connect_ex((host, 22))
                if res == 0:
                    # Read SSH banner
                    banner = s.recv(1024).decode("utf-8", errors="ignore")
                    if banner and "OpenSSH" in banner:
                        import re
                        m = re.search(r"OpenSSH_(\d+\.\d+)", banner)
                        if m:
                            try:
                                v = tuple(int(x) for x in m.group(1).split("."))
                                if v < (9, 6):
                                    self._add_vuln("CVE-2024-6387 regreSSHion Vulnerable OpenSSH",
                                                    "CRITICAL", self.target,
                                                    f"Banner: {banner.strip()[:80]}",
                                                    endpoint=":22")
                            except ValueError:
                                pass
        except Exception:
            pass

