    def test_mqtt_5_0_abuse(self):
        """Wave 15 #101 — MQTT 5.0 protocol abuse."""
        if not self.deep: return
        self._print("[*]", "Wave 15: MQTT 5.0...", "INFO")
        try:
            import socket
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(3)
                host = urlparse(self.target).hostname
                res = s.connect_ex((host, 1883))
                if res == 0:
                    # MQTT 5.0 CONNECT
                    pkt = b"\x10\x0c\x00\x04MQTT\x05\x02\x00\x3c\x00\x00"
                    s.send(pkt)
                    data = s.recv(1024)
                    if data and len(data) >= 4 and data[0] == 0x20:
                        self._add_vuln("MQTT 5.0 Broker Exposed (port 1883)",
                                        "HIGH", self.target,
                                        "MQTT 5.0 broker reachable",
                                        endpoint=":1883")
        except Exception:
            pass

    def test_stomp_1_2_abuse(self):
        """Wave 15 #102 — STOMP 1.2 protocol abuse."""
        if not self.deep: return
        self._print("[*]", "Wave 15: STOMP 1.2...", "INFO")
        try:
            import socket
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(3)
                host = urlparse(self.target).hostname
                res = s.connect_ex((host, 61613))
                if res == 0:
                    # STOMP 1.2 CONNECT
                    msg = "CONNECT\naccept-version:1.2\nhost:stomp\n\n\x00"
                    s.send(msg.encode())
                    data = s.recv(1024)
                    if data and b"CONNECTED" in data:
                        self._add_vuln("STOMP 1.2 Broker Exposed",
                                        "HIGH", self.target,
                                        f"STOMP response: {data[:60]}",
                                        endpoint=":61613")
        except Exception:
            pass

