        self._print("[*]", "DNS zone transfer test...", "INFO")
        try:
            ns_records = dns.resolver.resolve(self.root_host, "NS")
            for ns in ns_records:
                ns_hostname = str(ns).rstrip(".")
                # Try AXFR against each NS
                import dns.query
                import dns.zone
                try:
                    z = dns.zone.from_xfr(dns.query.xfr(ns_hostname, self.root_host, timeout=5))
                    if z:
                        records = list(z.keys())
                        self._add_vuln("DNS Zone Transfer Allowed", "HIGH",
                                        ns_hostname, f"AXFR leaked {len(records)} records",
                                        ns=ns_hostname, records=len(records))
                except Exception:
                    pass
        except Exception:
            pass

