    def test_api_excessive_data(self):
        """API returns more data than needed."""
        self._print("[*]", "API excessive data exposure...", "INFO")
        for ep in ["/api/users", "/api/me", "/api/profile"]:
            url = urljoin(self.target, ep)
            r = self._get(url)
            if r and r.status_code == 200:
                try:
                    data = r.json()
                    # Look for sensitive fields
                    sensitive_fields = ["password", "ssn", "credit_card",
                                        "api_key", "token", "secret", "private_key"]
                    found_sensitive = []
                    def scan(obj, depth=0):
                        if depth > 5: return
                        if isinstance(obj, dict):
                            for k, v in obj.items():
                                if any(s in k.lower() for s in sensitive_fields):
                                    found_sensitive.append(k)
                                scan(v, depth+1)
                        elif isinstance(obj, list):
                            for item in obj:
                                scan(item, depth+1)
                    scan(data)
                    if found_sensitive:
                        self._add_vuln("API Excessive Data Exposure", "HIGH",
                                        url, f"sensitive fields: {found_sensitive}",
                                        fields=found_sensitive)
                except Exception:
                    pass

