    def _ssrf_test_target(self, target, description, indicator_kw=None):
        """Test if a specific SSRF target is reachable from the server."""
        if not self.deep: return False
        for url, params in list(self.params_seen)[:3]:
            for p in params:
                if p.lower() not in SSRF_PARAMS: continue
                test_url = self._inject(url, p, target)
                r = self._get(test_url)
                if r and r.status_code == 200 and len(r.text) > 100:
                    body = r.text or ""
                    if indicator_kw and indicator_kw in body:
                        self._add_vuln(f"SSRF ({description})", "CRITICAL",
                                        test_url, f"{p}={target}",
                                        param=p, target=target)
                        return True
        return False

