    # ─── GENERIC TEST GENERATORS (efficient) ─────────────────────────────

    def _test_path_probe(self, paths, severity, vuln_type, indicator_check=None):
        """Helper: probe a list of paths, classify by indicator."""
        for path in paths:
            url = urljoin(self.target, path)
            r = self._get(url)
            if not r or r.status_code != 200:
                continue
            body = r.text or ""
            size = len(r.content)
            if "<title>404" in body.lower() or "not found" in body[:300].lower():
                continue
            if indicator_check and not indicator_check(body):
                continue
            self._add_vuln(vuln_type, severity, url,
                          f"size={size}b", path=path, preview=body[:200])

    def _test_payloads_for_params(self, payloads, vuln_type, severity,
                                     detector=None, params_filter=None):
        """Helper: inject payloads into each param, check detector."""
        if not self.deep: return
        tested = set()
        for url, params in list(self.params_seen)[:30]:
            for p in params:
                if params_filter and not params_filter(p):
                    continue
                if (url, p) in tested:
                    continue
                tested.add((url, p))
                marker = "x" + "".join(random.choices(string.ascii_lowercase, k=6))
                for tpl in payloads:
                    payload = marker + tpl if isinstance(tpl, str) else tpl
                    test_url = self._inject(url, p, payload)
                    r = self._get(test_url)
                    if r and detector and detector(r.text or "", marker, tpl, payload):
                        self._add_vuln(vuln_type, severity, test_url,
                                      f"{p}={str(tpl)[:50]}",
                                      param=p, payload=payload)
                        break

    # ─── XSS — HTML tag-specific attribute contexts (30 modules) ────────

    def _xss_tag_specific(self, tag, attrs):
        """Generic XSS tester for a specific HTML tag context."""
        if not self.deep: return
        marker = "xt" + "".join(random.choices(string.ascii_lowercase, k=5))
        payloads = [f'{marker}" onfocus=alert(1) autofocus=',
                    f'{marker}" onmouseover=alert(1) x=',
                    f'{marker}\' onmouseover=alert(1) x=\'']
        for url, params in list(self.params_seen)[:10]:
            for p in params:
                for tpl in payloads:
                    test_url = self._inject(url, p, tpl)
                    r = self._get(test_url)
                    if r and marker in (r.text or ""):
                        # Check if payload landed inside an attribute of our target tag
                        body = r.text or ""
                        # crude heuristic: tag name near payload
                        if tag.lower() in body.lower()[body.find(marker)-200:body.find(marker)+200]:
                            self._add_vuln(f"XSS in <{tag}> attribute", "HIGH",
                                          test_url, f"{p}={tpl[:50]}",
                                          param=p, payload=tpl, tag=tag)
                            return

