    def test_java_deserialization(self):
        """Java deserialization — Java serialized object in HTTP."""
        if not self.deep: return
        # Java serialized object magic bytes: rO0
        # Try sending serialized Java object in various params
        # Just trigger the detection — actual attack is complex
        marker = b"rO0ABXNyACRqYXZhLnV0aWwuQ29sbGVjdGlvbnMkRW1wdHlMaXN0e"
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                # Send empty serialized Java object
                serialized = b"\xac\xed\x00\x05p"  # minimal Java serialized
                r = self._post(self._inject(url, p, "test"),
                                data=serialized,
                                headers={"Content-Type":"application/octet-stream"})
                if r and r.status_code == 500 and ("java.lang" in (r.text or "") or
                                                    "ClassNotFoundException" in (r.text or "")):
                    self._add_vuln("Java deserialization potential", "CRITICAL",
                                    url, f"Java exception when sending serialized obj to {p}",
                                    param=p)

