    def _waf_bypass_test(self, waf_name, payloads, vuln_type="SQLi"):
        """Generic WAF bypass tester."""
        if not self.deep: return
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p, waf_name) in tested: continue
                tested.add((url, p, waf_name))
                for tpl in payloads[:5]:  # limit per WAF
                    test_url = self._inject(url, p, tpl)
                    r = self._get(test_url)
                    if r:
                        body = r.text or ""
                        # Generic SQLi error indicator
                        for pat, db in SQLI_ERRORS:
                            if re.search(pat, body, re.I):
                                self._add_vuln(f"{vuln_type} ({waf_name} bypass)", "HIGH",
                                              test_url, f"{p}={tpl[:50]} [{db}]",
                                              param=p, payload=tpl, waf=waf_name, dbms=db)
                                return
                        # Time-based
                        if "SLEEP" in tpl or "DELAY" in tpl or "pg_sleep" in tpl:
                            t0 = time.time()
                            r2 = self._get(test_url)
                            dt = time.time() - t0
                            if r2 and dt > 3.0:
                                self._add_vuln(f"{vuln_type} ({waf_name} bypass, time-based)", "HIGH",
                                              test_url, f"{p}={tpl[:50]} delay={dt:.1f}s",
                                              param=p, payload=tpl, waf=waf_name, delay=f"{dt:.1f}s")
                                return

