    # ─── LFI — More OS-specific paths (40 modules via path enumeration) ──

    def _test_lfi_specific_path(self, path, description):
        """Test a specific LFI path against all params."""
        if not self.deep: return
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p, path) in tested: continue
                tested.add((url, p, path))
                test_url = self._inject(url, p, path)
                r = self._get(test_url)
                if r:
                    body = r.text or ""
                    if path.startswith("/etc/") and "root:" in body and "/bin/" in body:
                        self._add_vuln(f"LFI ({description})", "CRITICAL",
                                        test_url, f"{p}={path}",
                                        param=p, payload=path)
                    elif path.startswith("/proc/") and "USER=" in body:
                        self._add_vuln(f"LFI ({description})", "CRITICAL",
                                        test_url, f"{p}={path}",
                                        param=p, payload=path)
                    elif path.startswith("/var/log/") and any(kw in body for kw in
                                                                  ["GET /", "POST /", "PUT /"]):
                        self._add_vuln(f"LFI ({description})", "HIGH",
                                        test_url, f"{p}={path}",
                                        param=p, payload=path)
                    elif path.startswith("C:/") and ("[fonts]" in body.lower() or
                                                       "extensions" in body.lower()):
                        self._add_vuln(f"LFI ({description})", "CRITICAL",
                                        test_url, f"{p}={path}",
                                        param=p, payload=path)

