    def test_insecure_deserialization(self):
        """Insecure Deserialization — Java/PHP/Python/.NET."""
        if not self.deep: return
        self._print("[*]", "Insecure Deserialization testing...", "INFO")
        # PHP unserialize payloads
        php_payloads = [
            'O:4:"User":1:{s:4:"role";s:5:"admin";}',
            'O:4:"User":1:{s:4:"name";s:4:"test";}',
            'a:1:{s:4:"role";s:5:"admin";}',
            'O:8:"stdClass":1:{s:3:"cmd";s:2:"id";}',
        ]
        # Java payloads (base64-encoded serialized objects)
        java_payloads = [
            'rO0ABXNyABFqYXZhLnV0aWwuSGFzaE1hcAUH2sHDFemDAAAAAAB4',
            'aced0005737200116a6176612e6c616e672e496e7465676572',
        ]
        # Python pickle payloads
        python_payloads = [
            "gASVLgAAAAAAAACMBXh9lCiMCGkAAAAAAAF9lA==",
            "KlNieXMnJ1xucm9lJw==",
        ]
        endpoints = ["/api/", "/api/deserialize", "/api/load", "/deserialize.php",
                     "/api/objects", "/api/data"]
        for ep in endpoints:
            url = urljoin(self.target, ep)
            # PHP
            for payload in php_payloads:
                r = self._post(url, data={"data": payload})
                if r and ("admin" in (r.text or "").lower() and "error" not in (r.text or "").lower()):
                    self._add_vuln("PHP Deserialization", "CRITICAL",
                                    url, f"unserialize payload accepted",
                                    endpoint=ep, payload=payload[:60])
            # Java
            for payload in java_payloads:
                r = self._post(url, data={"data": payload})
                if r and r.status_code == 500 and ("ClassNotFoundException" in (r.text or "") or
                                                    "ObjectInputStream" in (r.text or "")):
                    self._add_vuln("Java Deserialization", "CRITICAL",
                                    url, "serialized object accepted",
                                    endpoint=ep, payload="base64-encoded")
            # Python
            for payload in python_payloads:
                r = self._post(url, data={"data": payload})
                if r and r.status_code == 500 and ("pickle" in (r.text or "").lower() or
                                                    "UnpicklingError" in (r.text or "")):
                    self._add_vuln("Python Deserialization", "CRITICAL",
                                    url, "pickle payload accepted",
                                    endpoint=ep, payload="base64-encoded")

