    def test_tls_analysis(self):
        """TLS Certificate — analyze for weaknesses."""
        self._print("[*]", "TLS certificate analysis...", "INFO")
        if not self.target.startswith("https"):
            return
        import ssl
        import socket as _socket
        try:
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            with _socket.create_connection((self.host, 443), timeout=10) as sock:
                with ctx.wrap_socket(sock, server_hostname=self.host) as ssock:
                    cert = ssock.getpeercert()
                    # Check expiry
                    not_after = cert.get("notAfter", "")
                    if not_after:
                        # Parse date
                        try:
                            expiry = time.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
                            days_left = (time.mktime(expiry) - time.time()) / 86400
                            if days_left < 30:
                                self._add_vuln(f"TLS Certificate expiring soon ({days_left:.0f} days)",
                                                "MEDIUM", self.target,
                                                f"notAfter={not_after}")
                            elif days_left < 0:
                                self._add_vuln("TLS Certificate EXPIRED", "HIGH",
                                                self.target, f"expired {abs(days_left):.0f} days ago")
                        except Exception:
                            pass
                    # Check for weak cipher
                    cipher = ssock.cipher()
                    if cipher:
                        cipher_name = cipher[0]
                        if any(weak in cipher_name for weak in ["RC4", "DES", "3DES", "MD5"]):
                            self._add_vuln(f"TLS Weak Cipher: {cipher_name}", "MEDIUM",
                                            self.target, f"cipher={cipher_name}")
                    # Check TLS version
                    version = ssock.version()
                    if version and "1.0" in version:
                        self._add_vuln("TLS 1.0 (deprecated)", "MEDIUM",
                                        self.target, f"version={version}")
                    elif version and "1.1" in version:
                        self._add_vuln("TLS 1.1 (deprecated)", "LOW",
                                        self.target, f"version={version}")
        except Exception:
            pass

    # ─── PERMISSIONS-POLICY ANALYSIS ────────────────────────────────────

    def test_response_time_entropy(self):
        """Response Time Entropy — detect blind vulns via timing."""
        if not self.deep: return
        self._print("[*]", "Response time entropy analysis...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                # Send 5 normal requests — measure timing
                times = []
                for _ in range(5):
                    t0 = time.time()
                    r = self._get(self._inject(url, p, "1"))
                    times.append(time.time() - t0)
                avg_normal = sum(times) / len(times)
                # Send 5 SLEEP-based requests
                times_sleep = []
                for _ in range(5):
                    t0 = time.time()
                    r = self._get(self._inject(url, p, "1' AND SLEEP(3)--"))
                    times_sleep.append(time.time() - t0)
                avg_sleep = sum(times_sleep) / len(times_sleep)
                # If SLEEP requests are significantly slower → blind SQLi
                if avg_sleep > avg_normal + 2.0:
                    self._add_vuln("Blind SQLi (time entropy analysis)", "HIGH",
                                    url, f"{p}: normal={avg_normal:.2f}s, sleep={avg_sleep:.2f}s",
                                    param=p, normal_time=f"{avg_normal:.2f}s",
                                    sleep_time=f"{avg_sleep:.2f}s")

