    def test_secret_scanning_all_responses(self):
        """Scan EVERY HTTP response body (not just JS) for leaked secrets."""
        self._print("[*]", "Secret scanning in all responses...", "INFO")
        # This runs on the home page + admin panels + sensitive files
        all_responses = []
        # Home page
        r = self._get(self.target)
        if r:
            all_responses.append(("homepage", r))
        # Admin panels
        for panel in self.results.get("admin_panels", [])[:10]:
            r = self._get(panel.get("url", ""))
            if r:
                all_responses.append((panel.get("url", ""), r))
        # Sensitive files
        for sf in self.results.get("sensitive_files", [])[:10]:
            r = self._get(sf.get("url", ""))
            if r:
                all_responses.append((sf.get("url", ""), r))
        # Scan each response
        all_patterns = [
            (r'AKIA[0-9A-Z]{16}', 'AWS Access Key'),
            (r'AIza[0-9A-Za-z_\-]{35}', 'Google API Key'),
            (r'ghp_[A-Za-z0-9]{36}', 'GitHub PAT'),
            (r'gho_[A-Za-z0-9]{36}', 'GitHub OAuth'),
            (r'xox[baprs]-[0-9A-Za-z-]{10,48}', 'Slack Token'),
            (r'sk_live_[0-9a-zA-Z]{24}', 'Stripe Live'),
            (r'sk-ant-[A-Za-z0-9_\-]{50,}', 'Anthropic Key'),
            (r'eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}', 'JWT Token'),
            (r'-----BEGIN (RSA|EC|OPENSSH|PGP) PRIVATE KEY-----', 'Private Key'),
            (r'mongodb(\+srv)?://[^:\s]+:[^@\s]+@[^\s"\'<>]+', 'MongoDB URL'),
            (r'postgres(ql)?://[^:\s]+:[^@\s]+@[^\s"\'<>]+', 'Postgres URL'),
            (r'redis://[^:\s]+:[^@\s]+@[^\s"\'<>]+', 'Redis URL'),
            (r'mysql://[^:\s]+:[^@\s]+@[^\s"\'<>]+', 'MySQL URL'),
            (r'password\s*[=:]\s*["\']([^"\'\s]{4,})["\']', 'Hardcoded Password'),
            (r'api[_-]?key\s*[=:]\s*["\']([A-Za-z0-9_\-]{16,})["\']', 'API Key'),
            (r'secret[_-]?key\s*[=:]\s*["\']([A-Za-z0-9_\-]{16,})["\']', 'Secret Key'),
            (r'access[_-]?token\s*[=:]\s*["\']([A-Za-z0-9_\-]{20,})["\']', 'Access Token'),
            (r'Bearer\s+[A-Za-z0-9_\-\.]{20,}', 'Bearer Token'),
            (r'ghp_[A-Za-z0-9]{36}', 'GitHub PAT'),
            (r'ghs_[A-Za-z0-9]{36}', 'GitHub App Secret'),
            (r'github_pat_[A-Za-z0-9_]{82}', 'GitHub PAT v2'),
            (r'glpat-[A-Za-z0-9_\-]{20}', 'GitLab PAT'),
            (r'xox[bpoa]-[0-9A-Za-z-]+', 'Slack Token alt'),
            (r'https://hooks\.slack\.com/services/T[A-Z0-9]+/B[A-Z0-9]+/[A-Za-z0-9]+', 'Slack Webhook'),
            (r'sk_test_[0-9a-zA-Z]{24}', 'Stripe Test'),
            (r'pk_live_[0-9a-zA-Z]{24}', 'Stripe Publishable'),
            (r'rk_live_[0-9a-zA-Z]{24}', 'Stripe Restricted'),
            (r'sk-[A-Za-z0-9]{20}T3BlbkJ[A-Za-z0-9]{20}', 'OpenAI Key'),
            (r'AAAA[A-Za-z0-9_\-]{43,}', 'Firebase Key'),
            (r'ya29\.[0-9A-Za-z_\-]+', 'Google OAuth Token'),
            (r'AIza[0-9A-Za-z_\-]{35}', 'Google API Key'),
            (r'[A-Za-z0-9_\-]{24}:[A-Za-z0-9_\-]{34}', 'Firebase Legacy'),
        ]
        for source_url, r in all_responses:
            body = r.text or ""
            for pattern, label in all_patterns:
                matches = re.findall(pattern, body)
                for match in matches[:3]:
                    secret = match if isinstance(match, str) else match[0]
                    if len(secret) > 8:
                        self._add_vuln(f"Secret in Response: {label}", "CRITICAL",
                                        source_url, f"secret={secret[:40]}...",
                                        secret=secret[:40], source=source_url)

    # ─── PII DETECTION ──────────────────────────────────────────────────────

    def test_pii_detection(self):
        """PII — detect SSN, credit cards, phone, IBAN, passport in responses."""
        self._print("[*]", "PII detection...", "INFO")
        r = self._get(self.target)
        if not r: return
        body = r.text or ""
        # SSN (US)
        ssns = re.findall(r'\b\d{3}-\d{2}-\d{4}\b', body)
        for s in list(set(ssns))[:3]:
            self._add_vuln("PII: SSN Detected", "HIGH", self.target,
                            f"SSN: {s[:3]}-XX-XXXX", pii_type="ssn")
        # Credit cards
        cards = re.findall(r'\b(?:4\d{3}|5[1-5]\d{2}|3[47]\d{2}|6(?:011|5\d{2}))\d{12}\b', body)
        for c in list(set(cards))[:3]:
            self._add_vuln("PII: Credit Card Detected", "HIGH", self.target,
                            f"card: {c[:6]}XXXXXX{c[-4:]}", pii_type="credit_card")
        # Phone numbers (US/EU)
        phones = re.findall(r'\b(?:\+?1[-.\s]?)?\(?[2-9]\d{2}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b', body)
        for p in list(set(phones))[:3]:
            self._add_vuln("PII: Phone Number Detected", "LOW", self.target,
                            f"phone: {p}", pii_type="phone")
        # IBAN
        ibans = re.findall(r'\b[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b', body)
        for i in list(set(ibans))[:3]:
            self._add_vuln("PII: IBAN Detected", "HIGH", self.target,
                            f"IBAN: {i[:4]}XXXX...{i[-4:]}", pii_type="iban")
        # Email (already handled but add here for completeness)
        # Passport numbers (various formats)
        passports = re.findall(r'\b[A-Z]{1,2}\d{7,9}\b', body)
        for p in list(set(passports))[:3]:
            if len(p) >= 8:
                self._add_vuln("PII: Passport Number (possible)", "MEDIUM",
                                self.target, f"passport: {p[:2]}XXXXXXX",
                                pii_type="passport")

