    def test_jwt_secret_brute(self):
        """JWT Secret Brute Force — try common JWT secrets."""
        if not self.deep: return
        self._print("[*]", "JWT secret brute force...", "INFO")
        common_secrets = [
            "secret", "password", "123456", "admin", "key",
            "jwt", "token", "auth", "your-secret-key",
            "your-secret-key-here", "secretkey", "mysecret",
            "jwt-secret", "jwt_secret", "JWT_SECRET",
            "supersecret", "changeme", "default",
            "your-256-bit-secret", "your-512-bit-secret",
            "your-1024-bit-secret", "your-2048-bit-secret",
            "your-4096-bit-secret", "secretkey123",
            "my_secret_key", "my-secret", "my_secret",
            "secret123", "secret1234", "secret12345",
            "notsecret", "verysecret", "topsecret",
            "SUPER_SECRET", "SUPERSECRET", "TOPSECRET",
            "THIS_IS_A_SECRET", "this_is_a_secret",
            "please-change-this", "change-this",
            "replace-this-with-your-own-secret",
            "this-is-a-secret-key",
            "this-is-my-secret-key",
            "abcd1234", "12345678", "87654321",
            "qwerty", "asdfgh", "zxcvbn",
            "letmein", "welcome", "monkey",
            "dragon", "master", "login",
            "princess", "abc123", "trustno1",
            "iloveyou", "sunshine", "football",
            "shadow", "michael", "passw0rd",
        ]
        for jwt_info in self.results.get("jwt_tokens", [])[:3]:
            token = jwt_info.get("token", "").replace("...", "")
            if not token or "." not in token:
                continue
            try:
                import hmac
                import hashlib
                parts = token.split(".")
                if len(parts) != 3:
                    continue
                header_b64 = parts[0]
                payload_b64 = parts[1]
                signature = parts[2]
                message = f"{header_b64}.{payload_b64}".encode()
                for secret in common_secrets:
                    sig = hmac.new(secret.encode(), message, hashlib.sha256).digest()
                    import base64
                    sig_b64 = base64.urlsafe_b64encode(sig).rstrip(b"=").decode()
                    if sig_b64 == signature:
                        self._add_vuln("JWT Secret Cracked!", "CRITICAL",
                                        self.target,
                                        f"secret='{secret}'",
                                        jwt_secret=secret)
                        break
            except Exception:
                pass

