    def test_response_anomaly_detection(self):
        """Zero-Day: baseline normal responses and flag ANY deviation."""
        if not self.deep: return
        self._print("[*]", "Response Anomaly Detection (zero-day)...", "INFO")
        # Baseline: send 5 normal requests, measure response size + time
        baselines = []
        for _ in range(5):
            t0 = time.time()
            r = self._get(self.target)
            dt = time.time() - t0
            if r:
                baselines.append({
                    "size": len(r.text or ""),
                    "time": dt,
                    "status": r.status_code,
                })
        if len(baselines) < 3:
            return
        avg_size = sum(b["size"] for b in baselines) / len(baselines)
        avg_time = sum(b["time"] for b in baselines) / len(baselines)
        # Now send "weird" inputs and check for anomalies
        weird_inputs = [
            ("null byte", "\x00"),
            ("negative number", "-1"),
            ("zero", "0"),
            ("very large", "999999999999999999999999999999"),
            ("float", "1.5"),
            ("NaN", "NaN"),
            ("Infinity", "Infinity"),
            ("true", "true"),
            ("false", "false"),
            ("null", "null"),
            ("empty", ""),
            ("whitespace", "   "),
            ("newline", "\n"),
            ("tab", "\t"),
            ("unicode", "\u0000\u0001\u0002"),
            ("array", "[1,2,3]"),
            ("object", "{\"a\":1}"),
            ("xml", "<x>1</x>"),
            ("sql", "' OR 1=1--"),
            ("xss", "<script>"),
            ("path", "../../../etc/passwd"),
            ("cmd", ";id"),
            ("ssrf", "http://169.254.169.254/"),
            ("ldap", "*)("),
            ("xpath", "' or '1'='1"),
            ("nosql", '{"$ne":null}'),
            ("ssi", "<!--#exec cmd=\"id\"-->"),
            ("template", "{{7*7}}"),
            ("crlf", "test\r\nSet-Cookie:injected=1"),
        ]
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                for label, payload in weird_inputs:
                    test_url = self._inject(url, p, payload)
                    t0 = time.time()
                    r = self._get(test_url)
                    dt = time.time() - t0
                    if not r: continue
                    resp_size = len(r.text or "")
                    # Anomaly: response size differs significantly from baseline
                    size_diff = abs(resp_size - avg_size)
                    if size_diff > 1000 and resp_size > 100:
                        self._add_vuln(
                            f"Response Anomaly ({label} on {p}) — possible zero-day",
                            "HIGH", test_url,
                            f"baseline={int(avg_size)}b, response={resp_size}b, diff={int(size_diff)}b",
                            param=p, payload=label, baseline_size=int(avg_size),
                            response_size=resp_size, size_diff=int(size_diff))
                    # Anomaly: response time differs significantly
                    if dt > avg_time + 3.0:
                        self._add_vuln(
                            f"Timing Anomaly ({label} on {p}) — possible blind vuln",
                            "MEDIUM", test_url,
                            f"baseline={avg_time:.2f}s, response={dt:.2f}s",
                            param=p, payload=label, baseline_time=f"{avg_time:.2f}s",
                            response_time=f"{dt:.2f}s")

