    def test_differential_fuzzing(self):
        """Zero-Day: mutate inputs and compare response diffs."""
        if not self.deep: return
        self._print("[*]", "Differential Fuzzing (zero-day)...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                # Send TRUE then FALSE — compare
                true_url = self._inject(url, p, "1")
                false_url = self._inject(url, p, "0")
                true_r = self._get(true_url)
                false_r = self._get(false_url)
                if not true_r or not false_r: continue
                t_len = len(true_r.text or "")
                f_len = len(false_r.text or "")
                # If TRUE returns different content than FALSE → boolean oracle
                if abs(t_len - f_len) > 500:
                    # Deep check: send more variations
                    variations = {
                        "true_str": "true",
                        "false_str": "false",
                        "yes": "yes",
                        "no": "no",
                        "on": "on",
                        "off": "off",
                        "1_str": "1",
                        "0_str": "0",
                        "empty": "",
                        "null": "null",
                        "array_true": "[true]",
                        "json_true": '{"val":true}',
                    }
                    responses = {}
                    for label, val in variations.items():
                        r = self._get(self._inject(url, p, val))
                        if r:
                            responses[label] = len(r.text or "")
                    # Check if responses cluster into 2 groups → boolean oracle
                    sizes = list(responses.values())
                    if len(sizes) >= 4:
                        med = sorted(sizes)[len(sizes)//2]
                        big = [s for s in sizes if s > med + 200]
                        small = [s for s in sizes if s < med - 200]
                        if len(big) >= 2 and len(small) >= 2:
                            self._add_vuln(
                                f"Differential Response on {p} — possible boolean blind injection",
                                "HIGH", url,
                                f"param={p}: responses cluster into 2 groups (big={len(big)}, small={len(small)})",
                                param=p, big_group=len(big), small_group=len(small))

