    def test_jwt_algorithm_confusion(self):
        """JWT Algorithm Confusion — RS256 → HS256 confusion attack."""
        if not self.deep: return
        self._print("[*]", "JWT Algorithm Confusion (RS256→HS256)...", "INFO")
        for jwt_info in self.results.get("jwt_tokens", [])[:3]:
            token = jwt_info.get("token", "").replace("...", "")
            if not token or "." not in token:
                continue
            try:
                import hmac
                import hashlib
                import base64
                parts = token.split(".")
                if len(parts) != 3:
                    continue
                header_b64 = parts[0]
                payload_b64 = parts[1]
                signature = parts[2]
                # Decode header
                pad = "=" * (-len(header_b64) % 4)
                header = json.loads(base64.urlsafe_b64decode(header_b64 + pad))
                # If original is RS256, try HS256 with public key
                if header.get("alg", "").upper() in ("RS256", "RS384", "RS512"):
                    # We don't have the public key, but flag the potential
                    self._add_vuln("JWT Algorithm Confusion (potential RS256→HS256)",
                                    "HIGH", self.target,
                                    "token uses RS256 — may be vulnerable to alg confusion",
                                    original_alg=header.get("alg"))
            except Exception:
                pass

