            url = urljoin(self.target, ep)
            t0 = time.time()
            r = self._post(url, data=xml_bomb,
                            headers={"Content-Type":"application/xml"})
            dt = time.time() - t0
            if r:
                if dt > 3:
                    self._add_vuln("XML Bomb (Billion Laughs) — slow response",
                                    "HIGH", url,
                                    f"took {dt:.1f}s — parser vulnerable to DoS",
                                    endpoint=ep, response_time=f"{dt:.1f}s")
                elif r.status_code == 500 and "entity" in (r.text or "").lower():
                    self._add_vuln("XML Bomb — parser error (entity expansion)",
                                    "HIGH", url,
                                    "entity expansion triggered 500",
                                    endpoint=ep)

