    def test_cookie_value_manipulation(self):
        """Cookie Value Manipulation — modify cookie values and observe."""
        if not self.deep: return
        self._print("[*]", "Cookie value manipulation...", "INFO")
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict()
        if not cookies:
            return
        for name, value in list(cookies.items())[:5]:
            # Try modifying the cookie value
            modified_value = value + "_tampered"
            r2 = self._get(self.target, cookies={name: modified_value})
            if not r2: continue
            # If response is the same size → cookie not validated
            if abs(len(r2.text or "") - len(r.text or "")) < 50:
                self._add_vuln(f"Cookie '{name}' — value not validated",
                                "MEDIUM", self.target,
                                f"cookie={name}: tampered value accepted",
                                cookie=name)
            # Try SQLi in cookie
            sqli_cookie = value + "' OR '1'='1"
            r3 = self._get(self.target, cookies={name: sqli_cookie})
            if r3:
                body = (r3.text or "").lower()
                for pat, db in SQLI_ERRORS:
                    if re.search(pat, body, re.I):
                        self._add_vuln(f"SQLi via cookie '{name}'", "HIGH",
                                        self.target,
                                        f"cookie={name}: SQLi error [{db}]",
                                        cookie=name, dbms=db)
                        break

