    def test_session_token_entropy(self):
        """Session Token Entropy — analyze session tokens for predictability."""
        if not self.deep: return
        self._print("[*]", "Session Token Entropy Analysis...", "INFO")
        # Collect 10 session tokens
        tokens = []
        for _ in range(10):
            r = self._get(self.target)
            if r:
                for cookie in r.cookies:
                    if cookie.name.lower() in ("session", "sessionid",
                                                "phpsessid", "jsessionid",
                                                "connect.sid", "token", "auth"):
                        tokens.append(cookie.value)
                        break
        if len(tokens) < 5:
            return
        # Analyze: check if tokens share common prefix
        if len(tokens) >= 3:
            prefix = os.path.commonprefix(tokens)
            if len(prefix) > len(tokens[0]) * 0.5:
                self._add_vuln("Session Token Predictable (common prefix)",
                                "HIGH", self.target,
                                f"tokens share {len(prefix)}-char prefix "
                                f"(>{len(tokens[0])*0.5:.0%} of token length)",
                                prefix_length=len(prefix))
        # Check token length
        avg_len = sum(len(t) for t in tokens) / len(tokens)
        if avg_len < 16:
            self._add_vuln("Session Token Too Short", "MEDIUM",
                            self.target,
                            f"average token length={avg_len:.0f} chars")

