    def test_api_response_schema(self):
        """API Response Schema — check for excessive data exposure."""
        self._print("[*]", "API Response Schema Analysis...", "INFO")
        api_endpoints = [
            "/api/users", "/api/me", "/api/profile",
            "/api/account", "/api/v1/users", "/api/v2/users",
            "/api/user", "/users", "/me",
        ]
        sensitive_fields = [
            "password", "passwd", "secret", "token", "api_key",
            "apikey", "private_key", "ssn", "credit_card",
            "card_number", "cvv", "pin", "salt", "hash",
            "verification_code", "otp", "2fa_code",
            "session_secret", "jwt_secret", "refresh_token",
            "access_token", "bearer_token",
        ]
        for ep in api_endpoints:
            url = urljoin(self.target, ep)
            r = self._get(url)
            if not r or r.status_code != 200:
                continue
            try:
                data = r.json()
                found_fields = []
                def check_keys(obj, prefix=""):
                    if isinstance(obj, dict):
                        for k, v in obj.items():
                            if any(s in k.lower() for s in sensitive_fields):
                                found_fields.append(f"{prefix}{k}")
                            check_keys(v, f"{prefix}{k}.")
                    elif isinstance(obj, list):
                        for item in obj[:3]:
                            check_keys(item, prefix)
                check_keys(data)
                if found_fields:
                    self._add_vuln(f"API Excessive Data Exposure ({ep})",
                                    "HIGH", url,
                                    f"sensitive fields: {found_fields}",
                                    endpoint=ep, fields=found_fields)
            except Exception:
                pass

