    def test_response_header_injection(self):
        """Response Header Injection — inject via various headers."""
        if not self.deep: return
        self._print("[*]", "Response Header Injection...", "INFO")
        marker = "hdrinj" + "".join(random.choices(string.ascii_lowercase, k=5))
        headers_to_inject = [
            ("X-Forwarded-Host", f"{marker}.attacker.com"),
            ("X-Forwarded-Proto", f"{marker}"),
            ("X-Forwarded-Server", f"{marker}.attacker.com"),
            ("X-Original-URL", f"/{marker}"),
            ("X-Rewrite-URL", f"/{marker}"),
            ("X-Custom-IP-Authorization", f"127.0.0.1"),
            ("X-Originating-IP", f"127.0.0.1"),
            ("X-Remote-IP", f"127.0.0.1"),
            ("X-Client-IP", f"127.0.0.1"),
            ("True-Client-IP", f"127.0.0.1"),
            ("CF-Connecting-IP", f"127.0.0.1"),
            ("X-Forwarded", f"127.0.0.1"),
            ("Forwarded-For", f"127.0.0.1"),
            ("Forwarded", f"for=127.0.0.1;host={marker}.attacker.com"),
        ]
        for hdr, val in headers_to_inject:
            r = self._get(self.target, headers={hdr: val})
            if not r: continue
            # Check if the value is reflected in response headers or body
            for resp_hdr, resp_val in r.headers.items():
                if marker in str(resp_val):
                    self._add_vuln(f"Response Header Injection via {hdr}",
                                    "HIGH", self.target,
                                    f"{hdr}: {val} → reflected in {resp_hdr}",
                                    header=hdr, reflected_header=resp_hdr)
            if marker in (r.text or ""):
                self._add_vuln(f"Header Injection in Body via {hdr}",
                                "HIGH", self.target,
                                f"{hdr}: {val} → reflected in body",
                                header=hdr)

