    def test_password_reset_token(self):
        """Password Reset Token — request 2 tokens and compare."""
        if not self.deep: return
        self._print("[*]", "Password reset token analysis...", "INFO")
        for ep in ["/forgot-password", "/password-reset", "/api/forgot-password"]:
            url = urljoin(self.target, ep)
            # Request 2 reset tokens
            r1 = self._post(url, data={"email": "admin@test.com"})
            r2 = self._post(url, data={"email": "admin@test.com"})
            if r1 and r2:
                # Check if tokens are in response
                token1 = re.search(r'token[=:]["\']?([a-zA-Z0-9_\-]{20,})', r1.text or "")
                token2 = re.search(r'token[=:]["\']?([a-zA-Z0-9_\-]{20,})', r2.text or "")
                if token1 and token2:
                    if token1.group(1) == token2.group(1):
                        self._add_vuln("Password Reset Token Reused (same token)",
                                        "HIGH", url,
                                        "same token returned for 2 requests",
                                        token1=token1.group(1)[:20])
                    elif len(token1.group(1)) < 16:
                        self._add_vuln("Password Reset Token Too Short",
                                        "MEDIUM", url,
                                        f"token length={len(token1.group(1))}",
                                        token_length=len(token1.group(1)))

