    def test_api_key_in_headers(self):
        """API Key in Response Headers — check response headers for secrets."""
        self._print("[*]", "API key in response headers...", "INFO")
        r = self._get(self.target)
        if not r: return
        secret_header_patterns = [
            (r'Bearer\s+[A-Za-z0-9_\-\.]{20,}', 'Bearer Token'),
            (r'[A-Za-z0-9_\-]{32,}', 'Long Key'),
            (r'eyJ[A-Za-z0-9_\-]{10,}', 'JWT in header'),
            (r'AKIA[0-9A-Z]{16}', 'AWS Key in header'),
            (r'ghp_[A-Za-z0-9]{36}', 'GitHub PAT in header'),
            (r'sk_live_[0-9a-zA-Z]{24}', 'Stripe Key in header'),
        ]
        for hdr_name, hdr_val in r.headers.items():
            for pattern, label in secret_header_patterns:
                if re.search(pattern, str(hdr_val)):
                    self._add_vuln(f"Secret in Response Header: {label}",
                                    "HIGH", self.target,
                                    f"header={hdr_name}: {hdr_val[:40]}...",
                                    header=hdr_name, secret_type=label)

