    def test_banner_grab(self):
        """Banner Grab — detect backend technology via banner."""
        self._print("[*]", "Banner grabbing...", "INFO")
        try:
            ip = socket.gethostbyname(self.host)
            # Try common ports and grab banners
            banner_ports = [21, 22, 25, 3306, 5432, 6379, 27017, 9200]
            for port in banner_ports:
                try:
                    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                        s.settimeout(3)
                        s.connect((ip, port))
                        if port == 21:
                            banner = s.recv(1024).decode("utf-8", "ignore")
                            if banner:
                                self._add_vuln(f"FTP Banner: {banner[:80]}",
                                                "LOW", self.target,
                                                f"port={port} banner={banner[:80]}",
                                                port=port, banner=banner[:80])
                        elif port == 22:
                            banner = s.recv(1024).decode("utf-8", "ignore")
                            if banner:
                                self._add_vuln(f"SSH Banner: {banner[:80]}",
                                                "LOW", self.target,
                                                f"port={port} banner={banner[:80]}",
                                                port=port, banner=banner[:80])
                        elif port == 25:
                            banner = s.recv(1024).decode("utf-8", "ignore")
                            if banner:
                                self._add_vuln(f"SMTP Banner: {banner[:80]}",
                                                "LOW", self.target,
                                                f"port={port} banner={banner[:80]}",
                                                port=port, banner=banner[:80])
                        elif port == 3306:
                            banner = s.recv(1024)
                            if banner:
                                self._add_vuln("MySQL Banner (version info leaked)",
                                                "LOW", self.target,
                                                f"port={port}",
                                                port=port)
                        elif port == 6379:
                            s.send(b"PING\r\n")
                            banner = s.recv(1024).decode("utf-8", "ignore")
                            if "PONG" in banner:
                                self._add_vuln("Redis responds to PING (unauth)",
                                                "CRITICAL", self.target,
                                                f"port={port} response={banner[:30]}",
                                                port=port, banner=banner[:30])
                        elif port == 9200:
                            s.send(b"GET / HTTP/1.0\r\n\r\n")
                            banner = s.recv(4096).decode("utf-8", "ignore")
                            if "cluster_name" in banner:
                                self._add_vuln("Elasticsearch (unauth) on port 9200",
                                                "CRITICAL", self.target,
                                                f"port={port}",
                                                port=port)
                except Exception:
                    pass
        except Exception:
            pass

