    def test_chain_attack_detection(self):
        """Chain Attack — detect when multiple issues can be chained into critical."""
        self._print("[*]", "Chain Attack Detection...", "INFO")
        vulns = self.results.get("vulnerabilities", [])
        # Check for chainable combinations
        has_sqli = any("SQLi" in v.get("type","") for v in vulns)
        has_xss = any("XSS" in v.get("type","") for v in vulns)
        has_ssrf = any("SSRF" in v.get("type","") for v in vulns)
        has_lfi = any("LFI" in v.get("type","") for v in vulns)
        has_cors = any("CORS" in v.get("type","") for v in vulns)
        has_default = any("Default Credentials" in v.get("type","") for v in vulns)
        has_idor = any("IDOR" in v.get("type","") for v in vulns)
        has_jwt = any("JWT" in v.get("type","") for v in vulns)
        # Chain: CORS + XSS = steal data from authenticated users
        if has_cors and has_xss:
            self._add_vuln("CHAIN: CORS + XSS = Cross-Origin Data Theft",
                            "CRITICAL", self.target,
                            "CORS allows evil origin + XSS = steal authenticated data")
        # Chain: SSRF + Internal metadata = cloud takeover
        if has_ssrf:
            self._add_vuln("CHAIN: SSRF → Cloud Metadata → Full Account Takeover",
                            "CRITICAL", self.target,
                            "SSRF can access cloud metadata endpoints for credentials")
        # Chain: LFI + Log Poisoning = RCE
        if has_lfi:
            self._add_vuln("CHAIN: LFI + Log Poisoning → RCE",
                            "CRITICAL", self.target,
                            "LFI can be combined with log poisoning for RCE")
        # Chain: IDOR + Default Creds = Account takeover
        if has_idor and has_default:
            self._add_vuln("CHAIN: IDOR + Default Credentials → Mass Account Takeover",
                            "CRITICAL", self.target,
                            "IDOR + default creds = access any user account")
        # Chain: JWT + XSS = Token theft
        if has_jwt and has_xss:
            self._add_vuln("CHAIN: JWT + XSS → Token Theft",
                            "HIGH", self.target,
                            "XSS can steal JWT tokens from cookies/storage")
        # Chain: SQLi + Default Creds = Database takeover
        if has_sqli and has_default:
            self._add_vuln("CHAIN: SQLi + Default Credentials → Database Takeover",
                            "CRITICAL", self.target,
                            "SQLi + admin access = full DB compromise")

