    def test_csp_nonce_analysis(self):
        """CSP Nonce — check if nonce is predictable or reused."""
        self._print("[*]", "CSP Nonce analysis...", "INFO")
        nonces = []
        for _ in range(3):
            r = self._get(self.target)
            if r:
                csp = r.headers.get("Content-Security-Policy", "")
                nonce_match = re.search(r"nonce-([A-Za-z0-9+/=_\-]{16,})", csp)
                if nonce_match:
                    nonces.append(nonce_match.group(1))
        if len(nonces) >= 2:
            if nonces[0] == nonces[1]:
                self._add_vuln("CSP Nonce Reused (same nonce across requests)",
                                "HIGH", self.target,
                                f"nonce={nonces[0][:20]} — same nonce reused")
            elif len(nonces[0]) < 16:
                self._add_vuln("CSP Nonce Too Short",
                                "MEDIUM", self.target,
                                f"nonce length={len(nonces[0])}")

