    def test_input_output_correlation(self):
        """Input-Output Correlation — track how input is reflected in output."""
        if not self.deep: return
        self._print("[*]", "Input-Output Correlation (supernova)...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:10]:
            for p in params:
                if (url, p) in tested: continue
                tested.add((url, p))
                # Send a unique marker and track where it appears
                marker = "iocorr" + "".join(random.choices(string.ascii_lowercase, k=8))
                r = self._get(self._inject(url, p, marker))
                if not r: continue
                body = r.text or ""
                if marker not in body:
                    continue
                # Count occurrences
                count = body.count(marker)
                # Check if marker appears in:
                # 1. HTML body (dangerous - XSS possible)
                in_html = marker in body
                # 2. HTML attribute (dangerous)
                in_attr = re.search(rf'\w+="[^"]*{marker}', body) is not None
                # 3. Script tag (dangerous)
                in_script = re.search(rf'<script[^>]*>[^<]*{marker}', body, re.I) is not None
                # 4. URL (dangerous - open redirect possible)
                in_url = re.search(rf'href=["\'][^"\']*{marker}', body, re.I) is not None
                # 5. Comment (less dangerous)
                in_comment = re.search(rf'<!--[^>]*{marker}', body) is not None
                # 6. JSON value (dangerous - XSS if Content-Type is HTML)
                in_json = re.search(rf'"[^"]*{marker}[^"]*"', body) is not None
                # 7. Meta tag
                in_meta = re.search(rf'<meta[^>]*content="[^"]*{marker}', body, re.I) is not None
                # 8. Title tag
                in_title = re.search(rf'<title>[^<]*{marker}', body, re.I) is not None
                if in_attr or in_script or in_url or in_meta:
                    self._add_vuln(f"Input reflected in dangerous position: {p}",
                                    "HIGH", url,
                                    f"param={p}: attr={in_attr} script={in_script} url={in_url} meta={in_meta} count={count}",
                                    param=p, in_attr=in_attr, in_script=in_script,
                                    in_url=in_url, in_meta=in_meta, occurrence_count=count)

    def test_blind_ssrf_timing(self):
        """Blind SSRF — detect via timing differences on different ports."""
        if not self.deep: return
        self._print("[*]", "Blind SSRF via timing (supernova)...", "INFO")
        tested = set()
        for url, params in list(self.params_seen)[:3]:
            for p in params:
                if p.lower() not in SSRF_PARAMS: continue
                if (url, p) in tested: continue
                tested.add((url, p))
                # Test open vs closed ports via timing
                # Open port (80) — should be fast
                t0 = time.time()
                self._get(self._inject(url, p, "http://127.0.0.1:80/"))
                t_open = time.time() - t0
                # Closed port (9999) — should be slow (timeout)
                t0 = time.time()
                self._get(self._inject(url, p, "http://127.0.0.1:9999/"))
                t_closed = time.time() - t0
                # If timing difference > 2s → SSRF (server is making outbound connections)
                if t_closed > t_open + 2.0:
                    self._add_vuln(f"Blind SSRF (timing) on {p}",
                                    "HIGH", url,
                                    f"open_port={t_open:.2f}s closed_port={t_closed:.2f}s diff={t_closed-t_open:.2f}s",
                                    param=p, open_time=f"{t_open:.2f}s", closed_time=f"{t_closed:.2f}s")

    def test_cookie_payload_matrix(self):
        """Cookie × Payload — inject payloads in every cookie."""
