    def test_zeroday_service_worker_hijack(self):
        """Zero-day #16 — Service Worker Hijack Detection.

        Detects if a service worker is registered and if its scope is
        broader than necessary (root scope = full hijack).
        """
        if not self.deep: return
        self._print("[*]", "Zero-day: Service Worker Hijack...", "INFO")
        import re
        r = self._get(self.target)
        if not r: return
        sw_matches = re.findall(
            r'serviceWorker\.register\s*\(\s*["\x27]([^"\x27]+)["\x27]\s*(?:,\s*\{[^}]*scope:\s*["\x27]([^"\x27]+)["\x27])?',
            r.text or "")
        for sw_path, scope in sw_matches:
            # default scope is the SW's directory
            effective_scope = scope or sw_path.rsplit("/", 1)[0] + "/"
            if effective_scope == "/":
                self._add_vuln(f"Zero-day Service Worker Root Scope: {sw_path}",
                                "HIGH", urljoin(self.target, sw_path),
                                f"SW registered with root scope → full page hijack.",
                                sw_path=sw_path)
            # check SW for fetch handler
            sw_url = urljoin(self.target, sw_path)
            sw_r = self._get(sw_url)
            if sw_r and 'fetch' in (sw_r.text or ""):
                self._add_vuln(f"Zero-day Service Worker Fetch Handler: {sw_path}",
                                "MEDIUM", sw_url,
                                f"SW intercepts network requests — verify integrity.",
                                sw_path=sw_path)

