    def test_zeroday_http2_rapid_reset(self):
        """Zero-day #22 — HTTP/2 Rapid Reset (CVE-2023-44487) Detection.

        Detects servers vulnerable to the HTTP/2 Rapid Reset DoS by
        observing how they handle rapidly-opened/closed streams.
        """
        if not self.deep: return
        self._print("[*]", "Zero-day: HTTP/2 Rapid Reset...", "INFO")
        try:
            import httpx
            client = httpx.Client(http2=True, verify=False)
            # Open and immediately close many streams
            import threading
            def abuse():
                try:
                    for _ in range(100):
                        req = client.get(self.target, timeout=2)
                except Exception: pass
            threads = [threading.Thread(target=abuse) for _ in range(5)]
            for t in threads: t.start()
            for t in threads: t.join(timeout=10)
            # After abuse, test if server is responsive
            r = self._get(self.target)
            if not r or r.status_code >= 500:
                self._add_vuln("Zero-day HTTP/2 Rapid Reset (CVE-2023-44487)",
                                "HIGH", self.target,
                                "Server became unresponsive after rapid stream reset.",
                                cve="CVE-2023-44487")
            client.close()
        except ImportError: pass

