        self._print("[*]", "Zero-day: DOM XSS Sink Discovery...", "INFO")
        import re
        sinks = [
            "innerHTML", "outerHTML", "insertAdjacentHTML",
            "document.write", "document.writeln",
            "eval", "setTimeout", "setInterval",
            "Function", "new Function",
            "location", "location.href", "location.replace",
            "location.assign", "location.search",
            "open", "window.open",
            "srcdoc", "postMessage",
            "URLSearchParams", "URL",
            "history.pushState", "history.replaceState",
            "element.setAttribute", "element.src",
            "jQuery.globalEval", "$.globalEval",
            "jQuery.parseHTML", "$.parseHTML",
            "document.domain",
            "navigator.registerProtocolHandler",
            "element.insertAdjacentHTML",
            "WebWorkers", "Worker",
            "fetch", "XMLHttpRequest",
            "WebSocket",
            "element.outerText",
        ]
        sources = [
            "location.search", "location.hash", "location.href",
            "document.referrer", "document.URL",
            "document.documentURI", "document.baseURI",
            "window.name", "window.history",
            "localStorage.getItem", "sessionStorage.getItem",
            "URLSearchParams", "URL",
            "navigator.userAgent", "navigator.language",
            "document.cookie", "postMessage",
            "IndexedDB",
        ]
        r = self._get(self.target)
        if not r: return
        js_files = re.findall(r'<script[^>]+src=["\x27]([^"\x27]+)["\x27]',
                                r.text or "")
