    def test_zeroday_pauli_exclusion(self):
        """Wave2 #17 — Pauli Exclusion Principle Test.

        Two simultaneous sessions can't occupy same state. If they
        can, it's a session collision vulnerability.
        """
        if not self.deep: return
        self._print("[*]", "Wave2: Pauli Exclusion Test...", "INFO")
        # Try logging in as same user from 2 sessions simultaneously
        import threading
        results = []
        def login(session, results, idx):
            try:
                r = session.post(urljoin(self.target, "/login"),
                                  data={"username": "admin", "password": "admin"},
                                  timeout=10, verify=False)
                results.append((idx, r.status_code, len(r.text or "")))
            except Exception as e:
                results.append((idx, -1, 0))
        s1 = requests.Session()
        s2 = requests.Session()
        t1 = threading.Thread(target=login, args=(s1, results, 1))
        t2 = threading.Thread(target=login, args=(s2, results, 2))
        t1.start(); t2.start()
        t1.join(); t2.join()
        # If both got 200, no exclusion → potential session collision
        if len(results) == 2 and results[0][1] == 200 and results[1][1] == 200:
            # Check if session IDs are the same (extremely unlikely normally)
            s1_id = s1.cookies.get("JSESSIONID") or s1.cookies.get("PHPSESSID") or s1.cookies.get("sessionid")
            s2_id = s2.cookies.get("JSESSIONID") or s2.cookies.get("PHPSESSID") or s2.cookies.get("sessionid")
            if s1_id and s2_id and s1_id == s2_id:
                self._add_vuln("Wave2 Pauli Violation (session collision)",
                                "HIGH", self.target,
                                "Two concurrent sessions got same session ID",
                                session_id=s1_id)

