    def test_zeroday_quantum_decoherence(self):
        """Wave2 #45 — Quantum Decoherence Test.

        Sends many parallel requests, checks if responses 'decohere'
        (diverge). If parallel requests cause different responses
        than sequential ones, race condition exists.
        """
        if not self.deep: return
        self._print("[*]", "Wave2: Quantum Decoherence...", "INFO")
        import threading
        # Sequential
        seq_responses = []
        for _ in range(5):
            r = self._get(self.target)
            if r: seq_responses.append((r.text or "")[:200])
        # Parallel
        par_responses = []
        def get_parallel(idx, results):
            r = self._get(self.target)
            if r: results.append((idx, (r.text or "")[:200]))
        threads = []
        for i in range(5):
            t = threading.Thread(target=get_parallel, args=(i, par_responses))
            threads.append(t); t.start()
        for t in threads: t.join()
        # Compare uniqueness
        seq_unique = len(set(seq_responses))
        par_unique = len(set(r[1] for r in par_responses))
        # If parallel has more unique responses, race condition
        if par_unique > seq_unique + 1:
            self._add_vuln("Wave2 Quantum Decoherence (race condition)",
                            "HIGH", self.target,
                            f"Parallel responses diverge ({par_unique} unique vs "
                            f"{seq_unique} sequential) — race condition",
                            parallel_unique=par_unique, sequential_unique=seq_unique)

