            "https://017700000001",  # octal
            "https://0x7f000001",  # hex
            "https://0177.0.0.1",  # partial octal
            "https://127.1",  # short
            "https://127.0.1",  # short
            # IPv6
            "https://[::]",
            "https://[0:0:0:0:0:0:0:1]",
            "https://[::ffff:127.0.0.1]",
