        """Wave2 Cloud #3 — GCP Storage Bucket Enumeration."""
        if not self.deep: return
        self._print("[*]", "Wave2: GCP Storage Enum...", "INFO")
        hostname = urlparse(self.target).hostname
        base = hostname.split(".")[0]
        buckets = [
            f"{hostname.replace('.', '-')}",
            f"{base}-prod", f"{base}-staging", f"{base}-dev",
            f"{base}-test", f"{base}-backup", f"{base}-data",
            f"{base}-static", f"{base}-media", f"{base}-uploads",
            f"{base}-assets", f"{base}-images", f"{base}-files",
            f"www.{hostname}", f"{hostname}-static",
            f"{base}-backups", f"{base}-logs",
            f"gcs.{hostname}", f"storage.{hostname}",
            f"static.{hostname}",
        ]
        for bucket in buckets[:20]:
            url = f"https://storage.googleapis.com/{bucket}/"
            try:
                r = requests.get(url, timeout=3, verify=False)
                if r and r.status_code in (200, 403):
                    # 403 with specific message means bucket exists but is private
                    if "AccessDenied" in (r.text or "") and "Unauthorized" in (r.text or ""):
                        # Bucket exists but access denied
                        self._add_vuln(f"Wave2 GCP Bucket Exists: {bucket}",
                                        "LOW", url,
                                        f"GCP bucket {bucket} exists (private)",
                                        bucket=bucket)
                    elif r.status_code == 200:
                        if "ListBucketResult" in (r.text or ""):
                            self._add_vuln(f"Wave2 GCP Bucket Public: {bucket}",
                                            "HIGH", url,
                                            f"GCP bucket {bucket} allows listing",
                                            bucket=bucket)
            except Exception: pass

