    def test_cloud_firebase_realtime_db(self):
        """Wave2 Cloud #5 — Firebase Realtime DB Open Access."""
        if not self.deep: return
        self._print("[*]", "Wave2: Firebase Realtime DB...", "INFO")
        r = self._get(self.target)
        if not r: return
        import re
        # Find Firebase project IDs in JS
        fb_urls = re.findall(r'https?://([a-z0-9-]+)\.firebaseio\.com',
                              r.text or "", re.IGNORECASE)
        fb_urls += re.findall(r'projectId["\']?\s*[:=]\s*["\']([^"\']+)["\']',
                               r.text or "", re.IGNORECASE)
        # Also try Firestore URLs
        fb_urls += re.findall(r'firestore\.googleapis\.com/v1/projects/([^/]+)',
                               r.text or "")
        # Add common project IDs based on hostname
        hostname = urlparse(self.target).hostname
        base = hostname.split(".")[0]
        fb_urls += [base, f"{base}-prod", f"{base}-dev", f"{base}-staging"]
        for fb in set(fb_urls):
            # Try REST access to Firebase
            url = f"https://{fb}.firebaseio.com/.json"
            try:
                r2 = requests.get(url, timeout=3, verify=False)
                if r2 and r2.status_code == 200 and r2.text.strip() != "null":
                    self._add_vuln(f"Wave2 Firebase Open: {fb}",
                                    "CRITICAL", url,
                                    f"Firebase RTDB {fb} is publicly readable",
                                    firebase=fb, sample=r2.text[:100])
            except Exception: pass
            # Try Firestore REST
            url2 = f"https://firestore.googleapis.com/v1/projects/{fb}/databases/(default)/documents"
            try:
                r3 = requests.get(url2, timeout=3, verify=False)
                if r3 and r3.status_code == 200 and "documents" in (r3.text or ""):
                    self._add_vuln(f"Wave2 Firestore Open: {fb}",
                                    "CRITICAL", url2,
                                    f"Firestore {fb} is publicly readable",
                                    firebase=fb)
            except Exception: pass

