    def test_cms_wordpress_comprehensive(self):
        """Wave2 CMS #1 — WordPress Comprehensive Scan."""
        if not self.deep: return
        self._print("[*]", "Wave2: WordPress Comprehensive...", "INFO")
        wp_paths = [
            "/wp-login.php", "/wp-admin/",
            "/wp-content/", "/wp-content/uploads/",
            "/wp-content/plugins/", "/wp-content/themes/",
            "/wp-content/uploads/2024/", "/wp-content/uploads/2023/",
            "/wp-content/uploads/2022/",
            "/wp-json/", "/wp-json/wp/v2/users",
            "/wp-json/wp/v2/posts", "/wp-json/wp/v2/pages",
            "/wp-json/wp/v2/categories", "/wp-json/wp/v2/comments",
            "/wp-json/wp/v2/media", "/wp-json/wp/v2/users/1",
            "/wp-json/wp/v2/users/admin", "/wp-json/oembed/1.0/embed",
            "/?author=1", "/?author=2", "/?author=3",
            "/?p=1", "/?page_id=1",
            "/wp-includes/", "/wp-includes/version.php",
            "/xmlrpc.php", "/xmlrpc.php?rsd",
            "/readme.html", "/license.txt",
            "/wp-config.php", "/wp-config.php.bak",
            "/wp-config.php.old", "/wp-config.php.save",
            "/wp-config.php~", "/.wp-config.php.swp",
            "/wp-config-sample.php",
            "/wp-content/debug.log", "/wp-content/backup/",
            "/wp-content/uploads/wpallimport/",
            "/wp-content/backups/", "/wp-content/upgrade/",
            "/wp-content/cache/", "/wp-content/wflogs/",
            "/wp-content/uploads/index.php",
            "/wp-content/plugins/akismet/",
            "/wp-content/plugins/contact-form-7/",
            "/wp-content/plugins/jetpack/",
            "/wp-content/plugins/yoast-seo/",
            "/wp-content/plugins/elementor/",
            "/wp-content/plugins/wordfence/",
            "/wp-content/plugins/wpforms/",
            "/wp-content/plugins/gravityforms/",
            "/wp-content/plugins/duplicator/",
            "/wp-content/plugins/all-in-one-wp-migration/",
            "/wp-content/plugins/wp-file-manager/",
            "/wp-content/plugins/file-manager-advanced/",
            "/wp-content/plugins/wpdiscuz/",
            "/wp-content/plugins/thrive-leads/",
            "/wp-content/plugins/buddypress/",
            "/wp-content/plugins/woocommerce/",
            "/wp-content/plugins/wp-job-manager/",
            "/wp-content/plugins/event-calendar/",
            "/wp-content/plugins/the-events-calendar/",
        ]
        for path in wp_paths:
            url = urljoin(self.target, path)
            r = self._get(url, timeout=3)
            if not r: continue
            txt = r.text or ""
            # WordPress indicators
            if "wp-login" in path.lower() and r.status_code in (200, 301):
                self._add_vuln(f"Wave2 WordPress Login: {path}",
                                "LOW", url,
                                f"WordPress login found at {path}",
                                path=path)
            if "wp-json" in path and r.status_code == 200:
                if "users" in path and "id" in txt:
                    self._add_vuln(f"Wave2 WordPress User Enum: {path}",
                                    "MEDIUM", url,
                                    f"WordPress user enumeration via {path}",
                                    path=path)
            if "wp-config" in path and r.status_code == 200:
                self._add_vuln(f"Wave2 WordPress Config Leak: {path}",
                                "CRITICAL", url,
                                f"WordPress config exposed at {path}",
                                path=path)
            if "xmlrpc.php" in path and r.status_code == 200:
                if "XML-RPC" in txt or "method" in txt.lower():
                    self._add_vuln(f"Wave2 WordPress XML-RPC: {path}",
                                    "MEDIUM", url,
                                    f"WordPress XML-RPC enabled at {path}",
                                    path=path)
            if "debug.log" in path and r.status_code == 200:
                self._add_vuln(f"Wave2 WordPress Debug Log: {path}",
                                "HIGH", url,
                                f"WordPress debug log exposed at {path}",
                                path=path)
            if path.endswith("readme.html") and r.status_code == 200:
                self._add_vuln(f"Wave2 WordPress Readme: {path}",
                                "LOW", url,
                                f"WordPress readme exposed (version info)",
                                path=path)

