    def test_ai_ml_api_key_leak(self):
        """Wave4 AI #1 — AI/ML API Key Leak Detection.

        Detects leaked API keys for AI services (OpenAI, Anthropic,
        HuggingFace, Replicate, Cohere, etc.) in JavaScript.
        """
        if not self.deep: return
        self._print("[*]", "Wave4: AI/ML API Key Leak...", "INFO")
        import re
        r = self._get(self.target)
        if not r: return
        # Find JS files
        js_files = re.findall(r'<script[^>]+src=["\x27]([^"\x27]+\.js)["\x27]',
                                r.text or "")
        all_text = r.text or ""
        # Fetch JS files
        for jsf in js_files[:5]:
            js_url = urljoin(self.target, jsf)
            jr = self._get(js_url, timeout=5)
            if jr:
                all_text += "\n" + (jr.text or "")
        # AI API key patterns
        ai_patterns = [
            (r'sk-[a-zA-Z0-9]{48}', "OpenAI API key"),
            (r'AIza[0-9A-Za-z\-_]{35}', "Google AI API key"),
            (r'claude-[a-zA-Z0-9]+', "Anthropic API key"),
            (r'hf_[a-zA-Z0-9]+', "HuggingFace token"),
            (r'r8_[a-zA-Z0-9]+', "Replicate API token"),
            (r'COHERE_[A-Z_]+\s*[:=]\s*["\x27]([a-zA-Z0-9]+)["\x27]', "Cohere API key"),
            (r'openai\.api\.com', "OpenAI endpoint"),
            (r'api\.anthropic\.com', "Anthropic endpoint"),
            (r'huggingface\.co/api', "HuggingFace API"),
            (r'replicate\.com/api', "Replicate API"),
        ]
        for pattern, label in ai_patterns:
            matches = re.findall(pattern, all_text)
            if matches:
                self._add_vuln(f"Wave4 AI API Key Leak: {label}",
                                "CRITICAL", self.target,
                                f"{label} found in JavaScript",
                                pattern=pattern, sample=str(matches[0])[:30])

