    def test_sidechannel_compression_ratio(self):
        """Wave4 Side-Channel #5 — CRIME/BREACH Compression Attacks.

        Detects endpoints that use compression + HTTPS, vulnerable
        to CRIME/BREACH data extraction.
        """
        if not self.deep: return
        self._print("[*]", "Wave4: Compression Side-Channel...", "INFO")
        # Send requests that should be compressed with same prefix
        # vs different prefix — measure if size differs
        try:
            # Send same content twice
            r1 = self._get(self.target, params={"q": "AAAAAAAAAAAAAAAA"})
            r2 = self._get(self.target, params={"q": "BBBBBBBBBBBBBBBB"})
            if not (r1 and r2): return
            # Check if compression used
            content_encoding = r1.headers.get("Content-Encoding", "")
            if "gzip" in content_encoding or "br" in content_encoding:
                # Test if size changes based on secret predictability
                # Send long random + specific
                r3 = self._get(self.target, params={"q": "AAAA" + "secret_token" + "AAAA"})
                r4 = self._get(self.target, params={"q": "AAAA" + "XXXXX_XXXXX" + "AAAA"})
                if r3 and r4:
                    s1 = len(r3.content)
                    s2 = len(r4.content)
                    if abs(s1 - s2) > 10:
                        self._add_vuln("Wave4 Compression Side-Channel (BREACH)",
                                        "HIGH", self.target,
                                        f"Response size differs based on secret match "
                                        f"({s1} vs {s2}) — BREACH attack possible",
                                        s1=s1, s2=s2)
        except Exception: pass

