    def test_recon_cdn_origin_discovery(self):
        """Wave4 Recon #1 — CDN Origin IP Discovery (20+ techniques)."""
        if not self.deep: return
        self._print("[*]", "Wave4: CDN Origin Discovery...", "INFO")
        import re, socket
        # Method 1: Look for IP in HTTP headers
        r = self._get(self.target)
        if r:
            for h in ["X-Originating-IP", "X-Forwarded-For",
                       "X-Real-IP", "CF-Connecting-IP", "True-Client-IP"]:
                v = r.headers.get(h, "")
                if v and re.match(r'\d+\.\d+\.\d+\.\d+', v):
                    self._add_vuln(f"Wave4 Origin IP Header: {h}",
                                    "HIGH", self.target,
                                    f"Origin IP leaked via header {h}: {v}",
                                    header=h, ip=v)
        # Method 2: Check DNS history (Censys, SecurityTrails)
        hostname = urlparse(self.target).hostname
        # Method 3: Try direct subdomain resolution (often bypasses CDN)
        bypass_subdomains = ["direct.", "origin.", "real.", "true.",
                              "backend.", "internal.", "old.", "new."]
        for prefix in bypass_subdomains:
            try:
                test_host = prefix + hostname
                ip = socket.gethostbyname(test_host)
                if ip:
                    self._add_vuln(f"Wave4 CDN Bypass Subdomain: {test_host}",
                                    "HIGH", test_host,
                                    f"Direct origin subdomain resolves to {ip}",
                                    subdomain=test_host, ip=ip)
            except Exception: pass

