    def test_w6_http2_specific(self):
        """W6 #1 — HTTP/2 Specific Attacks."""
        if not self.deep: return
        self._print("[*]", "W6: HTTP/2 Specific Attacks...", "INFO")
        try:
            import httpx
            client = httpx.Client(http2=True, verify=False, timeout=5)
            # Test HTTP/2 Rapid Reset (CVE-2023-44487)
            import threading
            responses = []
            def rapid_reset(idx):
                try:
                    r = client.get(self.target, timeout=3)
                    if r: responses.append(r.status_code)
                except Exception: pass
            threads = [threading.Thread(target=rapid_reset, args=(i,)) for i in range(20)]
            for t in threads: t.start()
            for t in threads: t.join(timeout=10)
            if len(responses) < 10:
                self._add_vuln("HTTP/2 Rapid Reset DoS (CVE-2023-44487)",
                                "HIGH", self.target,
                                "Server became unresponsive under rapid stream reset",
                                cve="CVE-2023-44487")
            client.close()
        except ImportError: pass

