    def test_w6_padding_oracle(self):
        """W6 #10 — Padding Oracle Attack."""
        if not self.deep: return
        self._print("[*]", "W6: Padding Oracle...", "INFO")
        # Test if server responds differently to valid vs invalid padding
        # in encrypted cookies/parameters
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        for cname, cval in cookies.items():
            if not cval or len(cval) < 16: continue
            # Try modifying the last byte of the cookie
            modified = cval[:-2] + ("00" if cval[-2:] != "00" else "01")
            r2 = self._get(self.target, cookies={cname: modified})
            if r2 and r2.status_code != r.status_code:
                self._add_vuln(f"Padding Oracle: {cname}",
                                "HIGH", self.target,
                                f"Cookie {cname} shows different response for modified padding",
                                cookie=cname)

