    def test_w6_tls_vulnerabilities(self):
        """W6 #12 — TLS Vulnerabilities (POODLE, BEAST, Heartbleed)."""
        if not self.deep: return
        self._print("[*]", "W6: TLS Vulnerabilities...", "INFO")
        import ssl, socket
        hostname = urlparse(self.target).hostname
        if not hostname: return
        try:
            ctx = ssl.create_default_context()
            sock = socket.create_connection((hostname, 443), timeout=5)
            ssock = ctx.wrap_socket(sock, server_hostname=hostname)
            cert = ssock.getpeercert()
            # Check for weak protocols
            version = ssock.version()
            if version and "TLSv1" == version:
                self._add_vuln("TLS 1.0 Enabled (POODLE/BEAST)",
                                "HIGH", self.target,
                                "Server supports TLS 1.0 — vulnerable to POODLE and BEAST attacks",
                                tls_version=version)
            elif version and "TLSv1.1" == version:
                self._add_vuln("TLS 1.1 Enabled (Deprecated)",
                                "MEDIUM", self.target,
                                "Server supports TLS 1.1 — deprecated and weak",
                                tls_version=version)
            ssock.close()
            sock.close()
        except Exception: pass

