    def test_w7_pauli_exclusion_v2(self):
        """W7 #27 — Pauli Exclusion v2 (session collision)."""
        if not self.deep: return
        self._print("[*]", "W7: Pauli Exclusion v2...", "INFO")
        import threading
        # Two concurrent logins — can both get same session ID?
        sessions = []
        def login(idx):
            s = requests.Session()
            try:
                r = s.post(urljoin(self.target, "/login"),
                            data={"username": "test", "password": "test"},
                            timeout=5, verify=False)
                if r:
                    sid = s.cookies.get("JSESSIONID") or s.cookies.get("PHPSESSID") or s.cookies.get("sessionid")
                    if sid: sessions.append((idx, sid))
            except Exception: pass
        threads = [threading.Thread(target=login, args=(i,)) for i in range(5)]
        for t in threads: t.start()
        for t in threads: t.join(timeout=10)
        if len(sessions) > 1:
            ids = [s[1] for s in sessions]
            if len(set(ids)) < len(ids):
                self._add_vuln("W7 Pauli Exclusion Violation (session collision)",
                                "CRITICAL", self.target,
                                f"Duplicate session IDs: {len(ids) - len(set(ids))} collisions in {len(ids)} sessions",
                                collisions=len(ids) - len(set(ids)))

