    def test_w8_entropy_gradient_v3(self):
        """W8 #46 — Entropy Gradient v3 (data leak detection)."""
        if not self.deep: return
        self._print("[*]", "W8: Entropy v3...", "INFO")
        import math
        from collections import Counter
        base_r = self._get(self.target)
        if not base_r or not base_r.text: return
        def shannon(text):
            if not text: return 0
            cnt = Counter(text[:5000])
            total = len(text[:5000])
            return -sum((c/total) * math.log2(c/total) for c in cnt.values())
        base_e = shannon(base_r.text)
        probes = ["'", '"', "<", "${", "{{", "%00",
                   "1' OR '1'='1", "<script>alert(1)</script>"]
        for p in probes:
            r = self._get(self.target, params={"q": p})
            if not r or not r.text: continue
            cur_e = shannon(r.text)
            if abs(cur_e - base_e) > 1.5 and len(r.text) > 1000:
                self._add_vuln(f"W8 Entropy Gradient: '{p[:20]}'",
                                "HIGH", self.target,
                                f"Entropy shifted {abs(cur_e-base_e):.2f} bits — data leak",
                                payload=p[:20], delta=abs(cur_e-base_e))

