    def test_w9_csp_nonce_reuse_v2(self):
        """W9 #15 — CSP Nonce Reuse Detection v2."""
        if not self.deep: return
        self._print("[*]", "W9: CSP Nonce Reuse v2...", "INFO")
        import re
        nonces = []
        for _ in range(4):
            r = self._get(self.target)
            if not r: continue
            csp = r.headers.get("Content-Security-Policy", "")
            m = re.search(r"nonce-([A-Za-z0-9+/=]{16,})", csp)
            if m: nonces.append(m.group(1))
            m2 = re.search(r"nonce=['\"]([A-Za-z0-9+/=]{16,})['\"]", r.text or "")
            if m2: nonces.append(m2.group(1))
        if len(nonces) > 1 and len(set(nonces)) < len(nonces):
            self._add_vuln("W9 CSP Nonce Reuse",
                            "HIGH", self.target,
                            f"CSP nonces reused ({len(nonces)} nonces, {len(set(nonces))} unique)",
                            nonces=len(nonces), unique=len(set(nonces)))

