        login_paths = ["/login", "/api/login", "/api/auth/login"]
        for path in login_paths:
            url = urljoin(self.target, path)
            # Try 5 rapid logins
            for i in range(5):
                r = self._post(url, data={"username": f"test{i}", "password": "wrong"},
                                timeout=3)
                if not r: break
                if "rate limit" in (r.text or "").lower() or r.status_code == 429:
                    # Try bypass with XFF
                    r2 = self._post(url, data={"username": "test", "password": "wrong"},
                                    headers={"X-Forwarded-For": f"10.0.0.{i}"}, timeout=3)
                    if r2 and r2.status_code != 429:
                        self._add_vuln(f"W9 Rate Limit Bypass via XFF: {path}",
                                        "HIGH", url,
                                        f"Rate limit bypassed via X-Forwarded-For at {path}",
                                        path=path)
                    break

