    def test_w10_subdomain_takeover_deep(self):
        """W10 #44 — Subdomain Takeover Deep."""
        if not self.deep: return
        self._print("[*]", "W10: Subdomain Takeover...", "INFO")
        takeover_sigs = {
            "AWS S3": "The specified bucket does not exist",
            "GitHub Pages": "There isn't a GitHub Pages site here",
            "Heroku": "No such app exists",
            "Azure": "404 Web Site not found",
            "Tumblr": "Whatever you were looking for doesn't exist",
            "Shopify": "Sorry, this shop is currently unavailable",
            "Fastly": "Fastly error: unknown domain",
            "Pantheon": "The gods are wise",
            "Ghost": "Domain is not configured",
            "Tilda": "Please renew your subscription",
            "Unbounce": "The requested URL was not found",
            "Webflow": "The page you are looking for doesn't exist",
        }
        r = self._get(self.target)
        if not r: return
        import re
        # Look for subdomain references in page
        subdomain_pattern = re.findall(
            r'https?://([a-z0-9.-]+\.' + re.escape(urlparse(self.target).hostname) + ')',
            r.text or "", re.IGNORECASE)
        for sub in set(subdomain_pattern)[:20]:
            sub_url = f"http://{sub}"
            try:
                r2 = requests.get(sub_url, timeout=3, verify=False)
                if not r2: continue
                for provider, sig in takeover_sigs.items():
                    if sig.lower() in (r2.text or "").lower():
                        self._add_vuln(f"W10 Subdomain Takeover: {sub} ({provider})",
                                        "HIGH", sub_url,
                                        f"Dangling CNAME → {provider} takeover possible",
                                        sub=sub, provider=provider)
            except Exception: pass

