    def test_w11_vnc_exposure(self):
        """W11 #3 — VNC Endpoint Exposure."""
        if not self.deep: return
        self._print("[*]", "W11: VNC Exposure...", "INFO")
        import socket
        hostname = urlparse(self.target).hostname
        for port in [5900, 5901, 5902, 5903]:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(2)
                    s.connect((hostname, port))
                    banner = s.recv(1024).decode('utf-8', errors='replace')
                if "RFB" in banner:
                    self._add_vuln(f"W11 VNC Exposed (port {port})",
                                    "HIGH", self.target,
                                    f"VNC server on port {port}: {banner.strip()[:40]}",
                                    port=port, banner=banner.strip()[:40])
            except Exception: pass

    def test_w11_ftp_anonymous(self):
        """W11 #4 — Anonymous FTP Access."""
        if not self.deep: return
        self._print("[*]", "W11: Anonymous FTP...", "INFO")
        import socket
        hostname = urlparse(self.target).hostname
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(5)
            s.connect((hostname, 21))
            banner = s.recv(1024).decode('utf-8', errors='replace')
            if "FTP" in banner or "220" in banner:
                s.send(b"USER anonymous\r\n")
                resp = s.recv(1024).decode('utf-8', errors='replace')
                s.send(b"PASS anonymous@\r\n")
                resp2 = s.recv(1024).decode('utf-8', errors='replace')
                s.close()
                if "230" in resp2:
                    self._add_vuln("W11 Anonymous FTP Access",
                                    "HIGH", self.target,
                                    f"Anonymous FTP login successful. Banner: {banner.strip()[:40]}",
                                    banner=banner.strip()[:40])
        except Exception: pass

