    def test_w11_cors_deep_v3(self):
        """W11 #19 — CORS Deep v3."""
        if not self.deep: return
        self._print("[*]", "W11: CORS Deep v3...", "INFO")
        target_host = urlparse(self.target).hostname
        origins = [
            f"https://evil.{target_host}",
            f"https://{target_host}.evil.com",
            f"https://{target_host}evil.com",
            "null",
            "https://localhost",
            "http://localhost",
            "https://127.0.0.1",
            "https://[::1]",
            "https://0.0.0.0",
            "https://2130706433",
            "https://017700000001",
            "https://0x7f000001",
            "https://127.1",
            f"https://{target_host}:443",
            f"https://{target_host}:80",
            f"http://{target_host}",
            f"https://{target_host}.",
            f"https://{target_host}..",
            f"https://*.{target_host}",
            f"https://{target_host}.*",
        ]
        for origin in origins:
            r = self._get(self.target, headers={"Origin": origin})
            if not r: continue
            acao = r.headers.get("Access-Control-Allow-Origin", "")
            acac = r.headers.get("Access-Control-Allow-Credentials", "")
            if acao == origin and acac.lower() == "true":
                self._add_vuln(f"W11 CORS Bypass: {origin}",
                                "HIGH", self.target,
                                f"Origin '{origin}' reflected with credentials",
                                origin=origin)

