    def test_w11_tls_deep_v2(self):
        """W11 #42 — TLS/SSL Deep v2."""
        if not self.deep: return
        self._print("[*]", "W11: TLS Deep v2...", "INFO")
        import ssl, socket
        hostname = urlparse(self.target).hostname
        if not hostname: return
        try:
            ctx = ssl.create_default_context()
            sock = socket.create_connection((hostname, 443), timeout=5)
            ssock = ctx.wrap_socket(sock, server_hostname=hostname)
            version = ssock.version()
            cipher = ssock.cipher()
            cert = ssock.getpeercert()
            ssock.close()
            sock.close()
            # Check TLS version
            if version in ("TLSv1", "TLSv1.1"):
                self._add_vuln(f"W11 Weak TLS: {version}",
                                "HIGH", self.target,
                                f"Server supports deprecated {version} — POODLE/BEAST attacks",
                                tls_version=version)
            # Check cipher strength
            if cipher and "RC4" in cipher[0]:
                self._add_vuln("W11 RC4 Cipher Enabled",
                                "HIGH", self.target,
                                f"Server supports RC4 cipher: {cipher[0]}")
            if cipher and "3DES" in cipher[0]:
                self._add_vuln("W11 3DES Cipher Enabled",
                                "MEDIUM", self.target,
                                f"Server supports 3DES cipher: {cipher[0]}")
            # Check cert validity
            if cert:
                not_after = cert.get("notAfter", "")
                if not_after:
                    import datetime
                    expiry = datetime.datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
                    days_left = (expiry - datetime.datetime.utcnow()).days
                    if days_left < 30:
                        self._add_vuln(f"W11 SSL Cert Expiring ({days_left}d)",
                                        "MEDIUM", self.target,
                                        f"Certificate expires in {days_left} days",
                                        days=days_left)
        except Exception: pass

