        if "http:" in csp:
            self._add_vuln("W11 CSP http: allowed",
                            "MEDIUM", self.target,
                            "CSP allows http: — MITM injection possible")
        if "*" in csp and "unsafe-inline" not in csp:
            self._add_vuln("W11 CSP wildcard",
                            "MEDIUM", self.target,
                            "CSP contains wildcard * — any source allowed")

