    def test_w11_csp_nonce_deep(self):
        """W11 #48 — CSP Nonce Reuse Deep."""
        if not self.deep: return
        self._print("[*]", "W11: CSP Nonce Deep...", "INFO")
        import re
        nonces = []
        for _ in range(4):
            r = self._get(self.target)
            if not r: continue
            csp = r.headers.get("Content-Security-Policy", "")
            m = re.search(r"nonce-([A-Za-z0-9+/=]{16,})", csp)
            if m: nonces.append(m.group(1))
        if len(nonces) > 1 and len(set(nonces)) < len(nonces):
            self._add_vuln("W11 CSP Nonce Reuse",
                            "HIGH", self.target,
                            f"CSP nonces reused ({len(nonces)} requests, {len(set(nonces))} unique)",
                            total=len(nonces), unique=len(set(nonces)))

