    def test_cve_2024_6387_openssh_regresshion(self):
        """CVE-2024-6387 — OpenSSH regreSSHion RCE (banner version check)."""
        if not self.deep: return
        self._print("[*]", "CVE-2024-6387: OpenSSH regreSSHion...", "INFO")
        try:
            host = self.host
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(6)
                if s.connect_ex((host, 22)) == 0:
                    banner = s.recv(1024).decode("utf-8", errors="ignore")
                    m = re.search(r"OpenSSH_(\d+)\.(\d+)(?:p(\d+))?", banner or "")
                    if m:
                        major, minor = int(m.group(1)), int(m.group(2))
                        # Vulnerable ranges: 8.5p1 - 9.7p1 (excl 9.8p1)
                        if (major == 8 and minor >= 5) or (major == 9 and 0 <= minor <= 7):
                            self._add_vuln("CVE-2024-6387 OpenSSH regreSSHion",
                                           "CRITICAL", self.target,
                                           "Vulnerable OpenSSH banner: " + banner.strip()[:80],
                                           cve="CVE-2024-6387", path=":22")
        except Exception:
            pass

