    def test_cve_2023_44487_http2_rapid_reset(self):
        """CVE-2023-44487 — HTTP/2 Rapid Reset DoS."""
        if not self.deep: return
        self._print("[*]", "CVE-2023-44487: HTTP/2 Rapid Reset DoS...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if not r: return
            srv = (r.headers or {}).get("server", "").lower()
            # Servers known vulnerable unless patched: nginx<1.25.3, nghttp2<1.57, h2o<2.2.5
            m = re.search(r"nghttp2/(\d+)\.(\d+)\.(\d+)", srv)
            if m and (int(m.group(1)), int(m.group(2)), int(m.group(3))) < (1, 57, 0):
                self._add_vuln("CVE-2023-44487 HTTP/2 Rapid Reset",
                               "HIGH", self.target,
                               "Server: " + r.headers.get("server", ""),
                               cve="CVE-2023-44487", path="/")
                return
            m = re.search(r"nginx/(\d+)\.(\d+)\.(\d+)", srv)
            if m and (int(m.group(1)), int(m.group(2)), int(m.group(3))) < (1, 25, 3):
                self._add_vuln("CVE-2023-44487 HTTP/2 Rapid Reset",
                               "HIGH", self.target,
                               "Server: " + r.headers.get("server", ""),
                               cve="CVE-2023-44487", path="/")
        except Exception:
            pass

