        try:
            # Ghostcat is on AJP port 8009; detect via TCP probe
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(5)
                if s.connect_ex((self.host, 8009)) == 0:
                    # Send a minimal AJP13 forward request
                    ajp_request = (
                        b"\x12\x34\x00\x05\x02\x00\x00"
                    )
                    try:
                        s.send(ajp_request)
                        resp = s.recv(1024)
                        if resp and len(resp) >= 4:
                            self._add_vuln("CVE-2020-1938 Tomcat Ghostcat",
                                           "HIGH", self.target,
                                           "AJP port 8009 reachable; Ghostcat vulnerable",
                                           cve="CVE-2020-1938", path=":8009")
                    except Exception:
                        pass
        except Exception:
            pass

