    def test_ai_openai_api_key_exposure(self):
        """Detect OpenAI API keys (sk-...) leaked in client-side JS."""
        if not self.deep: return
        self._print("[*]", "AI/OpenAI: scanning for sk- API key...", "INFO")
        try:
            pat = re.compile(r"sk-[A-Za-z0-9]{20,}")
            for path in ["/", "/index.js", "/static/js/main.js",
                         "/assets/index.js", "/app.js", "/main.js",
                         "/static/bundle.js", "/dist/main.js"]:
                url = urljoin(self.target, path)
                r = self._get(url, timeout=8)
                if r and pat.search(r.text or ""):
                    keys = pat.findall(r.text or "")
                    for k in keys[:3]:
                        self._add_vuln("OpenAI API Key Exposure", "CRITICAL",
                                       url, "OpenAI key found in JS: " + k[:10] + "...",
                                       category="ai", path=path)
                    return
        except Exception:
            pass

