    def test_aws_s3_bucket_public(self):
        """Check if AWS S3 bucket is publicly listable."""
        if not self.deep: return
        self._print("[*]", "AWS S3 bucket public listing...", "INFO")
        try:
            bucket_candidates = [self.host, self.host.replace(".", "-"),
                                 self.host.split(".")[0], "www." + self.host.split(".")[0]]
            for name in bucket_candidates:
                url = "https://%s.s3.amazonaws.com/" % name
                r = self._get(url, timeout=8)
                if r is not None and ("<ListBucketResult" in (r.text or "") or "Key" in (r.text or "")):
                    self._add_vuln("AWS S3 Public Bucket", "HIGH", url,
                                   "Bucket %s allows public listing" % name, bucket=name)
                url2 = "https://s3.amazonaws.com/%s/" % name
                r2 = self._get(url2, timeout=8)
                if r2 is not None and "<ListBucketResult" in (r2.text or ""):
                    self._add_vuln("AWS S3 Public Bucket", "HIGH", url2,
                                   "Path-style bucket %s public" % name, bucket=name)
        except Exception:
            pass

