        """Check S3 ACL for public-write grants."""
        if not self.deep: return
        self._print("[*]", "AWS S3 ACL write check...", "INFO")
        try:
            name = self.host.replace(".", "-")
            url = "https://%s.s3.amazonaws.com/?acl" % name
            r = self._get(url, timeout=8)
            if r is not None and ("WRITE" in (r.text or "") and "AllUsers" in (r.text or "")):
                self._add_vuln("AWS S3 ACL Public Write", "CRITICAL", url,
                               "ACL grants WRITE to AllUsers — bucket takeover possible", bucket=name)
                probe = url + "pwn-%s.txt" % hashlib.md5(self.host.encode()).hexdigest()[:8]
                self._put_probe = probe
        except Exception:
            pass

