    def test_jwt_weak_secret(self):
        """Test JWT with common weak secrets."""
        if not self.deep: return
        self._print("[*]", "JWT weak secret brute...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if r is None: return
            hdrs = {k.lower(): v for k, v in (r.headers or {}).items()}
            auth_hdr = hdrs.get("authorization", "")
            if not auth_hdr.startswith("Bearer "): return
            token = auth_hdr[7:]
            parts = token.split(".")
            if len(parts) != 3: return
            header = json.loads(base64.urlsafe_b64decode(parts[0] + "==").decode())
            if header.get("alg") not in ("HS256", "HS384", "HS512"): return
            weak_secrets = ["secret", "password", "123456", "key", "jwt-secret",
                            "your-256-bit-secret", "supersecret", "changeme"]
            import hmac
            signing_input = ("%s.%s" % (parts[0], parts[1])).encode()
            for sec in weak_secrets:
                sig = hmac.new(sec.encode(), signing_input, hashlib.sha256).digest()
                calc = base64.urlsafe_b64encode(sig).rstrip(b"=").decode()
                if calc == parts[2]:
                    self._add_vuln("JWT Weak Secret", "CRITICAL", self.target,
                                   "JWT signed with weak secret '%s'" % sec)
                    break
        except Exception:
            pass

