    def test_privacy_credit_card_regex_exposure(self):
        """Detect credit card numbers via regex (Luhn-validated)."""
        if not self.deep: return
        self._print("[*]", "Credit card number exposure...", "INFO")
        try:
            def _luhn(num):
                num = re.sub(r"\D", "", num)
                if len(num) < 13: return False
                s = 0
                alt = False
                for d in reversed(num):
                    n = int(d)
                    if alt:
                        n *= 2
                        if n > 9: n -= 9
                    s += n
                    alt = not alt
                return s % 10 == 0
            for path in ["/api/orders", "/api/payments", "/orders",
                         "/api/account", "/api/billing"]:
                url = urljoin(self.target, path)
                r = self._get(url, timeout=8)
                if r is None: continue
                body = (r.text or "")
                candidates = re.findall(r"\b(?:\d[ -]*?){13,19}\b", body)
                valid = [c for c in candidates if _luhn(c)]
                if r.status_code == 200 and valid:
                    self._add_vuln("Privacy: Credit Card Number Exposure", "CRITICAL",
                                   url,
                                   "Luhn-valid card number detected in response (masked)",
                                   compliance="PCI-DSS")
                    break
        except Exception:
            pass

