    def test_edge_cloudflare_origin_ip_bypass(self):
        """Cloudflare CDN bypass via direct origin IP."""
        if not self.deep: return
        self._print("[*]", "Cloudflare origin IP bypass...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if r is None: return
            is_cf = "cloudflare" in (r.headers.get("server") or "").lower() or \
                    "cf-ray" in {k.lower() for k in r.headers}
            if not is_cf: return
            # Try resolving the bare host directly (bypass CF)
            try:
                addrs = socket.getaddrinfo(self.host, 443)
            except Exception:
                addrs = []
            origin_candidates = []
            for fam, ty, proto, cn, sa in addrs:
                ip = sa[0]
                if ip.startswith("127.") or ip.startswith("10.") or \
                   ip.startswith("192.168."): continue
                origin_candidates.append(ip)
            for ip in origin_candidates[:3]:
                # Hit origin IP with Host header
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(8)
                    try:
                        s.connect((ip, 443))
                        ctx = ssl.create_default_context()
                        ctx.check_hostname = False
                        ctx.verify_mode = ssl.CERT_NONE
                        with ctx.wrap_socket(s, server_hostname=self.host) as ss:
                            req = ("GET / HTTP/1.1\r\nHost: " + self.host +
                                   "\r\nConnection: close\r\n\r\n")
                            ss.sendall(req.encode())
                            data = b""
                            while True:
                                chunk = ss.recv(4096)
                                if not chunk: break
                                data += chunk
                            text = data.decode("latin-1", "ignore")
                            if "200 OK" in text and "cf-ray" not in text.lower():
                                self._add_vuln("Edge: Cloudflare Origin IP Bypass", "HIGH",
                                               self.target,
                                               "Origin reachable directly at " + ip + " bypassing CF (no cf-ray)",
                                               origin_ip=ip)
                                break
                    except Exception:
                        pass
        except Exception:
            pass

