    def test_net_dns_zone_transfer(self):
        """Attempt DNS AXFR zone transfer."""
        if not self.deep: return
        self._print("[*]", "DNS zone transfer (AXFR)...", "INFO")
        try:
            import dns.resolver
            import dns.query
            import dns.zone
        except Exception:
            return
        try:
            ns_answers = dns.resolver.resolve(self.host, "NS")
            nss = [str(r.target) for r in ns_answers]
        except Exception:
            nss = [self.host]
        for ns_name in nss:
            try:
                z = dns.zone.from_xfr(dns.query.xfr(ns_name, self.host, timeout=8))
                if z and len(z.nodes) > 0:
                    names = list(z.nodes.keys())[:20]
                    self._add_vuln("Net: DNS Zone Transfer Allowed", "HIGH",
                                   "dns://" + ns_name,
                                   "AXFR of %s returned %d records: %s" %
                                   (self.host, len(z.nodes), str(names)),
                                   ns=ns_name, records=len(z.nodes))
                    return
            except Exception:
                continue

    def test_net_smb_v1_exposure(self):
        """Detect SMB v1 protocol exposure (port 445)."""
        if not self.deep: return
        self._print("[*]", "SMBv1 (445)...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 445))
                # SMBv1 NEGOTIATE
                req = (b"\x00\x00\x00\x2f" +
                       b"\xff\x53\x4d\x42" +  # SMB1 magic
                       b"\x72\x00\x00\x00\x00\x18\x53\xc8" +
                       b"\x00\x00\x00\x00\x00\x00\x00\x00" +
                       b"\x00\x00\x00\x00\x00\x00\x00\x00" +
                       b"\xff\xfe\x00\x00\x00\x00\x00\x62\x00\x02" +
                       b"\x00\x02\x00\x00\x00")
                s.send(req)
                data = s.recv(4096)
                if data and data[4:8] == b"\xff\x53\x4d\x42" and data[8] == 0x73:
                    self._add_vuln("Net: SMBv1 Exposure", "HIGH",
                                   "smb://" + self.host + ":445",
                                   "SMBv1 negotiate response received",
                                   port=445, proto="smb1")
        except Exception:
            pass

