    def test_net_ldap_directory_listing(self):
        """Attempt LDAP directory listing via anonymous bind."""
        if not self.deep: return
        self._print("[*]", "LDAP directory listing...", "INFO")
        try:
            import ldap3
        except Exception:
            return
        try:
            srv = ldap3.Server(self.host, port=389, get_info=ldap3.ALL)
            conn = ldap3.Connection(srv, auto_bind=True)
            if not conn.bind(): return
            if srv.info and srv.info.other:
                nc = srv.info.other.get("namingContexts", [])
                if nc:
                    if conn.search(nc[0], "(objectClass=*)", attributes=ldap3.ALL_ATTRIBUTES,
                                   size_limit=10):
                        entries = [e.entry_dn for e in conn.entries]
                        self._add_vuln("Net: LDAP Directory Listing", "HIGH",
                                       "ldap://" + self.host + ":389",
                                       "Anonymous listing of %s returned entries: %s" %
                                       (nc[0], str(entries)[:200]),
                                       port=389, proto="ldap")
            conn.unbind()
        except Exception:
            pass

