        """Detect NTP monlist amplifier (CVE-2013-5211)."""
        if not self.deep: return
        self._print("[*]", "NTP monlist amplifier...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                s.settimeout(8)
                # NTP monlist (opcode 42, request)
                req = (b"\x17\x00\x03\x2a" + b"\x00" * 4 * 6)
                s.sendto(req, (self.host, 123))
                data, _ = s.recvfrom(8192)
                if data and len(data) > 8 and data[0] & 0x07 == 0x17:
                    n_records = (len(data) - 4) // 72
                    if n_records > 0:
                        self._add_vuln("Net: NTP monlist Amplifier", "HIGH",
                                       "ntp://" + self.host + ":123",
                                       "NTP monlist returned %d entries (CVE-2013-5211)" % n_records,
                                       port=123, proto="ntp",
                                       cve="CVE-2013-5211", records=n_records)
        except Exception:
            pass

