    def test_net_ftp_bounce_scan(self):
        """Detect FTP bounce (PORT command to third-party)."""
        if not self.deep: return
        self._print("[*]", "FTP bounce scan...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 21))
                banner = s.recv(1024)
                if not banner: return
                # Login anonymous
                s.send(b"USER anonymous\r\n")
                s.recv(1024)
                s.send(b"PASS scanner@\r\n")
                resp = s.recv(1024)
                if b"230" not in resp: return
                # Try PORT command with arbitrary IP (probe only - don't actually scan)
                s.send(b"PORT 127,0,0,1,0,80\r\n")
                resp = s.recv(1024)
                if b"200" in resp:
                    self._add_vuln("Net: FTP Bounce Allowed", "HIGH",
                                   "ftp://" + self.host + ":21",
                                   "FTP server accepted PORT command to third-party IP: " + resp.decode(errors="ignore").strip(),
                                   port=21, proto="ftp")
        except Exception:
            pass

