    def test_crypto_ccs_injection(self):
        """Detect CCS injection (CVE-2014-0224)."""
        if not self.deep: return
        self._print("[*]", "CCS injection (CVE-2014-0224)...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 443))
                # Send TLS 1.0 ClientHello
                client_hello = (b"\x16\x03\x01\x00\x31" +
                                b"\x01\x00\x00\x2d\x03\x01" + b"\x00" * 32 +
                                b"\x00\x00\x04\x00\x2f\x00\x35\x01\x00")
                s.send(client_hello)
                resp = s.recv(4096)
                if not resp: return
                # Send early ChangeCipherSpec
                ccs = b"\x14\x03\x01\x00\x01\x01"
                s.send(ccs)
                data = s.recv(4096)
                # If server accepts early CCS, vulnerable
                if data and (data[0] == 0x14 or data[0] == 0x15):
                    if data[0] == 0x14:
                        self._add_vuln("Crypto: CCS Injection (CVE-2014-0224)", "HIGH",
                                       "tls://" + self.host + ":443",
                                       "Server accepted early CCS",
                                       port=443, proto="tls", cve="CVE-2014-0224")
        except Exception:
            pass

