    def test_crypto_drown_attack(self):
        """Detect DROWN (SSLv2 cross-protocol)."""
        if not self.deep: return
        self._print("[*]", "DROWN attack...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 443))
                # Try SSLv2 ClientHello
                client_hello = (b"\x80\x30\x01\x00\x02\x00\x00\x00" +
                                b"\x00" * 16 +  # cipher specs (3DES + RC4)
                                b"\x07\x05\xc0\x03" +
                                b"\x00" * 16)  # challenge
                s.send(client_hello)
                data = s.recv(2048)
                if data and data[0] == 0x80 and len(data) >= 3:
                    # Server replied with SSLv2 ServerHello
                    self._add_vuln("Crypto: DROWN (SSLv2 on HTTPS)", "CRITICAL",
                                   "tls://" + self.host + ":443",
                                   "Server accepts SSLv2 handshake on port 443",
                                   port=443, proto="ssl", cve="CVE-2016-0800")
        except Exception:
            pass

