    def test_crypto_weak_rng(self):
        """Probe for weak random number generator (predictable tokens)."""
        if not self.deep: return
        self._print("[*]", "Weak RNG...", "INFO")
        try:
            tokens = []
            for _ in range(5):
                url = urljoin(self.target, "/")
                r = self._get(url, timeout=8)
                if r is None: return
                for h in ["X-CSRF-Token", "X-CSRF", "X-XSRF-Token",
                          "Set-Cookie"]:
                    val = r.headers.get(h)
                    if val:
                        # Extract token-like string
                        m = re.search(r"[A-Za-z0-9+/=_-]{16,}", val)
                        if m:
                            tokens.append(m.group())
                            break
                time.sleep(0.1)
            if len(tokens) >= 3:
                # Check entropy
                uniq = len(set(tokens))
                if uniq < len(tokens) - 1:
                    self._add_vuln("Crypto: Weak RNG (Repeated Tokens)", "HIGH",
                                   urljoin(self.target, "/"),
                                   "Repeated CSRF tokens detected: %d unique out of %d" % (uniq, len(tokens)))
        except Exception:
            pass

    def test_race_balance_transfer(self):
        """Test balance transfer race condition (double-spend)."""
        if not self.deep: return
        self._print("[*]", "Balance transfer race...", "INFO")
        try:
            url = urljoin(self.target, "/api/transfer")
            data = {"recipient": "self", "amount": "100"}
            # Send multiple parallel requests
            import concurrent.futures
            results = []
            with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
                futures = [ex.submit(self._post, url, data=data, timeout=8) for _ in range(10)]
                for f in concurrent.futures.as_completed(futures):
                    results.append(f.result())
            successes = sum(1 for r in results if r and r.status_code in (200, 201))
            if successes > 1:
                self._add_vuln("Race: Balance Transfer Race Condition", "CRITICAL",
                               url,
                               "Transfer succeeded %d times for same request (double-spend)" % successes,
                               successes=successes)
        except Exception:
            pass

