    def test_apt_watering_hole_cdn(self):
        """Detect watering hole via compromised CDN references."""
        if not self.deep: return
        self._print("[*]", "APT watering hole...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if r is None: return
            body = r.text or ""
            scripts = re.findall(r'<script[^>]+src=["\']([^"\']+)["\']', body, re.I)
            suspicious = []
            for s in scripts:
                if s.startswith("http") and self.host not in s:
                    if re.search(r'(cloudfront|jsdelivr|unpkg|cdnjs|bootstrapcdn)', s, re.I):
                        if any(x in s for x in [".ru/", ".cn/", ".tk/", "tmp/", "temp/", "test/", "demo/"]):
                            suspicious.append(s)
            if suspicious:
                self._add_vuln("APT: Suspicious CDN Script (Watering Hole?)", "HIGH",
                               self.target,
                               "Suspicious CDN-hosted script: " + suspicious[0][:200])
        except Exception:
            pass

