    def test_apt_spearphishing_landing_page(self):
        """Detect APT spear-phishing landing page."""
        if not self.deep: return
        self._print("[*]", "Spear-phishing landing...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if r is None: return
            body = r.text or ""
            phish_signals = 0
            if re.search(r'<form[^>]+action=["\']https?://', body, re.I):
                if "login" in body.lower() or "password" in body.lower() or \
                   "credential" in body.lower():
                    phish_signals += 2
            if "verify your account" in body.lower() or \
               "confirm your identity" in body.lower() or \
               "security alert" in body.lower() or \
               "update your information" in body.lower():
                phish_signals += 2
            if re.search(r'<input[^>]+type=["\']password["\']', body, re.I):
                phish_signals += 1
            if phish_signals >= 3:
                self._add_vuln("APT: Possible Spear-Phishing Landing", "HIGH",
                               self.target,
                               "Page exhibits spear-phishing landing characteristics (form+credential harvest+urgency)")
        except Exception:
            pass

    def test_apt_credential_harvesting_form(self):
        """Detect APT credential harvesting form."""
        if not self.deep: return
        self._print("[*]", "Credential harvesting form...", "INFO")
        try:
            r = self._get(self.target, timeout=8)
            if r is None: return
            body = r.text or ""
            forms = re.findall(r'<form[^>]*>.*?</form>', body, re.I | re.S)
            for f in forms:
                has_pwd = re.search(r'type=["\']password["\']', f, re.I)
                has_email = re.search(r'(type=["\']email["\']|name=["\']email["\']|name=["\']user["\'])', f, re.I)
                action_m = re.search(r'action=["\']([^"\']+)["\']', f, re.I)
                action = action_m.group(1) if action_m else ""
                if has_pwd and has_email and action:
                    if action.startswith("http") and self.host not in action:
                        self._add_vuln("APT: Credential Harvesting Form", "HIGH",
                                       self.target,
                                       "Form posts credentials to external URL: " + action[:200])
                        break
        except Exception:
            pass

