        """Test ZTNA identity-aware proxy bypass via header spoofing."""
        if not self.deep: return
        self._print("[*]", "ZTNA IAP bypass...", "INFO")
        try:
            spoof_headers = [
                {"X-Original-URL": "/admin"},
                {"X-Rewrite-URL": "/admin"},
                {"X-Forwarded-For": self.host},
                {"X-Remote-User": "admin"},
                {"X-Authenticated-User": "admin"},
                {"X-ZTNA-User": "admin"},
                {"X-IAP-User": "admin@example.com"},
                {"X-Authenticated-User-Email": "admin@example.com"},
            ]
            admin_url = urljoin(self.target, "/admin")
            base = self._get(admin_url, timeout=8)
            base_status = base.status_code if base else 0
            for hdrs in spoof_headers:
                r = self._get(admin_url, headers=hdrs, timeout=8)
                if r is None: continue
                if r.status_code == 200 and base_status in (401, 403):
                    self._add_vuln("ZTNA: IAP Bypass via Header Spoofing", "CRITICAL",
                                   admin_url,
                                   "Admin page accessed with header " + str(list(hdrs.keys())[0]),
                                   header=str(hdrs))
                    break
        except Exception:
            pass

