            fake_jwt = "eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9." + \
                       "eyJleHAiOjk5OTk5OTk5OTksInN1YiI6ImFkbWluIn0." + \
                       "fakesig"
