    def test_wcd_path_extension_css(self):
        """Web Cache Deception via .css path extension."""
        if not self.deep: return
        self._print("[*]", "WCD .css extension...", "INFO")
        try:
            paths = ["/profile", "/account", "/settings",
                     "/dashboard", "/user/profile", "/me",
                     "/account/settings", "/portal/account",
                     "/users/me", "/my-account", "/portal/profile",
                     "/home/account", "/secure/profile",
                     "/private/profile", "/user/dashboard"]
            for path in paths:
                url = urljoin(self.target, path)
                base = self._get(url, timeout=8)
                if base is None: continue
                if base.status_code != 200: continue
                base_body = base.text or ""
                if not any(t in base_body.lower() for t in
                          ["email", "account", "profile", "token",
                           "username", "private", "balance"]):
                    continue
                attack_url = urljoin(self.target, path + "/static.css")
                r = self._get(attack_url, timeout=8)
                if r is None: continue
                body = r.text or ""
                if r.status_code == 200 and \
                   len(body) > 50 and \
                   re.search(r"(email|account|profile|token|username|balance)",
                             body, re.I):
                    overlap = sum(1 for w in
                                 ["email","account","profile","token","username"]
                                 if w.lower() in body.lower())
                    if overlap >= 2:
                        self._add_vuln("Web Cache Deception (.css extension)",
                                       "HIGH", attack_url,
                                       "Sensitive content served from .css path - cacheable and identical to authenticated response: " + body[:200],
                                       method="GET", path=path)
                        break
        except Exception:
            pass

