    # Shared constants for Expansion Pack 10
    # =====================================================================

    _EP10_LFI_PARAMS = [
        "file", "page", "path", "template", "include", "doc", "document",
        "root", "pg", "style", "php_path", "filepath", "filename", "cat",
        "id", "show", "view", "read", "load", "lang", "module", "action",
        "src", "source", "dir", "name", "item", "body", "content", "data",
        "open", "get", "img", "image", "static", "resource", "uri", "url",
    ]

    _EP10_XML_ENDPOINTS = [
        "/", "/api", "/api/xml", "/xml", "/xmlrpc", "/import", "/upload",
        "/parse", "/api/v1/parse", "/soap", "/api/soap", "/feed", "/rss",
        "/api/saml", "/saml", "/api/upload", "/convert", "/api/convert",
    ]

    _EP10_REDIR_PARAMS = [
        "url", "redirect", "return", "returnUrl", "return_url", "next",
        "r", "rurl", "u", "goto", "dest", "destination", "redir",
        "redirectUrl", "redirect_url", "continue", "to", "from", "forward",
        "callback", "ref", "back", "link", "target", "go", "entry",
    ]

    def _ep10_resp_text(self, r):
        try:
            return (r.text or "") if r is not None else ""
        except Exception:
            return ""

    def _ep10_resp_headers(self, r):
        try:
            return r.headers or {}
        except Exception:
            return {}

    def _ep10_resp_status(self, r):
        try:
            return r.status_code
        except Exception:
            return 0

    def _ep10_header(self, headers, name):
        try:
            for k, v in headers.items():
                if k.lower() == name.lower():
                    return v or ""
            return ""
        except Exception:
            return ""

    def _ep10_check_external_redirect(self, loc, text, evil):
        """Return True if an external redirect to *evil* is detected."""
        try:
            ls = str(loc or "")
            if evil in ls:
                return True
            if re.search(r'<meta[^>]+http-equiv=["\']?refresh["\']?[^>]+content=["\'][^"\']*' + re.escape(evil), text or "", re.I):
                return True
            if re.search(r'(window\.location|location\.href|location\.replace|location\.assign)\s*=\s*["\'][^"\']*' + re.escape(evil), text or "", re.I):
                return True
            if evil in (text or ""):
                return True
        except Exception:
            return False
        return False

