    def _ep10_get_forms(self, text):
        """Return list of (action, method, fields) tuples parsed from HTML."""
        forms = []
        try:
            for m in re.finditer(r'<form[^>]*>', text, re.I):
                tag = m.group(0)
                am = re.search(r'action=["\']?([^"\'>\s]+)', tag, re.I)
                mm = re.search(r'method=["\']?([^"\'>\s]+)', tag, re.I)
                action = am.group(1) if am else ""
                method = (mm.group(1) if mm else "get").lower()
                end = text.find("</form>", m.end(), re.I)
                chunk = text[m.end():end] if end != -1 else text[m.end():m.end()+2000]
                fields = re.findall(r'<input[^>]+name=["\']?([^"\'>\s]+)', chunk, re.I)
                forms.append((action, method, fields))
        except Exception:
            pass
        return forms

    def _ep10_get_cookies(self, r):
        try:
            jar = getattr(r, "cookies", None)
            out = []
            if jar is None: return out
            for c in jar:
                out.append((c.name, c.value, c.domain, c.path))
            return out
        except Exception:
            return []

    def test_csrf_cors_preflight_bypass(self):
        """Test CORS preflight bypass for CSRF."""
        if not self.deep: return
        self._print("[*]", "csrf_cors_preflight_bypass...", "INFO")
        try:
            evil = "https://evil-" + hashlib.md5(b"preflight").hexdigest()[:8] + ".com"
            for ep in ["/api", "/api/user", "/api/update"]:
                u = urljoin(self.target, ep)
                pr = self._request("OPTIONS", u, headers={"Origin": evil, "Access-Control-Request-Method": "POST", "Access-Control-Request-Headers": "Content-Type"}, timeout=8)
                if pr is None: continue
                headers = self._ep10_resp_headers(pr)
                acao = self._ep10_header(headers, "Access-Control-Allow-Origin")
                acac = self._ep10_header(headers, "Access-Control-Allow-Credentials")
                if (acao == evil or acao == "*") and acac.lower() == "true":
                    self._add_vuln("CSRF (CORS preflight bypass)", "HIGH", u, "CORS reflects origin with credentials: ACAO=" + acao)
                    return
        except Exception:
            pass

