    def _ep10_redir_check(self, r, evil):
        """Check response for external redirect to *evil*."""
        try:
            if r is None: return False
            status = self._ep10_resp_status(r)
            headers = self._ep10_resp_headers(r)
            text = self._ep10_resp_text(r)
            loc = self._ep10_header(headers, "Location")
            if status in (301, 302, 303, 307, 308) and evil in str(loc):
                return True
            if self._ep10_check_external_redirect(loc, text, evil):
                return True
            return False
        except Exception:
            return False

