    def test_cat221_graphql_001(self):
        """GraphQL introspection at /graphql"""
        if not self.deep: return
        self._print("[*]", "test_cat221_graphql_001...", "INFO")
        try:
            payload = '{"query":"{__schema{types{name}}}"}'
            r = self._post(urljoin(self.target, "/graphql"), data=payload, timeout=8)
            if r and r.status_code == 200:
                txt = r.text or ""
                if "__schema" in txt or "__type" in txt:
                    self._add_vuln("GraphQL Introspection Enabled", "HIGH", urljoin(self.target, "/graphql"), "Introspection query returned schema", endpoint="/graphql")
                elif "errors" not in txt.lower() and len(txt) > 50:
                    self._add_vuln("GraphQL Unauthenticated Access", "MEDIUM", urljoin(self.target, "/graphql"), "GraphQL accessible without auth", endpoint="/graphql")
        except Exception:
            pass

