    def test_cat222_varnish_001(self):
        """Varnish cache at /"""
        if not self.deep: return
        self._print("[*]", "test_cat222_varnish_001...", "INFO")
        try:
            r = self._get(urljoin(self.target, "/"), timeout=8)
            if r:
                via = r.headers.get("Via", "")
                xcache = r.headers.get("X-Cache", "")
                if "varnish" in via.lower():
                    self._add_vuln("Varnish Cache Detected", "INFO", urljoin(self.target, "/"), f"Via: {via}", endpoint="/")
                if "varnish" in xcache.lower():
                    self._add_vuln("Varnish Cache Header", "LOW", urljoin(self.target, "/"), f"X-Cache: {xcache}", endpoint="/")
                if r.status_code == 200 and "purge" in "/":
                    self._add_vuln("Varnish Purge Accessible", "HIGH", urljoin(self.target, "/"), "Purge endpoint accessible", endpoint="/")
        except Exception:
            pass

