    def test_cat222_poison_001(self):
        """Cache poisoning via X-Forwarded-Host"""
        if not self.deep: return
        self._print("[*]", "test_cat222_poison_001...", "INFO")
        try:
            marker = hashlib.md5(b"poison0").hexdigest()[:12]
            r1 = self._get(urljoin(self.target, "/"), timeout=8)
            r2 = self._get(urljoin(self.target, "/"), timeout=8, headers={"X-Forwarded-Host": "evil.com"})
            r3 = self._get(urljoin(self.target, "/"), timeout=8)
            if r1 and r2 and r3:
                if r2.text and r2.text == r3.text and r1.text != r2.text:
                    self._add_vuln("Cache Poisoning", "HIGH", urljoin(self.target, "/"), f"Poisoned via X-Forwarded-Host", header="X-Forwarded-Host")
                cc = r1.headers.get("Cache-Control", "")
                if "no-store" not in cc and "private" not in cc:
                    self._add_vuln("Cacheable Dynamic Content", "MEDIUM", urljoin(self.target, "/"), f"Cache-Control: {cc}", header="X-Forwarded-Host")
        except Exception:
            pass

