    def test_cat242_pkce_bypass_00(self):
        """OAuth PKCE bypass at /oauth/authorize."""
        if not self.deep: return
        self._print("[*]", "test_cat242_pkce_bypass_00...", "INFO")
        try:
            r = self._get(urljoin(self.target, "/oauth/authorize"), params={'client_id':'test','redirect_uri':'http://evil.tld/cb','response_type':'code'}, timeout=8, allow_redirects=False)
            if r is not None and r.status_code in (302, 301):
                loc = r.headers.get('Location', '')
                if 'code=' in loc and 'code_challenge' not in str(r.url):
                    self._add_vuln("OAuth PKCE Bypass", "HIGH", urljoin(self.target, "/oauth/authorize"), "authz code issued without PKCE at /oauth/authorize")
        except Exception:
            pass

