    def test_cat251_rc4_020(self):
        """Detect weak RC4 cipher RC4-MD5 acceptance."""
        if not self.deep: return
        self._print("[*]", "test_cat251_rc4_020...", "INFO")
        try:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            ctx.set_ciphers("RC4-MD5")
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 443))
                with ctx.wrap_socket(s, server_hostname=self.host) as ss:
                    self._add_vuln("Weak Cipher (RC4-MD5)", "HIGH", 'https://' + self.host + ':443', "cipher accepted: RC4-MD5")
        except Exception:
            pass

