    def test_cat253_recursion_google_com_015(self):
        """Open DNS recursion check for google.com."""
        if not self.deep: return
        self._print("[*]", "test_cat253_recursion_google_com_015...", "INFO")
        try:
            header = b'\\xee\\xff\\x01\\x00\\x00\\x01\\x00\\x00\\x00\\x00\\x00\\x00'
            qname = b''
            for part in 'google.com'.split('.'):
                qname += bytes([len(part)]) + part.encode()
            qname += b'\\x00'
            query = header + qname + b'\\x00\\x01' + b'\\x00\\x01'
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                s.settimeout(8)
                s.sendto(query, (self.host, 53))
                try:
                    data, addr = s.recvfrom(4096)
                    if data and len(data) > 12:
                        self._add_vuln("Open DNS Recursion", "HIGH", 'dns://' + self.host + ':53', "open recursion for google.com")
                except Exception:
                    pass
        except Exception:
            pass

