    def test_cat257_gamesrc_005(self):
        """Game server probe on port 27020."""
        if not self.deep: return
        self._print("[*]", "test_cat257_gamesrc_005...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 27020))
                s.sendall(b'\x00\x00\x00\x00')
                banner = s.recv(4096)
                txt = banner.decode(errors='ignore').lower()
                if any(k in txt for k in ["rcon"]):
                    self._add_vuln("RCON Auth Probe", "HIGH", 'tcp://' + self.host + ':27020', "banner match on port 27020")
        except Exception:
            pass

