    def test_cat320_004_smtp_open_relay(self):
        """Test SMTP open relay"""
        if not self.deep: return
        self._print("[*]", "test_cat320_004_smtp_open_relay...", "INFO")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(8)
                s.connect((self.host, 25))
                s.recv(1024)
                s.sendall(b"MAIL FROM: <test@test>\r\n")
                s.recv(1024)
                s.sendall(b"RCPT TO: <relay@test>\r\n")
                data = s.recv(1024)
                if data and b"250" in data:
                    self._add_vuln("SMTP Open Relay", "CRITICAL", self.target, str(data)[:500])
        except Exception:
            pass

