# ─── CLOUD UPLOAD HELPER ────────────────────────────────────────────────────

CLOUD_UPLOAD_URL = "https://yousf3.lovable.app/api/public/files-api/upload"


def upload_report_to_cloud(filepath):
    """Upload a single file to yousf3.lovable.app cloud.
    The server rejects .py files; we append .txt if needed.
    Returns the file ID from the response, or None on failure."""
    if not os.path.exists(filepath):
        print(f"{C.RED}[!] upload: file not found: {filepath}{C.RESET}")
        return None
    filename = os.path.basename(filepath)
    # If .py extension, server rejects — rename for upload
    tmp_file = None
    upload_name = filename
    upload_path = filepath
    if filename.endswith(".py"):
        upload_name = filename + ".txt"
        tmp_file = f"/tmp/{upload_name}"
        try:
            shutil.copy(filepath, tmp_file)
            upload_path = tmp_file
        except Exception as e:
            print(f"{C.RED}[!] upload: rename failed: {e}{C.RESET}")
            return None
    try:
        with open(upload_path, "rb") as f:
            files = {"file": (upload_name, f)}
            data = {"name": upload_name}
            r = requests.post(CLOUD_UPLOAD_URL, files=files, data=data,
                                timeout=60, verify=True)
    except Exception as e:
        print(f"{C.RED}[!] upload: network error: {e}{C.RESET}")
        if tmp_file and os.path.exists(tmp_file):
            os.remove(tmp_file)
        return None
    # cleanup temp
    if tmp_file and os.path.exists(tmp_file):
        os.remove(tmp_file)
    if r.status_code not in (200, 201):
        print(f"{C.RED}[!] upload: HTTP {r.status_code} — {r.text[:100]}{C.RESET}")
        return None
    try:
        data = r.json()
        file_id = data.get("id")
        file_name = data.get("name")
        file_size = data.get("size")
        print(f"{C.GREEN}[☁️]  Uploaded: {file_name} ({file_size}b) "
              f"ID: {file_id}{C.RESET}")
        return file_id
    except Exception as e:
        print(f"{C.RED}[!] upload: parse error: {e}{C.RESET}")
        return None


# ─── TELEGRAM BOT CONFIGURATION ────────────────────────────────────────
TELEGRAM_BOT_TOKEN = "8590521968:AAEdfKhz7fuGUrDMZlOzRqS1fNlndSVTMKQ"
TELEGRAM_CHAT_ID = "8381536661"
TELEGRAM_API_BASE = "https://api.telegram.org/bot"


def send_report_to_telegram(filepath, caption=None):
    """Send a single report file to Telegram bot.
    Sends file as document with optional caption.
    Returns True on success, False on failure."""
    if not os.path.exists(filepath):
        print(f"{C.RED}[!] telegram: file not found: {filepath}{C.RESET}")
        return False
    filename = os.path.basename(filepath)
    file_size = os.path.getsize(filepath)
    # Telegram max file size is 50MB
    if file_size > 50 * 1024 * 1024:
        print(f"{C.RED}[!] telegram: file too large ({file_size}b > 50MB){C.RESET}")
        return False
    # Default caption with target info
    if caption is None:
        caption = f"📋 BugBounty Report\n📄 File: {filename}\n📊 Size: {file_size}b\n🕐 Generated: {time.strftime('%Y-%m-%d %H:%M:%S')}"
    url = f"{TELEGRAM_API_BASE}{TELEGRAM_BOT_TOKEN}/sendDocument"
    try:
        with open(filepath, "rb") as f:
            files = {"document": (filename, f)}
            data = {
                "chat_id": TELEGRAM_CHAT_ID,
                "caption": caption,
                "parse_mode": "HTML",
            }
            r = requests.post(url, files=files, data=data, timeout=120, verify=True)
    except Exception as e:
        print(f"{C.RED}[!] telegram: network error: {e}{C.RESET}")
        return False
    if r.status_code != 200:
        print(f"{C.RED}[!] telegram: HTTP {r.status_code} — {r.text[:200]}{C.RESET}")
        return False
    try:
        data = r.json()
        if data.get("ok"):
            msg_id = data.get("result", {}).get("message_id")
            print(f"{C.GREEN}[📨]  Telegram: sent {filename} (msg_id: {msg_id}){C.RESET}")
            return True
        else:
            print(f"{C.RED}[!] telegram: API error — {data}{C.RESET}")
            return False
    except Exception as e:
        print(f"{C.RED}[!] telegram: parse error: {e}{C.RESET}")
        return False


def send_telegram_message(text):
    """Send a text message to Telegram bot."""
    url = f"{TELEGRAM_API_BASE}{TELEGRAM_BOT_TOKEN}/sendMessage"
    try:
        data = {
            "chat_id": TELEGRAM_CHAT_ID,
            "text": text,
            "parse_mode": "HTML",
        }
        r = requests.post(url, data=data, timeout=30, verify=True)
        return r.status_code == 200 and r.json().get("ok", False)
    except Exception as e:
        print(f"{C.RED}[!] telegram: msg error: {e}{C.RESET}")
        return False


def send_reports_to_telegram(target_host, scan_summary=None, files=None):
    """Send all 3 report files (JSON, MD, PDF) to Telegram bot.
    Also sends a summary message first."""
    from html import escape as _html_escape
    if scan_summary is None:
        scan_summary = {}
    vuln_count = scan_summary.get("vuln_count", 0)
    critical = scan_summary.get("critical", 0)
    high = scan_summary.get("high", 0)
    medium = scan_summary.get("medium", 0)
    low = scan_summary.get("low", 0)
    _target_escaped = _html_escape(target_host or "", quote=True)
    summary = (
        f"🚨 <b>BugBounty Scan Complete</b> 🚨\n"
        f"\n"
        f"🎯 <b>Target:</b> <code>{_target_escaped}</code>\n"
        f"🕐 <b>Time:</b> {time.strftime('%Y-%m-%d %H:%M:%S')}\n"
        f"\n"
        f"📊 <b>Findings Summary:</b>\n"
        f"  🔴 CRITICAL: {critical}\n"
        f"  🟠 HIGH: {high}\n"
        f"  🟡 MEDIUM: {medium}\n"
        f"  🔵 LOW: {low}\n"
        f"  ━━━━━━━━━━\n"
        f"  <b>TOTAL: {vuln_count}</b>\n"
        f"\n"
        f"📤 Sending 3 report files..."
    )
    send_telegram_message(summary)
    # Send files
    if files is None:
        files = []
    success = 0
    for f in files:
        if send_report_to_telegram(f):
            success += 1
    # Final message
    final = (
        f"✅ <b>Reports Delivered</b>\n"
        f"📤 {success}/{len(files)} files sent to Telegram\n"
        f"📄 PDF + 📝 MD + 📊 JSON attached"
    )
    send_telegram_message(final)
    return success




